window.__D("text/maamarim-melukatim/c011",{"p":[[1500370057,"<h3>בס\"ד. ש\"פ וארא, מבה\"ח שבט, ה'תשל\"א<sup data-n=\"4188\">*</sup></h3>\n(הנחה בלתי מוגה)\n<b>וידבר</b> אלקים אל משה ויאמר אליו אני ה' וארא אל אברהם אל יצחק ואל יעקב גו' ושמי הוי' לא נודעתי להם<sup data-n=\"4189\">1</sup>. וידוע הדיוק<sup data-n=\"4190\">2</sup> בזה מבעל ההילולא במה שאומר ושמי הוי' לא נודעתי להם, הלא נאמר שם הוי' וכמה פעמים בדיבור להאבות, וכמו שהקשה בפירש\"י. גם צריך להבין מה שאומר כאן דוקא אני הוי', מה השייכות דשם הוי' ליצי\"מ ולמ\"ת (שקשורים זב\"ז, כמ\"ש<sup data-n=\"4191\">3</sup> בהוציאך את העם ממצרים תעבדון את האלקים על ההר הזה). והנה מהמבואר בד\"ה זה בתו\"א, מובן, שלהאבות נתגלה שם הוי' רק ע\"י שם אלקים, שבכללות הוא בחי' שם הוי' דלתתא, אבל שם הוי' דלעילא לא נודעתי להם, משא\"כ במ\"ת נתגלה שם הוי' שלמעלה מהתלבשות בשם אלקים, בחי' שם הוי' דלעילא. שלכן קודם מ\"ת הי' הגזירה<sup data-n=\"4192\">4</sup> שהעליונים לא ירדו לתחתונים והתחתונים לא יעלו לעליונים, ובמ\"ת ביטל הקב\"ה את הגזירה ואמר התחתונים יעלו לעליונים, והעליונים ירדו לתחתונים, ואני המתחיל, שנאמר<sup data-n=\"4193\">5</sup> וירד הוי' על הר סיני, וכתיב<sup data-n=\"4194\">6</sup> ואל משה אמר עלה אל ה'. וזהו מה שנאמר לו כאן אני הוי', שמתחיל גילוי חדש, שיתגלה שם הוי' שלמעלה מהתלבשות בשם אלקים, שם הוי' דלעילא.\nב) <b>ויש</b> לקשר זה עם מאמר מבעל ההילולא (שלא נדפס עדיין) ד\"ה אשרי יושבי ביתך<sup data-n=\"4195\">7</sup> [וכנראה שהמאמר ד\"ה זה שבסידור מאדמו\"ר האמצעי, מיוסד הוא על מאמר הנ\"ל, ובארוכה יותר נתבאר בפירוש המלות מאדמו\"ר האמצעי<sup data-n=\"4196\">8</sup>, ובפירוש המלות מהצ\"צ<sup data-n=\"4197\">9</sup> – בתוס' הערות ומ\"מ], שמבאר<sup data-n=\"4198\">10</sup> שם כל תפלת אשרי עד הפסוק קרוב הוי' לכל קוראיו (והמשך הפסוקים כבר נתבאר במקומות אחרים בדרושי אדמו\"ר הזקן). ותוכן ביאורו הוא, דאשרי הוא בחי' כתר עליון, שנקרא אשרי שהו\"עהתענוג (מלשון באשרי כי אשרוני בנות<sup data-n=\"4199\">11</sup>). וכן כתר עליון נקרא עתיק שהוא בחי' עונג העליון, וממנו מתלבש באו\"א הנקראים יושבי ביתך, שהם ב' הבתים דחכמה ובינה.\nג) <b>וממשיך</b> לבאר המזמור<sup data-n=\"4200\">12</sup> תהלה לדוד ארוממך אלקי המלך גו' (שמזמור זה הוא עיקר תפלת אשרי והוא סיבת אמירתה, כמארז\"ל<sup data-n=\"4201\">13</sup> האומר תהלה לדוד ג\"פ בכל יום מובטח לו כו'). ומבאר בזה, דארוממך הוא ג\"כ בחי' כתר, שנקרא רם מפני שהוא מרומם מכל הי\"ס, כי כל הי\"ס הם בבחי' גילוי, אבל הכתר הוא סתימא דכל סתימין, ולכן אמר על הכתר ארוממך, שהוא מרומם. וזהו גם פירוש ארוממך בכ\"ף, כי הכ\"ף רומז ג\"כ על בחי' כתר, הא' מפני שכ' הוא התחלת תיבת כתר, והב' כי כ' הוא ב\"פ יו\"ד, שהוא עשר ספירות באור ישר שמלמעלה למטה, וע\"ס באור חוזר שמלמטה למעלה<sup data-n=\"4202\">14</sup>, והם נכללים בכתר [משא\"כ כפי שהם בפני עצמם לא שייך שיהיו במספר עשרים, כי הם שני סוגים שונים<sup data-n=\"4203\">15</sup>, ודוקא בכתר נכללים הם להיות מציאות אחת של עשרים]. אמנם, ממש\"נ ארוממך בלשון נוכח, משמע לכאורה שהוא לשון גילוי, והרי הכתר הוא נעלם מהשגת הנבראים. אך על זה אמר אח\"כ אלקי המלך, כלומר, עיקר סיבת ההשגה בו הוא מפני שמתלבש במלך, דהיינו מלכות דאצילות, שבה מתלבש הכתר, כי נעוץ סופן בתחלתן כו'<sup data-n=\"4204\">16</sup>. והטעם הוא, כי בהיות מלכות דאצילות יורדת למטה מטה במקום הקליפות לברר בירורים, הנה לסיבה זו יכולים הקליפות לינק ממנה, וע\"כ צריכה שמירה ממקום גבוה, דהיינו מבחי' אור הכתר, ובזה גופא, לא רק חיצוניות הכתר, אלא גם פנימיות הכתר, וכנ\"ל דאשרי קאי על עתיק שהוא תענוג העליון דהיינו פנימיות הכתר (ולא רק רצון שהוא חיצוניות הכתר), ובחי' זו שהיא למעלה ביותר, נמשכת ונעוצה דוקא במלכות שהיא סוף הספירות. וי\"ל שזהו ג\"כ מ\"ש ארוממך בכ' ארוכה, כידוע שהמשכת הכ\"ף למטה מן השורה מורה שהיא יורדת למטה מטה ביותר. וזהו מה שממשיך ואברכה שמך לעולם ועד, שלאחר שנתגלה הארת הכתר במלכות, אזי יומשך ממנה השפע לעולמות בי\"ע, וזהו ואברכה מלשון המבריך את הגפן<sup data-n=\"4205\">17</sup>, דהיינו ההמשכה שנמשכת מבחי' המלכות שנקראת שמך, שהיא בחי' שם והארה בלבד (ולא עצם), וההמשכה היא לעולם ועד, היינו שההמשכה לבי\"ע היא לאין קץ, שיוכל להחיות נבראים עד אין קץ, אף שזהו מבחי' שמך בלבד.\nד) <b>ועד\"ז</b> מבואר ג\"כ בהמשך המאמר קרוב לסיומו<sup data-n=\"4206\">18</sup>, במש\"נ בהמשך המזמור, פותח את ידיך ומשביע לכל חי רצון צדיק הוי' גו' קרוב הוי' גו'.ומבאר בזה ע\"פ משארז\"ל<sup data-n=\"4207\">19</sup> אל תקרי ידיך אלא יודי\"ך, ומפרש דפותח את ידיך היינו פתיחו דיודי\"ן דתיקוני דיקנא, שהת\"ד הם יודי\"ן וווי\"ן שנמשכים ונפתחים בחכמה, והיינו ענין המשכת הכתר. והמשכה זו היא באופן דמשביע לכל חי רצון, פירוש, כי יסוד נקרא חי, מפני שעל ידו הם כל ההשפעות, ולכן נמשך הכתר בבחי' היסוד כדי שעל ידו יושפע לכל סדר ההשתלשלות. וממשיך לבאר<sup data-n=\"4208\">20</sup> מ\"ש צדיק הוי' בכל דרכיו, דצדיק הוא ג\"כ יסוד, וההפרש בין כשנקרא חי לכשנקרא צדיק הוא, דכשמשפיע חיות לפנימיות העולמות נקרא חי, וכשמשפיע חיות לחיצוניות העולמות נקרא צדיק, וזהו צדיק הוי' בכל דרכיו, שהמשכה זו נמשכת אח\"כ בבחי' חיצוניות העולמות, עד בכל דרכיו, בכל דרכי סדר ההשתלשלות. וממשיך לבאר<sup data-n=\"4209\">21</sup> מ\"ש קרוב הוי' לכל קוראיו, שזהו משום שאוא\"ס מלובש בעשי' כמו באצילות, ולכן קרוב הוי' לכל קוראיו בשוה.\n<b>ויש</b> להוסיף ביאור במ\"ש בהמשך הכתוב לכל אשר יקראוהו באמת, כי הענין דקרוב לכל קוראיו בשוה, הוא מצד קריאה סתם, קריאה חיצונית, ולמעלה מזה הוא הקירוב לכל אשר יקראוהו באמת, שהו\"ע קריאה פנימית, שהיא קריאה באמת, שאז הוא קרוב ביותר, וכמבואר במ\"א<sup data-n=\"4210\">22</sup> שיקראוהו באמת קאי על התורה, אין אמת אלא תורה<sup data-n=\"4211\">23</sup>, שדוקא ע\"י התורה היא ההמשכה הפנימית.\nה) <b>ועפ\"ז</b><sup data-n=\"4212\">24</sup> יש לבאר בתוס' ביאור השייכות של גילוי הוי' דלעילא ליצי\"מ ומ\"ת, כי בכדי שתהי' הירידה גם לתחתונים (שזה נתחדש במ\"ת) צ\"ל ההמשכה מבחינה נעלית יותר. ע\"ד המבואר בהמאמר שבכדי שיהי' \"אלוקי המלך\" ובפרט \"ואברכה שמך לעולם ועד\" צ\"ל \"ארוממך\". וזהו וידבר אלקים אל משה ויאמר אליו אני הוי', שבתחילה הי' הגילוי דשם הוי' ע\"י שם אלקים דוקא, ושמי הוי' דלעילא לא נודעתי להם. אבל כדי להוציא ישראל ממצרים ושיהי' מ\"ת, צ\"ל נמשך ממקום גבוה יותר, מבחי' הוי' דלעילא. הנה כתיב<sup data-n=\"4213\">25</sup> גדול הוי' ומהולל מאד בעיר אלקינו, ואמרז\"ל<sup data-n=\"4214\">26</sup> אימתי הוא גדול כשהוא בעיר אלקינו, שע\"י עיר אלקינו<sup data-n=\"4215\">27</sup> בא הוי' בריבוי התחלקות להוות ריבוי נבראים, מה רבו מעשיך הוי'<sup data-n=\"4216\">28</sup> (וגם ההתהוות דמה גדלו מעשיך הוי'<sup data-n=\"4217\">29</sup> הוא ע\"י שבא בעיר אלקינו דוקא). אמנם בחי' הוי' מצדעצמו הוא למעלה מהתחלקות, הי' הוה ויהי' כאחד<sup data-n=\"4218\">30</sup>, ועד לאחדות הפשוטה, שזהו ולגדולתו אין חקר<sup data-n=\"4219\">31</sup>, שהוא בחי' גדולת הוי' שמצ\"ע. והנה בחי' שם הוי' כפי שנתצמצם ע\"י שם אלקים, מכיון שהוא אור מצומצם ומוגבל, נמשך רק לאצילות, ובכדי שיומשך גם למטה בעולמות בי\"ע, ועד לעוה\"ז התחתון שאין תחתון למטה ממנו<sup data-n=\"4220\">32</sup> (חיבור עליונים ותחתונים שנתחדש במ\"ת), צ\"ל נמשך שם הוי' שלמעלה מהתלבשות בשם אלקים, שהוא בחי' הוי' דלעילא. ועפ\"ז יובן מה שפירש\"י לא נכרתי להם במדת אמיתית שלי, שלכאורה איך שייך לומר שלא נגלה להאבות מדת אמיתית, ובפרט ליעקב שמדתו היא מדת האמת<sup data-n=\"4221\">33</sup>. אלא שהכוונה היא שלא נתגלה להם בחי' הוי' דלעילא, שהוא מדת אמיתית שלו דוקא, וע\"ד מ\"ש תתן אמת ליעקב<sup data-n=\"4222\">34</sup>, שגם ליעקב שמדתו מדת האמת, צריך להמשיך בחי' אמת העליון אמת ה'<sup data-n=\"4223\">35</sup>. וזהו מה שנתחדש ביצי\"מ ומ\"ת, שהאיר אז בחי' שם הוי' דלעילא, ובפרטיות יותר, שם הוי' דבחי' עתיק. ועד\"ז יהי' לעתיד לבא, שנאמר<sup data-n=\"4224\">36</sup> כימי צאתך מארץ מצרים אראנו נפלאות, שיהי' אז גילוי שם הוי' דלעילא, בחי' מדת אמיתית שלי, ועוד יותר מבזמן יצי\"מ<sup data-n=\"4225\">37</sup>, כי אראנו הנפלאות מה שביצי\"מ ופני לא יראו<sup data-n=\"4226\">38</sup>. והנה כל הגילויים דלעתיד תלויים<sup data-n=\"4227\">39</sup> במעשינו ועבודתינו במשך זמן הגלות, לכן צ\"ל עכשיו העבודה למעלה ממדידה והגבלה, וע\"ד דחז\"ל עה\"פ וארא שצ\"ל העבודה באופן דלא הרהרו<sup data-n=\"4228\">40</sup>, ואני הוי', נאמן<sup data-n=\"4229\">41</sup> לשלם שכר טוב ולקיים הבטחותיו והוצאתי והצלתי וגאלתי ולקחתי<sup data-n=\"4230\">42</sup> – שנאמר למשה רעיא מהימנא, הוא גואל ראשון הוא גואל אחרון<sup data-n=\"4231\">43</sup>, יבוא ויגאלנו ויוליכנו קוממיות לארצנו, בעגלא דידן.\n**********",[["4188","*","התחלת וסיום המאמר הוגה ע\"י כ\"ק אדמו\"ר שליט\"א. וראה לקמן הערה 7."],["4189","1","וארא ו, ב-ג."],["4190","2","ראה אוה\"ת וארא (ע' קיט ואילך)."],["4191","3","שמות ג, יב."],["4192","4","שמו\"ר פי\"ב, ג. תנחומא וארא טו."],["4193","5","יתרו יט, כ."],["4194","6","משפטים כד, א."],["4195","7","יצא לאור בקונטרס בפ\"ע – \"<i>פורים</i>,<i> שנת </i>כ\"י תש\"א<i> את ראש בני ישראל</i>\" (ונדפס אח\"כ במאמרי אדמו\"ר הזקן תק\"ע ע' קלא ואילך). ובפתח דבר: \"בעת ההתוועדות דשבת מברכים החודש שבט, שחל השנה יומים לאחרי ההילולא של אדה\"ז, הואיל כ\"ק אדמו\"ר שליט\"א לאמר חלק ממאמר זה בתוספת התחלה וסיום וכו'\"."],["4196","8","פקנ\"ט ואילך."],["4197","9","דרמ\"צ ח\"ב ע' רכג, א ואילך [יהל אור במילואים ע' תרסה ואילך]. וראה יהל אור עה\"פ (ע' תקלג ואילך)."],["4198","10","מכאן עד סוס\"ד – הנחה בלתי מוגה."],["4199","11","ויצא ל, יג."],["4200","12","תהלים קמה."],["4201","13","ברכות ד, ב."],["4202","14","ראה פרדס שער ט\"ו פ\"ד."],["4203","15","ראה גם ד\"ה כי תשא דש\"פ תרומה, פ' שקלים, תשל\"ד (סה\"מ תשל\"ד ע' 95 ואילך)."],["4204","16","ספר יצירה פ\"א מ\"ז."],["4205","17","כלאים פ\"ז מ\"א."],["4206","18","מאמרי אדה\"ז שם ע' קמג."],["4207","19","תקוני זהר בהקדמה (ז, ב)."],["4208","20","מאמרי אדה\"ז שם ע' קמד."],["4209","21","שם ע' קמה."],["4210","22","ראה המשך תער\"ב ח\"ב ע' תשמא. ד\"ה וידבר גו' אנכי דיום ב' דחג השבועות וד\"ה נשא – תש\"ל (סה\"מ תש\"ל ע' 238 ואילך). ד\"ה ונחה דאחש\"פ – שנה זו (סה\"מ תשל\"א ע' 454 ואילך)."],["4211","23","ירושלמי ר\"ה פ\"ג ה\"ח. איכ\"ר פתיחתא ב. תקו\"ז תיקון כא (נ, א)."],["4212","24","מכאן עד סוף המאמר הוגה ע\"י כ\"ק אדמו\"ר שליט\"א."],["4213","25","תהלים מה, ב."],["4214","26","כ\"ה בכמה מקומות, וראה זח\"ג ה, א. זו\"ח תשא (מד, א) – בשינוי לשון."],["4215","27","ראה גם כבוד מלכותך תרס\"א (סה\"מ תרס\"א ע' קעא ואילך). אור לי\"ד ש\"ת (סה\"מ ה'ש\"ת ע' 37 ואילך)."],["4216","28","תהלים קד, כד."],["4217","29","שם צב, ו."],["4218","30","זח\"ג רנז, סע\"ב. שער היחוד והאמונה פ\"ז."],["4219","31","תהלים קמה, ג."],["4220","32","<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו</a>."],["4221","33","זח\"ב רעו, ב."],["4222","34","מיכה ז, כ."],["4223","35","עיין אגה\"ק ס\"ו."],["4224","36","מיכה ז, טו."],["4225","37","ראה זח\"ג נב, סע\"א. ת\"ז תי\"ג ד\"ה שתיתאה (כח, ב). רשימות הצ\"צ עה\"פ כימי צאתך (<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600486\" data-slug=\"or-hatorah-hb\" data-id=\"8316600486\">אוה\"ת נ\"ך ע' תפו</a> ואילך)."],["4226","38","תשא לג, כג."],["4227","39","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>."],["4228","40","ראה פרש\"י שמות ו, א."],["4229","41","פרש\"י פרשתנו ו, ב."],["4230","42","פרשתנו שם, ו-ז."],["4231","43","ראה שמו\"ר פ\"ב, ד. זח\"א רנג, א. שה\"פ פרשת ויחי. תו\"א ר\"פ משפטים."]]],[1500370058,"<h3>בס\"ד. ש\"פ בא, ח' שבט, ה'תשל\"ו<sup data-n=\"4232\">*</sup></h3>\n(הנחה)\n<b>באתי</b><sup data-n=\"4233\">1</sup> לגני אחותי כלה<sup data-n=\"4234\">2</sup> ומביא כ\"ק מו\"ח אדמו\"ר בעל ההילולא [בהמאמר<sup data-n=\"4235\">3</sup> שניתן על ידו ליום הסתלקותו ש\"פ בא יו\"ד שבט, תש\"י] את מאמר המדרש<sup data-n=\"4236\">4</sup> לגני לגנוני למקום שהי' עיקרי בתחלה, דעיקר שכינה בתחתונים היתה, אלא שע\"י ענינים בלתי רצויים במשך ז' דורות סילקו את השכינה מלמטה למעלה עד רקיע הז', ואח\"כ עמדו צדיקים והמשיכו את השכינה מלמעלה למטה, והתחלת ההמשכה היתה מאברהם, אחד הי' אברהם<sup data-n=\"4237\">5</sup>, שהורידה מרקיע הז' לו' וכו' ועד שבא משה שהוא השביעי וכל השביעין חביבין<sup data-n=\"4238\">6</sup> והורידה למטה בארץ. וזהו מה שעשיית המשכן היתה ע\"י משה (דוקא), כי ענין המשכן הוא כמ\"ש<sup data-n=\"4239\">7</sup> ועשו לי מקדש ושכנתי בתוכם, שע\"י ועשו לי מקדש נעשה ושכנתי למטה בבני ישראל ובעולם, כי מהשראת השכינה שהייתה בבית המקדש נמשך הגילוי ע\"י החלונות שקופים אטומים<sup data-n=\"4240\">8</sup> בכל העולם. וכל זה נעשה ע\"י עבודת ישראל וכמו שדייקו רז\"ל<sup data-n=\"4241\">9</sup> בתוכו לא נאמר אלא בתוכם בתוך כאו\"א מישראל, שע\"י עבודת ישראל (אשר ועמך כולם צדיקים<sup data-n=\"4242\">10</sup>) נעשה ושכנתי בהמשכן ועי\"ז בכל העולם. וזהו צדיקים יירשו ארץ וישכנו לעד עלי'<sup data-n=\"4243\">11</sup>, דצדיקים יירשו ארץ שהוא ארצות החיים (ג\"ע) לפי שהם משכינים וממשיכים<sup data-n=\"4244\">12</sup> בחינת שוכן<sup data-n=\"4245\">13</sup> עד<sup data-n=\"4246\">14</sup>, בחינת הסובב, שיהי' בגילוי למטה ע\"י העבודה דתומ\"צ. וכמ\"ש<sup data-n=\"4247\">15</sup> אנכי עשיתי ארץ ואדם עלי' בראתי, דזה<sup data-n=\"4248\">16</sup> מה שאנכי עשיתי ארץ הוא בשביל האדם ובריאת האדם היא בשביל בראת\"י בגימטריאתרי\"ג<sup data-n=\"4249\">17</sup>, והיינו שע\"י קיום התרי\"ג מצוות נשלמה כוונת הבריאה דנתאווה הקב\"ה להיות לו ית' דירה בתחתונים<sup data-n=\"4250\">18</sup>. וזהו מה שאחת העבודות שהי' במקדש הו\"ע עבודת הקרבנות&lt;<b>א</b>&gt;, דעבודת הקרבנות היא עבודה רוחנית שבנפש האדם, וכמו שמדייק כ\"ק אדמו\"ר הזקן<sup data-n=\"4251\">19</sup> במ\"ש<sup data-n=\"4252\">20</sup> אדם כי יקריב מכם גו' שהקרבן צ\"ל מכם ממש, מנפש הבהמית שבאדם, ואומר על זה מן הבקר ומן הצאן, הן הפרטי מדריגות שישנם בנה\"ב (וכמבואר בכ\"מ<sup data-n=\"4253\">21</sup> בענין שור כשב ועז). ועבודה זו הייתה במקדש, כי כל העליות הן ע\"י המקדש. דכמו שכל ההמשכות הן ע\"י המקדש, וכנ\"ל שהמשכת השכינה בעולם הייתה ע\"י החלונות שקופים אטומים דמקדש, כן גם העליות מלמטה למעלה הן ע\"י המקדש, שלכן כשמתפלל יכוון כנגד בית המקדש<sup data-n=\"4254\">22</sup>. ועפ\"ז מבאר שם מה שהמשכן הי' מעצי שטים, כי עיקר עבודת האדם הוא הענין דאתכפיא ואתהפכא חשוכא לנהורא, ולכן הי' המשכן מעצי שטים, לשון שטות, הפיכת השטות דלעו\"ז שלמטה מטו\"ד, שאין אדם עובר עבירה אא\"כ נכנס בו רוח שטות<sup data-n=\"4255\">23</sup>, לשטות דקדושה שלמעלה מטו\"ד.\nב) <b>וממשיך</b> כ\"ק מו\"ח אדמו\"ר בהמאמר בפ\"ו<sup data-n=\"4256\">24</sup>, שבזה יובן גם מה שעצי שטים שבנו מהם את המשכן נקראים בשם קרשים וכמ\"ש<sup data-n=\"4257\">25</sup> ועשית את הקרשים למשכן עצי שטים עומדים. דהשם קרשים [שזה שמו אשר יקראו לו בלה\"ק<sup data-n=\"4258\">26</sup>] מורה על תוכן ענינם. והוא מה שמקשר ושקר דעולם מתברר ונהפך לקרש המשכן, קשר דקדושה (וכמבואר לקמן במאמר ההילולא פ\"י). והוא ע\"ד המבואר לעיל בענין עצי שטים, שזהו מה שמתהפך משטות דלעו\"ז (שקר דעולם) לשטות דקדושה (קרשי המשכן). והנה ענין זה שבקרש (שקודם שנהפך לקדושה מורה על שקר) מרומז הוא לא רק בכללות התיבה אלא גם בהאותיות שבה, ומבאר בהמאמר בפ\"ו<sup data-n=\"4256\">24</sup> בהקדם מ\"ש בהקדמת הזהר<sup data-n=\"4259\">27</sup> דאות ק' ור' הן אתוון דאתחזיאו על סטרא בישא, ובגין לאתקיימא נטלי אות ש' בגווייהו (דהא אות ש' את קשוט איהו). והשייכות דאות ק' ור' לסטרא בישא מבאר בהמאמר שם, שק' ור' הן לנגד ד' וה'. דד' ור' דומים זל\"ז בדמותן וכן בפירושן, דד' הוא מלשון דלות ועניות וכן רי\"ש\n<b>&lt;א&gt;</b>) ד\"ה באתי לגני רפ\"ב. וראה תוד\"ה עד אחת (מנחות יח, א).הוא מלשון עניות ורישות, אלא שמ\"מ הם מובדלים ומרוחקים זמ\"ז בתכלית, מן הקצה אל הקצה. דד' היא אות דקדושה ורי\"ש היא אות דלעו\"ז, שלכן כאשר מחליף אותיות אלו זב\"ז ה\"ז מחריב עולמות ח\"ו. ומביא על זה ב' דוגמאות. דוגמא אחת מהד' דאחד, הקו דועשה טוב, שאם מחליפה ח\"ו באות ר' ה\"ז מחריב עולמות<sup data-n=\"4260\">28</sup>, ודוגמא שני' מהר' דלא תשתחווה לא-ל אחר<sup data-n=\"4261\">29</sup>, הקו דסור מרע, שאם מחליף ח\"ו את הרי\"ש בד' ה\"ז מחריב עולמות<sup data-n=\"4260\">28</sup>.\n<b>והנה</b> ההפרש שבין אות ד' לאות ר' בתמונתן מבאר בהמאמר שם, שאות ד' יש לה יו\"ד מאחורי', דאות יו\"ד [להיותה אות הכי קטנה מכל האותיות, ועד שהיא נקודה בלבד] מורה על הביטול. וזהו נקודת הביאור בהחילוק שבין אות ד' לר' (אף ששתיהן מורות על העניות), שאות רי\"ש, מכיון שאין בה יו\"ד המורה על ביטול, הו\"ע הישות, ולכן היא מאתוון דאתחזיאו על סטרא בישא (וענין העניות דסט\"א הוא מה שאין להם שייכות לאלקות), משא\"כ אות ד', מכיון שיש בה יו\"ד המורה על ביטול, ענין העניות שלה הו\"ע הביטול.\nג) <b>והנה</b> ענין הביטול (המבואר בהמאמר פ\"ו) בא בהמשך להענין דבאתי לגני לגנוני (התוכן דכללות המאמר). והיינו, שהמשכת השכינה למטה, שיהי' דירה לו ית' בתחתונים, הוא ע\"י העבודה דביטול דוקא. ומכיון שעשיית הדירה היא ע\"י התורה, דזהו מה שכל הבריאה הוא בשביל התורה וכמרז\"ל<sup data-n=\"4262\">30</sup> בשביל התורה שנקראת ראשית, הרי מובן, שההקדמה למ\"ת הו\"ע הביטול. וכמו שמבאר כ\"ק אדמו\"ר הזקן<sup data-n=\"4263\">31</sup> עה\"פ<sup data-n=\"4264\">32</sup> בחודש השלישי גו' ביום הזה באו מדבר סיני, ודרשו רז\"ל<sup data-n=\"4265\">33</sup> שקאי על ר\"ח, שאינו מובן, מהי השייכות של ביאתם למדבר סיני (ההקדמה למ\"ת) לר\"ח, וגם למה נקרא ר\"ח בכתוב זה בלשון ביום הזה, ומבאר כ\"ק אדמו\"ר הזקן ע\"פ מארז\"ל<sup data-n=\"4266\">34</sup> ישראל מונין ללבנה, שהלבנה לית לה מגרמה כלום<sup data-n=\"4267\">35</sup>, ענין הביטול. וזוהי השייכות דר\"ח למ\"ת, דכמו שהלבנה בשעת המולד (ענין ר\"ח) היא נקודה בלבד (שנקודה הו\"ע הביטול), ויתירה מזו, אשר רגע לפני המולד היא בהעלם והסתר לגמרי שאינה בבחינת מציאות כלל (גם לא מציאות דנקודה), עד\"ז גם ההקדמה למ\"ת הו\"ע הביטול. וזהו ג\"כ מה שהתורה ניתנה ע\"י משה דוקא, לפי שמשה הי' בתכלית הביטול וכמ\"ש<sup data-n=\"4268\">36</sup> והאיש משה עניו מאוד מכל האדם אשר על פני האדמה, עניו הוא ענין עני<sup data-n=\"4269\">37</sup> והו\"ע הביטול דאות דל\"ת מלשון דלות ועניות,ומצד הביטול שלו ניתנה התורה על ידו. וזהו ג\"כ מה שכל הנביאים נתנבאו בכה ומשה נתנבא בזה<sup data-n=\"4270\">38</sup>, זה הוא בחינת חכמה, והמשכת החכמה היא ע\"י הביטול, ולכן נתנבא משה בזה. וזהו ג\"כ מה שר\"ח נקרא בכתוב זה בלשון ביום הזה, יום הוא אור וגילוי וזה הוא בחינת חכמה כנ\"ל, ויום הזה הוא הגילוי דבחינת חכמה. וע\"י ענין ר\"ח שמורה על הביטול כנ\"ל, נעשה ביום הזה, הגילוי דבחינת חכמה.\n<b>והנה</b> ענין הביטול (שהוא ההכנה למ\"ת, כנ\"ל) צ\"ל בכל ג' הקוין דתורה עבודה וגמ\"ח<sup data-n=\"4271\">39</sup>. דהנה תורה היא המשכה מלמעלה, וההמשכה מלמעלה היא דוקא למי שבטל, וכמ\"ש<sup data-n=\"4272\">40</sup> מרום וקדוש אשכון ואת דכא ושפל רוח. שלכן לימוד התורה צ\"ל לא בבחינת יש מי שלומד רק כמ\"ש<sup data-n=\"4273\">41</sup> תען לשוני אמרתך, כעונה אחר הקורא<sup data-n=\"4274\">42</sup>, ועד\"ז הוא גם בקו הצדקה, דענין הצדקה הוא<sup data-n=\"4275\">43</sup> להחיות רוח שפלים. וכמו שהוא בנוגע לצדקה בפרט, עד\"ז הוא גם בכללות המצוות שנקראים בשם צדקה<sup data-n=\"4276\">44</sup>, שקיום המצוות צ\"ל בביטול דוקא, שהוא מקיים מצות הוי'&lt;<b>ב</b>&gt; [ובדוגמת הביטול בלימוד התורה, שהוא מרגיש שהתורה היא אמרתך]. ועד\"ז הוא גם בקו העבודה שענינה הוא<sup data-n=\"4275\">43</sup> בחינת ביטול (מלמטה למעלה), דזהו מה שעבודת התפלה צ\"ל בביטול דוקא וכמ\"ש<sup data-n=\"4277\">45</sup> תפלה לדוד הטה גו' וענני כי עני ואביון אני, וכמרז\"ל<sup data-n=\"4278\">46</sup> אין עומדים להתפלל אלא מתוך כובד ראש ופירש\"י הכנעה ושפלות<sup data-n=\"4279\">47</sup>. וזהו ג\"כ מה שמבאר כ\"ק מו\"ח אדמו\"ר בהמאמר (פ\"ו) ענין הביטול בכל ג' הקוין, דבענין לימוד התורה מביא מה שאמרו רז\"ל<sup data-n=\"4280\">48</sup> לא תמצא בגסי הרוח כו', כי לימוד התורה צ\"ל בתכלית הביטול, וכמו התלמיד המקבל מרבו, שבעת ההשפעה צ\"ל בטל בתכלית (שפתותיו נוטפות מר<sup data-n=\"4281\">49</sup>), וכן בנוגע לתפלה מביא בהמאמר מ\"ש תפלה לדוד הטה ה' אזנך וענני כי עני ואביון אני, שהבקשה הטה גו' וענני הוא לפי דעני ואביון אני, וגם הביטול שצ\"ל בהקו דגמ\"ח כללות המצוות מרמז שם בהמשל דכח התנועה, שבכדי\n<b>&lt;ב&gt;</b>) וכדאיתא באוה\"ת בראשית (ה, סע\"ב ואילך).להגבי' משא כבדה צריך לצמצם את עצמו, שבזה מרמז ענין הביטול שבקיום המצוות. כי המצוות מלובשים בדברים גשמיים, וענין ההתלבשות בגשמיות (אצל יהודי) הוא דבר קשה. וזהו מה שמרמז בהמשל דכח התנועה, דכמו שבכדי להגבי' משא כבדה צריך לצמצם את עצמו, עד\"ז הוא גם בקיום המצוות (שהוא דוגמת משא כבדה) שצ\"ל בביטול.\nד) <b>והנה</b> בענין הביטול דאות יו\"ד (שבאחורי הדל\"ת) מבאר בהמאמר, וז\"ל: דאות יו\"ד מורה על הביטול ואזעירת גרמה<sup data-n=\"4282\">50</sup>, והיינו מלכות דאצילות דלית לה מגרמה כלום. ויש לומר הכוונה בזה שמוסיף הענין דלית לה מגרמה כלום, כי הענין דאזעירת גרמה, אף שהוא בחינת ביטול, מ\"מ נשאר עדיין איזה מציאות (ורק שהמציאות הוא באופן דאזעירת), ולכן מוסיף הענין דלית לה מגרמה כלום, שהיא (כלשון המאמר שם) בתכלית הביטול והשפלות. ויובן זה ע\"פ מ\"ש כ\"ק אדמו\"ר האמצעי בביאורי הזהר<sup data-n=\"4283\">51</sup> בענין וגם אמנה אחותי בת אבי היא אך לא בת אמי<sup data-n=\"4284\">52</sup>, שבחינת הביטול דכלי ריקן באה מבחינת החכמה (אבי) דוקא. כי מההתבוננות דבינה (אמי) נעשה ההתפעלות בבחינת התלהבות ורעש, וענין הביטול דכלי ריקן בא מבחינת החכמה (אבי) דוקא, שההתפעלות דחכמה הו\"ע השפלות להניח את עצמו ולבטל את עצמו מכל וכל. והנה מובן, שגם ההתפעלות בבחינת התלהבות ורעש שבאה מההתבוננות דבינה, מכיון שגם בת אמי היא בחינה דקדושה, היא בבחינת ביטול, שהרי \"כל ענין הקדושה שיהי' בבחינת ביטול בתכלית\"<sup data-n=\"4285\">53</sup>, וההפרש שבין בת אמי לבת אבי הוא רק מה שההתפעלות הנולדה מהבינה אינה בבחינת ביטול בתכלית. כי מכיון שבינה היא הבנה והשגה, בחינת מציאות, לכן גם ההתפעלות הנולדת ממנה היא בבחינת רעש. משא\"כ מבחינת החכמה הוא בא לידי ביטול בתכלית, והיינו שהביטול הבא ע\"י ההתבוננות דבינה (שהוא בחינת רעש והתפעלות) הוא בבחינת חיצוניות בלבד, משא\"כ הביטול דחכמה (שהיא בחשאי) הוא בחינת ביטול עצמי שהוא בטל בעצם מהותו. וזהו מה שמדייק בהמאמר הענין דלית לה מגרמה כלום, בחינת תכלית הביטול, כי מכיון שבביטול ישנם כמה דרגות כנ\"ל, לכן מדייק שהביטול (דאות ד') המבואר כאן הוא ביטול בתכלית (שהוא ביטול נעלה יותר גם מהביטול דחכמה, כמשי\"ת לקמן). שע\"י ביטול כזה דוקא הוא נעשה כלי לקבל גם שפע שבאין ערוך אליו כלל, וכמו שמבאר בהמשל דרב ותלמיד, שע\"י שהתלמיד הוא בבחינת ביטול במציאות לגמרי, בתכלית הביטול והשפלות, אז דוקא הוא כלי לקבל אמיתית השפעת הרב.\nה) <b>והענין</b> הוא כמו שמבאר כ\"ק אדמו\"ר הצ\"צ באוה\"ת<sup data-n=\"4286\">54</sup>, שביטול התלמיד לקבל שפע הרב הוא בדוגמת ביטול הרב בכדי להשפיע להתלמיד,דכאשר הרב משפיע שכל לתלמיד שבערכו, הנה הגם שגם אז צריך לצמצם קצת את שכלו מ\"מ אינו צריך להניח את עצמו. משא\"כ כשרוצה להשפיע שכל לתלמיד שאינו בערך כלל אז הוא צריך להניח עצמותו על הצד ולצמצם כל עצמותו כו'. ועד\"ז הוא בנוגע לביטול התלמיד, שבכדי לקבל השפעה שבערכו (אף שגם אז צ\"ל בביטול, מ\"מ) אינו צריך להיות בתכלית הביטול, משא\"כ בכדי לקבל השפעה שאינו בערכו כלל, הנה כמו שהרב המשפיע צריך להניח את עצמותו כנ\"ל, עד\"ז הוא גם בהתלמיד המקבל (כמים הפנים לפנים<sup data-n=\"4287\">55</sup>) שצריך להיות בבחינת ביטול בתכלית. ועפ\"ז מבאר (שם) מה שאמרו רז\"ל<sup data-n=\"4288\">56</sup> ר' זירא צם מאה תעניתא דלשתכח מיני' תלמוד בבלי כדי שיוכל לקבל תלמוד ירושלמי, \"שהמכוון, שכשלא הי' כלי ריקן והי' בידו מהשגות הראשוני' לא הי' יכול לקבל השפע העליון דא\"י\". וי\"ל הכוונה בזה, כי בפשטות אינו מובן מה שהוצרך ר\"ז לצום מאה תעניתא כו', דלכאורה, הרי גם קודם לזה הי' אצלו הביטול כדבעי [דמזה גופא שלמד והשיג תלמוד בבלי הרי מוכח שהי' בביטול, שהרי השגת התורה היא ע\"י הביטול דוקא ועד אשר כל תלמיד שאין שפתותיו נוטפות מר כו'], וא\"כ למה הוצרך לצום מאה תעניתא כו', ועל זה מבאר כ\"ק אדמו\"ר הצ\"צ, שהמכוון בזה הוא שהי' צ\"ל כלי ריקן גם מהשגות הראשונים. דמכיון שבכדי לקבל אור נעלה יותר צריך להיות בביטול גדול יותר, לכן, בכדי שיוכל לקבל השפע עליון דא\"י [שהוא נעלה באין ערוך], לא הי' מספיק הביטול שהי' אצלו מקודם, והוצרך לצום מאה תעניתא, שצומות הוא ביטול דמציאות האדם, וביטול זה אינו מספיק עדיין והוצרך להיות גם דלשתכח מיני' תלמוד בבלי (היינו שצ\"ל לא רק ביטול מציאותו בכלל כ\"א גם ביטול השגתו הקודמת), שזהו אמיתית הענין דכלי ריקן, אשר הוא ריקן גם מההשגות הראשונים. וזהו ג\"כ ענין אחותי בת אבי היא, כי בחינת כלי ריקן הנ\"ל נמשך מצד החכמה דוקא ולא מבחינת בינה, כמבואר באוה\"ת שם.\n<b>והנה</b> עד\"ז הוא גם בההשפעה למעלה, שבכדי לקבל ההשפעה דבחינה שלמעלה מהשתלשלות הוא ע\"י הביטול דוקא. וכמו שמבאר כ\"ק אדמו\"ר מהר\"ש<sup data-n=\"4289\">57</sup> עה\"פ<sup data-n=\"4290\">58</sup> מי א-ל כמוך נושא עון ועובר על פשע לשארית נחלתו וארז\"ל<sup data-n=\"4291\">59</sup> למי שמשים עצמו כשיריים, דלכאורה אינו מובן, והלא הסליחה נמשכה ממקום גבוה מאד שהוא למעלה ממקום הדקדוק ולמה דוקא למי שמשים עצמו כשיריים. ומבאר בזה בהקדם<sup data-n=\"4292\">60</sup> מה שהמקובלים הראשונים שלפני האריז\"ל קראו למדת החסד בשם גדולה והאריז\"ל קרא למדת החסד בשם חסד. והטעם לזה הוא, כי מקובלים הראשונים דברו בענין המדות דתהו, וחסד דתהו הוא בבחינת גדולה משא\"כ האריז\"ל מדבר בבחינת חסד דאצילות ולכן קורא זה חסד סתם. וחסד זה (חסדדאצילות) נקרא גם בשם חסד זוטא. והטעם לזה שחסד זה נקרא בשם חסד זוטא, אין זה שהחסד גופא הוא זוטא שהרי גם השפעה דחסד זה הוא בריבוי מופלג, וכדאיתא בספר ארחות צדיקים<sup data-n=\"4293\">61</sup> בנוגע לאברהם אבינו (שהי' מרכבה לחסד דאצילות<sup data-n=\"4294\">62</sup>) שהי' נדיב בממונו בגופו ובנפשו, ומה שנקרא בשם חסד זוטא הוא לא מפני שהחסד עצמו הוא קטן כ\"א לפי שהחסד בא בסיבת הקטנות, והיינו שהשפעת החסד דאצילות הוא מחמת הביטול. וכמו אברהם (שהי' מרכבה לחסד דאצילות כנ\"ל), דלהיות שהי' שפל בעיני עצמו וכמ\"ש<sup data-n=\"4295\">63</sup> ואנכי עפר ואפר, ולכן הי' משפיע כל הטוב והחסד לזולתו. ועד\"ז הוא גם ענין קטונתי מכל החסדים<sup data-n=\"4296\">64</sup> שאמר יעקב, כמ\"ש באגה\"ק<sup data-n=\"4297\">65</sup>. והנה הגם שחסד דאצילות נקרא חסד סתם או חסד זוטא והתואר גדולה קאי על החסד שלמעלה מהשתלשלות, אעפ\"כ מבואר בכ\"מ בפירוש הכתוב<sup data-n=\"4298\">66</sup> לך הוי' הגדולה והגבורה וגו' שקאי על המדות דאצילות. ומבאר בזה, דלהיות שחסד זוטא בא מחמת בחינת הקטנות, שמקטין ומשפיל את עצמו עד שאינו נחשב לכלום, לכן מטעם זה גופא הוא כלי לקבל השפעת בחינת החסד שלמעלה מהשתלשלות הנקרא גדולה, ואדרבה, הגילוי דבחינת הגדולה הוא דוקא בבחינת חסד זוטא. וזהו מי א-ל כמוך גו' לשארית נחלתו למי שמשים עצמו כשיריים, שההמשכה דיגמה\"ר שלמעלה מהשתלשלות היא דוקא למי שמשים עצמו כשיריים, בחינת ביטול בתכלית.\nו) <b>והנה</b> הגם שנת\"ל ס\"ד (מביאוה\"ז) שענין הביטול (היינו ביטול עצמי) הוא מבחינת החכמה דוקא, מ\"מ ע\"י גילוי הארת החכמה בבינה, נמשך הביטול דחכמה גם בבינה. אלא שבחינת החכמה המתגלית בבינה היא רק בחינת חיצוניות החכמה השייכת אל הבינה משא\"כ בחינת פנימיות החכמה היא למעלה מבחינת מקור לבינה. וכמו שמבאר כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע בהמשך תרס\"ו<sup data-n=\"4299\">67</sup>, שבאות יו\"ד (המורה על חכמה) יש ב' ענינים. הא' אות היו\"ד עם המילוי שלה ו\"ד הוא בחינת חיצוניות החכמה השייכת לבינה, והב' הוא אות יו\"ד עצמה בלא המילוי והוא בחינת עצמות החכמה שאינה בבחינת מקור לבינה. וי\"ל הביאור בזה ע\"פ מ\"ש בסידור<sup data-n=\"4300\">68</sup> ובדרוש המילויים<sup data-n=\"4301\">69</sup>, שענין המילוי הוא בשביל הזולת. דכשצריך לומר אות יו\"ד בדיבור לזולתו אזי נתוספים בהכרח אותיות ו\"ד, משא\"כ כמו שהוא במחשבה אינה אלא אות אחת (היו\"ד עצמה). ועפ\"ז מובן, מה שאות יו\"ד עם המילוי שלה ו\"ד הוא בחינת חיצוניות החכמה השייכת לבינה (שהבינה היא כמוזולת לגבי החכמה), משא\"כ אות יו\"ד עצמה בלא המילוי היא בחינת עצמות החכמה. ושתי בחינות אלו שבחכמה הן חלוקות גם בבחינת הביטול שבהם, וכמובן ממה שמבואר בהמשך תרס\"ו שם, שבחינת חיצוניות החכמה היא דוגמת בחינת האור (בחינת מים) המתפשט ומתלבש בכלים, ובחינת פנימיות החכמה היא דוגמת בחינת האור שלמעלה מענין התלבשות בכלים. והנה גם הביטול דבחינת פנימיות החכמה אינו בבחינת העדר המציאות לגמרי. כי גם החכמה היא בבחינת גוון ורק שהגוון שלה הוא גוון עצמי. וכמבואר בההמשך שם שהביטול דחכמה הוא הביטול דאין זולתך, שפירוש אין זולתך הוא מה שאין שום מציאות מלבד העצמות אבל עם העצמות יש מציאות, וביטול זה הוא הביטול דאור (כמו שהוא בבחינת גילוי) מה שאינו מציאות לעצמו מלבד המאור, אבל עם המאור הוא בבחינת מציאות. דביטול זה הוא בבחינת אור המתפשט דוקא, משא\"כ הביטול דאור הכלול במאור הוא הביטול דאפס (שלמעלה מהביטול דאין) והוא שגם עמי' ית' לא יש מציאות כלל. שביטול זה הוא בבחינת האור בהיותו כלול בהמאור ועאכו\"כ בבחינת ישת חשך סתרו<sup data-n=\"4302\">70</sup>, שהוא בחינת חשך והעלם שלמעלה מבחינת אור (גם מבחינת אור הכלול). וזהו ההפרש שבין הביטול דבחינת חכמה לביטול דבחינת כתר, שהביטול דחכמה הוא הביטול דבחינת אין, משא\"כ הביטול דכתר הוא הביטול דבחינת אפס, דזהו מה שכתר הוא מלשון כתר לי זעיר<sup data-n=\"4303\">71</sup> שהו\"ע שתיקה, שהביטול דשתיקה הוא למעלה גם מהביטול דפנימיות החכמה. וזהו מה שאמרו<sup data-n=\"4304\">72</sup> סיג לחכמה שתיקה, שג' תיבות אלו מורות על ג' בחינות הנ\"ל. סיג מורה על הביטול דחיצוניות הכתר, דזהו מה שסיג בגימטריא חכמה, היינו שלמעלה מהביטול דבחינת חכמה ממש ורק גימטריא (והעלם דחכמה) לבד&lt;<b>ג</b>&gt;. חכמה הוא הביטול דבחינת חכמה מצ\"ע. ושתיקה הוא הביטול דכתר, וכנ\"ל שכתר הוא מלשון כתר לי זעיר שהו\"ע שתיקה.\nז) <b>ויש</b> לקשר זה עם מאמר התיקונים<sup data-n=\"4305\">73</sup> כל רב מבבל כל רבי מא\"י, ומבאר בשער מאמרי רשב\"י<sup data-n=\"4306\">74</sup>, שבצאתו יתברך לחוץ, אל חוצה לארץ (בבל), אינו יוצא מבחינת ההויות אלא שבא בבחינת שלשה המילויים של ע\"ב ס\"ג מ\"ה. וז\"ש<sup data-n=\"4307\">75</sup> הנה ה' רוכב על ע\"ב ק\"ל, פירוש, כי איננו יוצא לחו\"ל אלא בבחינת ע\"ב ק\"ל [שהוא מילוי ההוי' של מ\"ה דאלפי\"ן כנודע], והנה ע\"ב ק\"ל בגימטריא ר\"ב, ולכן כל ר\"ב הוא מבבל. אבל בארץ ישראל, אז נקרא רבי, לפי ששם מתחברים עם\n<b>&lt;ג&gt;</b>) ע\"ד י' (דשם הוי') בגימטריא עשר – כל עשר אותיות השם (במילויו) – ויש חשבון ע\"ד מש\"כ בשעהיוה\"א ספ\"ז – וע\"ד: כלל ופרט וכלל.העשרה אותיות של ההוי' עם המילוי שלהם שהוא ע\"ב ק\"ל, ויהי' הכל בגימטריא רב\"י (ע\"כ). ומוסיף הבעש\"ט<sup data-n=\"4308\">76</sup> בפירוש המאמר כל רב מבבל וכל רבי מא\"י, שר\"ב קאי על בחינת חו\"ב, ר' הוא ראשית חכמה ב' הוא בחינת בינה, ואות י' המתוסף ברבי הוא הנביע מא\"ס. וי\"ל שבחינת הי' המתוסף ברבי לפי ביאור הבעש\"ט הוא למעלה מבחינת יו\"ד הנ\"ל לפי הביאור שבשער מאמרי רשב\"י. כי לפי הביאור שבשער מאמרי רשב\"י היו\"ד היא העשר אותיות [שהוא יו\"ד עם המילוי, ורק שהוא נעלה יותר מבחינת המילוי שבגימטריא ע\"ב ק\"ל], משא\"כ לפי ביאור הבעש\"ט הוא היו\"ד עצמו שלמעלה מבחינת מילוי.\n<b>וביאור</b> השייכות דבחינת יו\"ד לא\"י (מה שבא\"י דוקא הוא רבי ביו\"ד), יובן בהקדם תורת הרב המגיד<sup data-n=\"4309\">77</sup> עה\"פ<sup data-n=\"4310\">78</sup> ארץ אשר ה\"א גו' תמיד עיני ה\"א גו', דבספר הזהר<sup data-n=\"4311\">79</sup> הקשה כתיב<sup data-n=\"4312\">80</sup> עין ה' אל יראיו לשון יחיד וכתיב<sup data-n=\"4313\">81</sup> עיני ה' אל צדיקים לשון רבים. ולפי פשוטו י\"ל כי הנה חכמים נקראו<sup data-n=\"4314\">82</sup> עיני העדה. וכתיב<sup data-n=\"4315\">83</sup> חכמות בחוץ תרונה ב' חכמות חכמה עילאה וחכמה תתאה<sup data-n=\"4316\">84</sup>. והנה יש יראה פנימית ויראה חיצונית יראה חיצונית היא היראה שמחמת גדלות<sup data-n=\"4317\">85</sup>, היינו שאינו מכיר פנימיותו ורק שרואה את גדלו ומחמת זה הוא ירא [וע\"ד המבואר בתניא<sup data-n=\"4318\">86</sup>, שגם כשלא ראה את המלך מעולם ואינו מכירו כלל ורק רואה ששרים רבים ונכבדים משתחווים לאיש אחד, תפול עליו אימה ופחד], ויראה פנימית היא שמכיר את פנימיותו וחשיבותו ומחמת זה הוא ירא ומתבייש מפניו. ויראה זו נקראת יראה בושת<sup data-n=\"4317\">85</sup>. וב' בחינות אלו שביראה הן נגד חכמה עילאה וחכמה תתאה. דבחכמה תתאה, שהיא בחינת מלכות, שם היראה היא מחמת גדלות, ובחכמה עילאה (היינו בחינת חכמה) היראה היא מחמת פנימיות. והנה כדי להיות ירא בושת צריך להכיר ולהשיג את אלקותו ית', וזה א\"א אלא ע\"י צמצום שמצמצם את עצמו כביכול שיכולים להשיגו, וזה הצמצום בא ע\"י שיקטין האדם את עצמו כי כמים הפנים לפנים. וזהו מ\"ש גבי ארץ ישראל עיני ה\"א בה, עיני לשון רבים, שבארץ ישראל יש ב' עיינין, יראה החיצונית ויראה הפנימית. דעם היות שארץ היא בחינת מלכות ח\"ת, מ\"מ מצד המעלה דאור חוזר יש בה גם התגלות יראה עליונה. ובדוגמת מה שבאויר הסמוך לארץ יש יותר חמימות מבאויר האמצעי, כי השמש שמכה על הארץ חוזרת ממנו הארה למעלה עד שליש החלל. וזהו ארץ אשר עיני ה\"א בה,ארץ הוא א\"י, ויש בה ב' עיינין חכמה עילאה וחכמה תתאה. מרשית השנה ועד אחרית שנה, ראשית הוא ח\"ע [ורשית חסר כתיב, כי ח\"ע המתגלית בח\"ת (ארץ) אין בה אל\"ף המורה עלי']. (ע\"כ תוכן התורה של הה\"מ). ועפ\"ז יובן מה שאמרו כל רב מבבל וכל רבי מא\"י [שבא\"י הוא רב בתוס' יו\"ד המורה על חכמה], דהגם שא\"י היא בחינת מלכות ח\"ת ויר\"ת, מ\"מ, מכיון שביראה התחתונה יש גם התגלות יראה עליונה, לכן בא\"י הוא רבי ביו\"ד. וזהו ג\"כ מה שהיו\"ד המתוסף ברבי (מא\"י) הוא בחינת פנימיות החכמה כנ\"ל, כי בחינת יראה בושת הבאה מהכרת הפנימיות היא בחינת פנימיות ח\"ע, ולכן הי' ברבי (שמא\"י) בחינת פנימיות החכמה, ועד לבחינת נביע מא\"ס, כנ\"ל מהבעש\"ט.\nח) <b>וזהו</b> מ\"ש כ\"ק מו\"ח אדמו\"ר בהמאמר בענין היו\"ד שבאחורי הד', שאות יו\"ד מורה על הביטול ואזעירת גרמה והיינו מלכות דאצילות דלית לה מגרמה כלום, שהביטול דבחינת מלכות הוא [לא רק הביטול דאזעירת גרמה, כ\"א] בחינת הביטול דלית לה מגרמה כלום, שהוא תכלית הביטול. וכנ\"ל שדוקא במלכות, בחינת ח\"ת, נתגלה בחינת ביטול הכי עליון. וממשיך בהמאמר, שביטול זה צ\"ל בכל ג' הקוין דתורה עבודה וגמ\"ח, שבלימוד התורה אינו מספיק ביטול סתם (השלילה דגסי הרוח) כ\"א צ\"ל \"בבחינת ביטול במציאות לגמרי\", וכן בקו העבודה (תפלה) צ\"ל הביטול דעני ואביון אני שהוא בחינת הביטול דבחינת מלכות, וכן בקו הגמ\"ח (קיום המצוות) מבאר בהמשל דהגבהת משא כבדה (שהוא משל על ענין דקיום המצוות, כנ\"ל), שבכדי להגבי' משא כבדה ביותר (אינו מספיק שיצמצם עצמו קצת, כ\"א) צריך לצמצם את עצמו ביותר. וע\"י הביטול (בכל ג' קוין הנ\"ל) הוא נעשה כלי ריקן ומחזיק, שמקבל את כל הגילויים והכחות שנותנים מלמעלה לעבוד את עבודתו בלימוד התורה וקיום המצוות ועבודת התפלה, ועד שעושה מקשר ושקר העולם שיתהפך לקרשי המשכן, שמהפך את השטות דלעו\"ז לשטות דקדושה. דכל זה הוא ע\"י הביטול דכלי ריקן, שאז הוא כלי לקבל הכחות שנותנים מלמעלה שיוכל לנצח את מלחמת היצר, וכמבואר בהמאמר<sup data-n=\"4319\">87</sup> שבשביל נצוח המלחמה מבזבזים את האוצרות הכמוסים מדור דור (מה שאצר בעצמו וגם מה שאצרו אבותיו) ומוסרים אותם ע\"י פקידי החיל, בשביל אנשי החיל שהם דוקא (אנשי החיל) מביאים את הנצחון בפועל, הצבאות הוי', בכל ג' הפירושים שבזה, כמבואר בהמאמר<sup data-n=\"4320\">88</sup>. והנה התואר צבאות הוי' לישראל התחיל מזמן יצי\"מ, וכמ\"ש<sup data-n=\"4321\">89</sup> בעצם היום הזה&lt;<b>ד</b>&gt; יצאו כל צבאות הוי' מארץ מצרים, ומזה מובן גם בנוגע לגאולה\n<b>&lt;ד&gt;</b>) להעיר מהנ\"ל [אות ג'] בפי' היום הזה.העתידה, שתהי' בדוגמת הגאולה דיציאת מצרים וכמ\"ש<sup data-n=\"4322\">90</sup> כימי צאתך מארץ מצרים אראנו נפלאות, שעי\"ז יהי' הגילוי דגאולה העתידה שאז יהיו נפלאות אפילו לגבי הענינים שהיו ביציאת מצרים<sup data-n=\"4323\">91</sup>, ולאח\"ז יהי' הקיצו ורננו שוכני עפר<sup data-n=\"4324\">92</sup> והוא בתוכם.\n**********",[["4232","*","על רשימת ההנחה – תיקן כ\"ק אדמו\"ר שליט\"א כמה תיקונים בכתי\"ק, וכן הוסיף כמה הערות (<i>המו\"ל</i>)."],["4233","1","מאמר זה מיוסד <i>בעיקרו</i> על פרק הששי מהמשך באתי לגני ה'שי\"ת (סה\"מ ה'שי\"ת ע' 119 ואילך)."],["4234","2","שה\"ש ה, א."],["4235","3","סה\"מ ה'שי\"ת ע' 111."],["4236","4","שהש\"ר עה\"פ."],["4237","5","יחזקאל לג, כד."],["4238","6","ויק\"ר פכ\"ט, יא."],["4239","7","תרומה כה, ח."],["4240","8","מלכים-א ו, ד. וראה מנחות פו, ב ובפרש\"י שם."],["4241","9","ראשית חכמה שער האהבה פ\"ו קרוב לתחילתו (ד\"ה ושני פסוקים). של\"ה סט, א. רא, א. שכה, ב. שכו, ב. ועוד."],["4242","10","ישעי' ס, כא."],["4243","11","תהלים לז, כט."],["4244","12","ראה מתנות כהונה ומהרז\"ו לבמדב\"ר פי\"ג, ב. מהרז\"ו לב\"ר פי\"ט, ז."],["4245","13","ראה ד\"ה באתי לגני תשי\"א פ\"ד (לעיל ע' רסו)."],["4246","14","נוסח התפלה."],["4247","15","ישעי' מה, יב."],["4248","16","ראה סה\"מ תרצ\"ו ע' 139. ספר השיחות תרצ\"ו-חורף ה'ש\"ת ע' 255. וש\"נ."],["4249","17","ראה מקדש מלך לזח\"א רה, ב."],["4250","18","ראה תנחומא בחוקותי ג. נשא טז. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו. ובכ\"מ."],["4251","19","סה\"מ קונטרסים ח\"ב תנ, א ואילך (הועתק ב\"היום יום\" יב אדר שני). סה\"מ תרח\"ץ ע' רלב. ועוד. וראה לקו\"ת ויקרא ד\"ה אדם כי יקריב."],["4252","20","ויקרא א, ב."],["4253","21","ראה קונטרס התפלה פ\"ח. ספר השיחות תורת שלום ע' 10. סה\"מ עת\"ר ע' רלט."],["4254","22","שו\"ע אדמו\"ר הזקן או\"ח רסצ\"ד."],["4255","23","סוטה ג, א."],["4256","24","סה\"מ ה'שי\"ת ע' 119."],["4257","25","תרומה כו, כט."],["4258","26","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310006\" data-slug=\"tanya\" data-id=\"3401310006\">תניא שעהיוה\"א ספ\"א</a>."],["4259","27","ב, ב."],["4260","28","ראה ויק\"ר פי\"ט, ב."],["4261","29","תשא לד, יד."],["4262","30","רש\"י ר\"פ בראשית."],["4263","31","תו\"א ר\"פ יתרו (סו, ג ואילך)."],["4264","32","יתרו יט, א."],["4265","33","מכילתא יתרו עה\"פ. שבת פו, ב."],["4266","34","סוכה כט, א."],["4267","35","זהר ח\"א לג, ב. רמט, ב. ח\"ב רטו, א. ועוד."],["4268","36","בהעלותך יב, ג."],["4269","37","ראשית חכמה שער הענוה רפ\"א. הובא באוה\"ת בראשית ו, ב."],["4270","38","ספרי ופרש\"י ר\"פ מטות."],["4271","39","ראה תו\"א שם סז, ג."],["4272","40","ישעי' נז, טו."],["4273","41","תהלים קיט, קעב."],["4274","42","ע\"ד סוכה לח, ב."],["4275","43","תו\"א שם."],["4276","44","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370128\" data-slug=\"torah-or\" data-id=\"3901370128\">תו\"א</a> יתרו שם. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370191\" data-slug=\"torah-or\" data-id=\"3901370191\">תו\"א וישב כז, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370284\" data-slug=\"torah-or\" data-id=\"3901370284\">מקץ מב, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380810\" data-slug=\"likkutei-torah\" data-id=\"4001380810\">בשלח סג, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381280\" data-slug=\"likkutei-torah\" data-id=\"4001381280\">לקו\"ת פ' ראה כג, ג</a>. שה\"ש לח, א."],["4277","45","תהלים פו, א."],["4278","46","ברכות ל, ב."],["4279","47","כ\"ה בכ\"מ בדא\"ח בשם רש\"י \"הכנעה ושפלות\" (סה\"מ תרס\"ה ס\"ע קצד. תרע\"ח ריש ע' צד. תש\"ז ע' 203. ועוד), אבל בפרש\"י לפנינו אין תיבת \"ושפלות\", ובאה לתוספת ביאור ענין ההכנעה [ראה הערה בסה\"מ תרע\"ח ותש\"ז שם. לקו\"ש חל\"ד ע' 69 הערה 18. וש\"נ]."],["4280","48","עירובין נה, א."],["4281","49","ראה שבת ל, ב."],["4282","50","זהר ח\"א כ, א. ח\"ג קצא, א."],["4283","51","פ' וירא י, סע\"ד ואילך."],["4284","52","וירא כ, יב."],["4285","53","המשך באתי לגני שם פ\"ו."],["4286","54","מסעי ע' א'רנא ואילך."],["4287","55","משלי כז, יט."],["4288","56","ב\"מ פה, א."],["4289","57","סה\"מ תרכ\"ז ע' קצח ואילך. תמז ואילך. תר\"ל ע' קצט ואילך."],["4290","58","מיכה ז, יח."],["4291","59","ר\"ה יז, רע\"ב."],["4292","60","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380785\" data-slug=\"likkutei-torah\" data-id=\"4001380785\">לקו\"ת עקב יז, ד</a>."],["4293","61","שער יז. וראה סה\"מ תרפ\"ט ע' 90 ואילך. תרח\"ץ ע' קכט ואילך."],["4294","62","ראה ספר הבהיר סקצ\"א. הובא בפרדס שער כב (שער הכינויים) פ\"ד."],["4295","63","וירא יח, כז."],["4296","64","וישלח לב, יא."],["4297","65","ס\"ב."],["4298","66","דברי הימים-א כט, יא."],["4299","67","ד\"ה ביום השמע\"צ תרס\"ז (ע' שעב ואילך)."],["4300","68","עם דא\"ח – קטו, ב."],["4301","69","סה\"מ אתהלך לאזניא ע' כ."],["4302","70","תהלים יח, יב."],["4303","71","איוב לו, ד."],["4304","72","אבות פ\"ג מי\"ג."],["4305","73","הקדמת ס' התיקונים כת\"י. וראה סה\"מ תש\"ח ע' 121 ובהערה שם."],["4306","74","בתחלתו, בביאור מאמר התיקונים."],["4307","75","ישעי' יט, א."],["4308","76","כתר שם טוב סי' קמ. ס' תולדות יעקב יוסף פ' חוקת."],["4309","77","אור תורה פ' עקב נג, ב ואילך."],["4310","78","עקב יא, יב."],["4311","79","ראה זח\"ג קל, א."],["4312","80","תהלים לג, יח."],["4313","81","שם לד, טז."],["4314","82","שלח טו, כד."],["4315","83","משלי א, כ."],["4316","84","<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670167\" data-slug=\"torat-chaim\" data-id=\"2300670167\">ראה זח\"א קמא, ב</a>. תו\"ח בראשית ג, ב ואילך."],["4317","85","<a class=\"ft-cite\" href=\"#/read/tanya/3401310048\" data-slug=\"tanya\" data-id=\"3401310048\">תניא</a> רפמ\"ג. הערה לתיקון חצות (סידור עם דא\"ח קנא, סע\"ג ואילך)."],["4318","86","פמ\"ב בהגהה (סא, א)."],["4319","87","ד\"ה באתי לגני שם פי\"א."],["4320","88","שם פי\"ב."],["4321","89","בא יב, מא."],["4322","90","מיכה ז, טו."],["4323","91","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600487\" data-slug=\"or-hatorah-hb\" data-id=\"8316600487\">זהר ח\"א</a> רסא, ב. פע\"ח שער חג המצות פ\"ו. אוה\"ת נ\"ך עה\"פ (ח\"א ע' תפז)."],["4324","92","ישעי' כו, יט."]]],[1500380002,"<h3>בס\"ד. ש\"פ משפטים, פ' שקלים, מבה\"ח אדר ה'תשל\"א<sup data-n=\"1\">*</sup></h3>\n<b>כי</b> תשא את ראש בני ישראל לפקודיהם ונתנו איש כופר נפשו גו'<sup data-n=\"2\">1</sup>, ואיתא בגמרא<sup data-n=\"3\">2</sup>, אמר משה לפני הקב\"ה, רבש\"ע במה תרום קרן ישראל אמר לו בכי תשא, ופירש רש\"י, אם באת לשאת ראשם בהגבהה קח מהם כופר לצדקה. ולכאורה, השייכות דכי תשא להרמת קרן ישראל היא, כי תשא הוא (גם) מלשון הגבהה והרמה. וצריך להבין, דעפ\"ז, כששאל משה להקב\"ה <i>במה</i> תרום קרן ישראל הי' צריך לכאורה לענות לו בנתינת כופר לצדקה, ומהו פירוש המענה בכי תשא [שהרמת קרן ישראל נעשית <i>ע\"י</i> כי תשא], הרי נשיאת ראש בני ישראל והרמת קרנם הוא היינו הך. גם צריך להבין, דבכתוב נאמר <i>ונתנו</i> איש כופר נפשו, שנשיאת (הגבהת והרמת) ראש ישראל היא ע\"י <i>נתינת</i> כופר, ובפרש\"י הנ\"ל אם באת לשאת ראשם בהגבהה <i>קח</i> מהם כופר לצדקה. גם צריך להבין, דלשון הכתוב הוא כי תשא את <i>ראש</i> בני ישראל, והלשון בשאלת משה הוא במה תרום <i>קרן</i> ישראל.\nב) <b>והענין</b> הוא, דמבואר בהדרושים (ד\"ה כי תשא את ראש בני ישראל<sup data-n=\"4\">3</sup>), דראש הוא אהבה הטבעית שלמעלה מהשכל<sup data-n=\"5\">4</sup>, וכתיב<sup data-n=\"6\">5</sup> כי עוונותי עברו ראשי גו', שהעוונות מסתירים על בחינת הראש דהנשמה (אהבה הטבעית שלמעלה מהשכל) שלא יאיר בגילוי בכחות הפנימיים. וזהו כי תשא את ראש גו', דהגם שבבחינת הראש אין שייך פגם, מ\"מ, זה עצמו שהראש דהנשמה אינו יכול להאיר בגילוי בכחות הפנימיים מורה שנעשה בו ירידה והשפלה<sup data-n=\"7\">6</sup> ע\"י העוונות (אלא שהירידה וההשפלה היא לא בנוגע לעצמו ורק בנוגע להגילוי שלו), ולכן צריך לישא את הראש, להגבי' אותו משפלותו.\n<b>ולהעיר</b><b>,</b> דבלקו\"ת ד\"ה שובה ישראל גו' כי כשלת בעוניך<sup data-n=\"8\">7</sup> מבואר שהוא כמשל אדם הכושל רגלו שעי\"ז נופל ראשו למטה. ועפ\"ז הי' אפשר לומרדפירוש כי תשא את ראש בני ישראל הוא להגבי' את הראש מנפילתו למטה. ויש לומר הטעם על זה שבדרושים הנ\"ל אינו מפרש כן, כי פרשה זו נאמרה לאחרי יוהכ\"פ<sup data-n=\"9\">8</sup> לאחרי שנתרצה הקב\"ה לישראל בשמחה ובלב שלם ואמר לו למשה סלחתי כדברך<sup data-n=\"10\">9</sup>. והרושם מהחטא שנשאר אחר יוהכ\"פ הוא (בעיקר) רק בנוגע לזה שהרצון שלמעלה מהשכל לא האיר בגילוי בכחות הפנימיים, ולכן נאמר כי תשא את ראש בני ישראל.\nג) <b>והנה</b> כתיב<sup data-n=\"11\">10</sup> גדע בחרי אף כל קרן ישראל, שע\"י העוונות נעשה ירידה גם בבחינת הקרן שלמעלה מהראש. ולכן אמר משה במה תרום קרן ישראל, שצריך להגבי' ולרומם את הקרן שלמעלה מהראש. ומבואר בלקו\"ת<sup data-n=\"12\">11</sup>, דקרן היא בחינת כתר. וצריך ביאור, הרי זה שהקרן הוא למעלה מהראש הוא (לא רק מהמוח שבראש אלא) גם מהגולגולת, וע\"פ הידוע שגלגלתא (הגולגולת שחופה על המוח) היא בחינת כתר, מהו מעלת הקרן על הראש. ויש לומר, דגלגלתא הוא מקיף ששייך לפנימי, בדוגמת הגולגולת שבאדם שמקיף את המוח אבל שייך אליו<sup data-n=\"13\">12</sup>, וקרן הוא מקיף שלמעלה משייכות לפנימי. וכמבואר בכ\"מ<sup data-n=\"14\">13</sup> בפירוש הכתוב<sup data-n=\"15\">14</sup> וירם קרן לעמו, שקאי על עצמות אוא\"ס שלמעלה מסובב. וכמו\"כ הוא בנשמה, שקרן הנשמה הוא עצם הנשמה<sup data-n=\"16\">15</sup>.\n<b>וצריך</b> להבין מה שאמר משה במה תרום קרן ישראל, דלכאורה, איך שייך שתהי' ירידה בעצם הנשמה. ויש לומר הביאור בזה, דהכוונה בירידת הנשמה למטה היא בכדי לפעול בהגוף, ולכן, כשאינה משלמת הכוונה נעשה ירידה בכל הדרגות שבה, גם בהעצם שלה (שירדה למטה). ועפ\"ז, הירידה שע\"י החטא בדרגת הראש דהנשמה, היא מפני שלגבי דרגא זו יש ערך לכחות הגלויים (מכיון שהיא מקיף השייך לפנימי), ולכן הענינים דכחות הגלויים פועלים בה שינוי (אלא שהשינוי הוא רק בנוגע להגילוי שלה, כנ\"ל סעיף ב), והירידה שנעשית ע\"י החטא בעצם הנשמה היא לא שהענינים דכחות הגלויים פועלים בה שינוי, אלא לפי שלא נשלמה הכוונה שבשבילה ירדה למטה. ויש לומר, דזהו מ\"ש <i>גדע</i> גו' קרן ישראל, דכמו שבקרן כפשוטו, השינוי שנעשה בקרן ע\"י שנגדע מהראש (שאין בו התוקף שהי' בו תחילה) הוא לא <i>שהראש</i> פועל שינוי בקרן אלא אדרבה מפני שנגדע מהראש, עד\"ז הוא בהקרן דהנשמה, שהשינוי שנעשה בה ע\"י החטא הוא מצד זה שאינה פועלת בכחות הגלויים (ואינה משלמת כוונת ירידתה למטה).ד) <b>ועפ\"ז</b> יש לומר דבאמירת הקב\"ה למשה כי תשא את ראש בני ישראל, שני ענינים. שישא ויגבי' את <i>ראש</i> בני ישראל, כמפורש בקרא. ועוד ענין (שאינו מפורש בתושב\"כ אלא נתגלה בתושבע\"פ), שע\"י כי תשא את ראש בני ישראל תהי' גם הרמת קרן ישראל [וכלשון הגמרא אמר לו <i>ב</i>כי תשא, שע\"י כי תשא יהי' עוד ענין]. ועפ\"ז יש לבאר מ\"ש רש\"י אם באת לשאת ראשם בהגבהה <i>קח</i> מהם כופר לצדקה, ולא <i>יתנו</i> כופר לצדקה, כלשון הכתוב <i>ונתנו</i> איש כופר נפשו, כי נשיאת והגבהת <i>ראש</i> בני ישראל הוא ע\"י <i>נתינת</i> כופר – <i>ונתנו</i> איש כופר נפשו. ובכדי שהנשיאת ראש תביא להרמת <i>קרן</i> ישראל הוא כשהנשיאת והגבהת הראש היא ע\"י <i>שמשה יקח</i> מהם כופר – אם באת לשאת ראשם בהגבהה <i>קח</i> מהם כופר לצדקה.\nה) <b>ויובן</b> זה בהקדים מ\"ש (בפרשתנו<sup data-n=\"17\">16</sup>) אם כסף תלוה את עמי, ואיתא במדרש<sup data-n=\"18\">17</sup> אמר הקב\"ה אם כסף תלוה את עמי (עמי בחירי\"ק תחת העי\"ן), ומבואר בהדרושים<sup data-n=\"19\">18</sup>, דזה שמעלת הגמ\"ח היא גדולה כ\"כ עד שעי\"ז אתה עמי, עמי במחיצתי<sup data-n=\"20\">19</sup>, הוא כמ\"ש<sup data-n=\"21\">20</sup> כי חסד חפצתי ולא זבח, דהגם שגם הקרבנות (זבח) הם רצונו ית' [כמובן גם מזה שישנם כו\"כ ציוויים להקריב קרבנות], מ\"מ, כיון שענין הקרבנות הוא העלאה מלמטה למעלה, ותכלית הכוונה הוא שיהי' המשכת גילוי אלקות למטה, דנתאוה הקב\"ה להיות לו ית' דירה בתחתונים<sup data-n=\"22\">21</sup>, לכן, הרצון בקרבנות הוא (לא בהקרבנות מצד עצמם, אלא) בשביל ההמשכה שתהי' אח\"כ ע\"י הנסכים [כדאיתא בגמרא<sup data-n=\"23\">22</sup> כל הקורא ק\"ש בלא תפילין כאילו הקריב עולה בלא מנחה וזבח בלא נסכים<sup data-n=\"24\">23</sup>, דמזה משמע שכשהקריב זבח בלא נסכים אין קרבנו כלום<sup data-n=\"25\">24</sup>, ומבואר בלקו\"ת<sup data-n=\"26\">25</sup> שזהו לפי שההעלאה דקרבנות היא בשביל ההמשכה שאח\"כ ע\"י הנסכים], ולכן, הרצון בקרבנות הוא (כמו<sup data-n=\"27\">26</sup>) חיצוניות הרצון [<i>ע\"ד</i><sup data-n=\"28\">27</sup> אדם שרוצה לנסוע לאיזהמקום לקנות סחורה, שהרצון שלו בהנסיעה הוא רק בשביל הריוח שיהי' לו עי\"ז], ופנימיות הרצון הוא בהמשכה למטה. וזהו כי חסד חפצתי ולא זבח, שהחפץ, פנימיות הרצון, הוא שיהי' חסד, המשכה למטה.\n<b>ולהוסיף</b><b>,</b> דמפשטות לשון הכתוב כי חסד חפצתי ולא זבח משמע שמדבר גם בזבח עם נסכים, ואעפ\"כ אומר חסד חפצתי ולא זבח, כי כיון שהנסכים הם טפלים להזבח, גם ההמשכה שע\"י הנסכים אינה כההמשכה שע\"י חסד. וכמוכח גם ממארז\"ל<sup data-n=\"29\">28</sup> (המובא בהדרושים<sup data-n=\"30\">29</sup>) עה\"פ<sup data-n=\"31\">30</sup> אם יתכפר עון בית עלי בזבח ובמנחה, בזבח ובמנחה אינו מתכפר אבל מתכפר בתורה ובגמילות חסדים, שגם הכפרה דמנחה (ועד\"ז נסכים) אינה כהכפרה שע\"י תורה וגמ\"ח, לפי שכללות ענין הקרבנות הוא העלאה, אלא שבקרבנות עצמם – מנחה ונסכים הם המשכה למטה, אבל ההמשכה שעל ידם אינה כההמשכה שע\"י תורה וגמ\"ח. ויתירה מזה, שגם ההמשכה דתורה, שנקראת תורת חסד<sup data-n=\"32\">31</sup> לפי שענינה הוא המשכה למטה, אינה כההמשכה שע\"י חסד. וכסיום מארז\"ל הנ\"ל<sup data-n=\"29\">28</sup> רבה דעסיק בתורה חי מ' שנין אביי דעסיק בתורה ובגמילות חסדים חי ס' שנין. ולהעיר, דענין זה שההמשכה שע\"י גמ\"ח היא המשכה למטה יותר (מההמשכה שע\"י מנחה ונסכים וגם) מההמשכה שע\"י תורה, הוא בכללות בכל המצוות<sup data-n=\"33\">32</sup>, דגמ\"ח היא כללות כל המצוות<sup data-n=\"34\">33</sup>. אבל אעפ\"כ, עיקר המעלה דהמשכה למטה ביותר היא בגמ\"ח כפשוטה. וכמובן גם מהמשך הענינים בהדרושים הנ\"ל, דענין חסד חפצתי ולא זבח הוא ביאור על המעלה דאם כסף תלוה, גמ\"ח כפשוטה. וכן מובן מהמבואר בדרושים הנ\"ל<sup data-n=\"35\">34</sup> הטעם על זה שגמ\"ח היא מהדברים שאדם אוכל פירותיהם בעולם הזה<sup data-n=\"36\">35</sup>, כי ההמשכה שע\"י גמ\"ח היא נמשכת עד למטה מטה, גם בעולם הזה.\nו) <b>והנה</b> איתא בילקוט<sup data-n=\"37\">36</sup> עה\"פ כי חסד חפצתי ולא זבח, פעם אחת הי' רבן יוחנן בן זכאי מהלך בירושלים, והי' רבי יהושע מהלך אחריו, ראה בית המקדש שהוא חרב, אמר, אוי לנו על הבית שחרב מקום שמתכפרין בו עונותינו, א\"ל, בני אל ירע לך, שיש לנו כפרה אחרת שהיא כמותה, ואי זה, זה גמילות חסדים, לכך נאמר כי חסד חפצתי ולא זבח, ואומר<sup data-n=\"38\">37</sup> אמרתי עולם חסד יבנה. ומדייק בהדרושים<sup data-n=\"35\">34</sup>, הרי גמילות חסדים היתה גם בזמן שבית המקדש הי' קיים, ומהלשון יש <i>לנו</i> כפרהאחרת משמע שכפרה זו נתחדשה בזמן הגלות. ומבאר שם, ע\"פ מה דאיתא בגמרא<sup data-n=\"39\">38</sup> א\"ר יוחנן, ששה דברים אדם אוכל פירותיהן בעולם הזה והקרן קיימת לו לעולם הבא (ועיון תפלה הוא מהששה דברים), ומקשה בגמרא, והא תנן&lt;35&gt; אלו דברים שאדם עושה אותם ואוכל פירותיהן בעוה\"ז כו' וקא חשיב שם רק שלשה דברים, ומתרץ, הני נמי בהני שייכי, ופירש רש\"י<sup data-n=\"40\">39</sup> שעיון תפלה הוא בכלל גמ\"ח דכתיב<sup data-n=\"41\">40</sup> גומל נפשו איש חסד [ונפש היינו תפלה דכתיב גבי חנה<sup data-n=\"42\">41</sup> ואשפוך את נפשי לפני ה'<sup data-n=\"43\">42</sup>]. ומבאר בהדרושים, דזה שאמר ריב\"ז יש לנו כפרה אחרת כו' גמילות חסדים, כוונתו היא לעיון תפלה שהיא בכלל גמ\"ח [דעיקר התפלה (ג' תפלות בכל יום ונוסח התפלה) נתקנה בזמן הגלות<sup data-n=\"44\">43</sup>]. והגם שתפלות הם במקום קרבנות וקרבנות הם העלאה מלמטה למעלה, מבואר בהדרושים, דתפלות כנגד תמידין ומוספין תקנום<sup data-n=\"45\">44</sup>, והתמידין ומוספין, קרבנות צבור, הם בחינת המשכה. כדאיתא במדרש<sup data-n=\"46\">45</sup> דזה שישראל נק' בשם רעיתי<sup data-n=\"47\">46</sup> הוא לפי שהיו מקריבין שני תמידין ע\"ג המזבח, ועי\"ז הם רעיתי, פרנסתי, ישראל מפרנסין לאביהם שבשמים<sup data-n=\"48\">47</sup>, שממשיכים אוא\"ס בע\"ס. ומ\"ש כי חסד חפצתי ולא זבח קאי על קרבנות יחיד, שהם בחי' העלאה, אבל קרבנות צבור, תמידין ומוספין, הם בחי' המשכה. וכמ\"ש הש\"ך בפירושו עה\"ת עה\"פ<sup data-n=\"49\">48</sup> מלבד עולת הבוקר, שמלבד הוא ר\"ת <i>מ</i>לוה <i>ל</i>עני <i>ב</i>שעת <i>ד</i>חקו, ופירוש מלבד עולת הבוקר הוא, שהמלוה לעני בשעת דחקו הוא כעולת הבוקר, קרבן תמיד, שהוא המשכה מלמעלה למטה. ומזה שתפלות כנגד <i>תמידין</i> תקנום, מובן, שהתפלות הם המשכה מלמעלה למטה.\nז) <b>והנה</b> מזה שגמילות חסדים (כפשוטה) היתה גם בזמן הבית, משא\"כ הגמ\"ח דתפלה (גומל נפשו איש חסד) נתקנה דוקא לאחרי חורבן ביהמ\"ק, בכדי שתהי' גם עכשיו הכפרה שבדומה להכפרה שהיתה ע\"י ביהמ\"ק, מקום שמתכפרין בו עונותינו, מובן, דיש יתרון בהכפרה שנעשית ע\"י גמ\"ח דתפלה לגבי הכפרה שע\"י גמ\"ח כפשוטה. והענין הוא, דתפלה (בכלל) היא העלאה מלמטה למעלה, וכמובן גם ממ\"ש ואשפוך את נפשי לפני הוי' [דמפסוק זה מביאים ראי' שתפלה היא המשכה], דשפיכת הנפש היא העלאה, אלא שהמבוקש דהעלאה זו הוא שתהי' המשכה למטה<sup data-n=\"50\">49</sup>. [ולהוסיף, דמבואר בהדרושים, דבגומל נפשו איש חסד, שניפירושים. גומל מלשון הפרשה (כמו ויגדל הילד ויגמל<sup data-n=\"51\">50</sup>), וגומל מלשון השפעה (כמו גמילות חסדים). גומל נפשו מלשון השפעה הוא בהעבודה דתפלה שמצד נפש האלקית, שההעלאה (שפיכת נפש) היא בשביל ההמשכה. וגומל נפשו מלשון הפרשה הוא בהקרבת נפש הבהמית שבתפלה, לפרוש ולצאת מעניני העולם ולהיות בביטול, העלאה. ובהעבודה שמצד נפש הבהמית, ההעלאה היא לא בשביל המשכה אלא שזה עצמו הוא המבוקש שלו&lt;49&gt;. ויש לומר, דזה שהתפלה דנפש האלקית נקראת בשם גומל נפשו, שגומל הוא גם לשון הפרשה, מורה, שגם בהתפלה דנפש האלקית ישנה העלאה <i>שבדוגמת</i> העלאה דנפש הבהמית, שהמבוקש שבה הוא העלאה].\n<b>והנה</b> ידוע דבסליחה וכפרה שני ענינים<sup data-n=\"52\">51</sup>. שע\"י ההמשכה מעצמות אוא\"ס בעל הרצון שאינו מוכרח בהרצון, מתבטלים החטאים והפגמים. ועוד ענין בסליחה וכפרה, שע\"י ההמשכה מעצמות אוא\"ס בעל הרצון<sup data-n=\"53\">52</sup>, נמשך <i>רצון</i> חדש (שלמעלה מהרצון שנסתלק ע\"י החטא), ועי\"ז נעשה <i>מרוצה</i> לפניו ית' כמו קודם החטא. והחילוק דשני הענינים הוא, דזה שע\"י ההמשכה מעצמות אוא\"ס מתבטלים הפגמים הוא מפני שאינו מוכרח בהרצון, <i>מובדל</i> מהרצון, וזה שנמשך ממנו רצון חדש הוא (לא מפני שהוא <i>מובדל</i> מהרצון, אלא אדרבה) מפני שהוא בעל <i>הרצון</i>. דבדרגת הרצון, יש הגבלה באופן המשכתו, וכשעושים היפך הרצון הוא מסתלק. משא\"כ <i>בעל</i> הרצון, אינו מוגבל באופן ההמשכה, ולכן גם לאחרי שעשו היפך הרצון שעי\"ז נסתלק הרצון, אפשר להיות נמשך ממנו רצון חדש.\n<b>ויש</b> לומר, דזה שמובא לעיל (סעיף ה) שעיקר הכפרה הוא גמילות חסדים לפי שפנימיות הרצון דלמעלה הוא בהמשכה למטה, חסד חפצתי, הוא בעיקר בנוגע לזה שיהי' <i>מרוצה</i> לפניו ית', וגם בנוגע <i>לתיקון</i> הפגמים. אבל בנוגע <i>ביטול</i> הפגמים [דענין זה הוא מפני שעצמות אוא\"ס בעל הרצון הוא מובדל מהרצון], יש יתרון בהמשכה ששייכת להעלאה. דע\"י ההעלאה (יציאה ממציאותו, ביטול) מגיעים לענין זה שבבעל הרצון שהוא מובדל מהרצון. וע\"י ההמשכה שלאחרי ההעלאה נמשך ענין זה (שאוא\"ס הוא מובדל מהרצון) למטה, ועי\"ז מתבטלים הפגמים.\nח) <b>וזהו</b> כי תשא את ראש בני ישראל גו' ואיתא בגמרא אמר משה לפני הקב\"ה רבש\"ע במה תרום קרן ישראל אמר לו בכי תשא, דיש לומר ששני הענינים בכי תשא – נשיאת והגבהת הראש דבנ\"י והרמת קרן ישראל, הם <i>ע\"ד</i> שני הענינים דגמ\"ח, גמ\"ח כפשוטה וגמ\"ח דתפלה. והענין הוא, דהחלישות<sup data-n=\"54\">53</sup> (ירידה והשפלה) שנעשה ע\"י החטא בהראש דהנשמה, שאין ביכלתו להאיר בכחות הפנימיים, הואע\"ד סילוק האור שנעשה מצד הפגם, שהאור מסתלק לשרשו ואינו מאיר בהכלים<sup data-n=\"55\">54</sup>. וענין נשיאת והגבהת הראש [שכח הגילוי דבחינת ראש בהנשמה הוא בתוקף כמו שהי' תחלה, להאיר בכחות הפנימיים] שע\"י נתינת כופר לצדקה הוא <i>ע\"ד</i> הכפרה (מילוי הפגמים והחזרת הרצון) שע\"י גמילות חסד כפשוטה. והתמי' של משה היתה במה תרום <i>קרן</i> ישראל, דכיון שהירידה שבדרגת הקרן היא (לא שהחטא פעל בה ירידה, אלא) שלא נשלמה הכוונה שבשבילה ירדה למטה, תמה משה איך אפשר לתקן זה. ויש לומר, דזה שאמר משה <i>לפני הקב\"ה</i> במה תרום קרן ישראל, הוא כי בכדי לתקן זה שלא נשלמה הכוונה הוא ע\"י ההמשכה מעצמות אוא\"ס בעל הרצון <i>שמובדל</i> מהרצון, ולכן אמר זה משה לפני הקדוש ב\"ה שהוא קדוש ומובדל, ויתירה מזה, <i>לפני</i> הקב\"ה, בכדי להמשיך משם. אמר לו בכי תשא, בזה <i>שמשה</i> ישא את ראשם בהגבהה, שגם המשכת בחינת לפני הקב\"ה צריכה להיות ע\"י בחינת חכמה (ענינו של משה), וע\"ד הידוע שגם גילוי הסובב הוא ע\"י הממלא. ואף שהפעולה דמשה (מצד עצמו) היא כי תשא את <i>ראש</i>, נמשך בזה גם הכח דבחינת לפני הקב\"ה, שעי\"ז נעשה הרמת <i>קרן</i> ישראל.\n<b>ובכדי</b> שענין זה יומשך לישראל הוא ע\"י שנשיאת והגבהת הראש שלהם הוא ע\"י שמשה <i>לוקח</i> מהם כופר, כלשון רש\"י <i>קח</i> מהם כופר לצדקה, ענין ההעלאה שבצדקה. וע\"ד המבואר לעיל (סעיף ז), שע\"י גמ\"ח כפשוטה הוא המשכת <i>הרצון</i> מבעל הרצון, ובכדי להגיע לענין זה שבבעל הרצון שהוא <i>מובדל</i> מהרצון הוא ע\"י גמ\"ח דתפלה, המשכה ששייכת להעלאה, עד\"ז הוא בענין כופר נפשו, שע\"י <i>נתינת</i> הכופר לצדקה (המשכה) הוא המשכת הרצון, ועי\"ז נעשה נשיאת והרמת הראש. וע\"י שמשה <i>לוקח</i> מהם כופר לצדקה (ענין ההעלאה שבצדקה) הוא המשכת עצמות אוא\"ס שמובדל מהרצון, ועי\"ז תרום קרן ישראל, ובאופן דקרנו<sup data-n=\"56\">55</sup> תרום בכבוד.\n**********",[["1","*","יצא לאור ב<b>קונטרס כ\"ב שבט – תנש\"א</b>, \"לקראת יום ד' כ\"ב שבט – יאָרצייט-הילולא השלישי של הרבנית הצדקנית מרת חי' מושקא נ\"ע זי\"ע . . <i>יום ג'</i>,<i> כ\"א שבט</i>,<i> שנת ה'תנש\"א</i>\"."],["2","1","תשא ל, יב."],["3","2","ב\"ב יו\"ד, ב."],["4","3","תרס\"ה (נדפס בסה\"מ תרס\"ה ע' קפט ואילך – וראה שם ע' קצד-ה). פר\"ת (סה\"מ פר\"ת ע' רסג ואילך – וראה שם ע' רסו-ז)."],["5","4","בלקו\"ת ר\"פ במדבר, ש\"ראש\" הוא רצון התחתון שנולד מהשכל ו\"גולגולת\" הוא רצון העליון שלמעלה מהשכל. ויש לומר, שזהו בפרטיות, אבל בכללות – גם הגולגולת נכלל בהראש. ולכן, בהפסוק \"שאו את <i>ראש</i> גו' <i>לגולגלותם</i>\" (שבזה מדבר בלקו\"ת שם) – צריך לומר ש\"ראש\" הוא המוח [השכל שבמוח והרצון שע\"פ שכל], משא\"כ בפסוק כי תשא את ראש גו' (שלא נאמר בו לגולגלותם), יש לומר, שב\"ראש\" נכלל גם הגולגולת, הרצון שלמעלה מהשכל."],["6","5","תהלים לח, ה."],["7","6","ראה בדרושים הנ\"ל בפירוש הכתוב (ישעי' ב, ט. ה, טו) וישח אדם <i>וישפל</i> איש."],["8","7","דרושי שבת שובה סז, ד. וראה ד\"ה שובה ישראל תשל\"ו (לעיל ח\"א ע' פה ואילך)."],["9","8","פרש\"י עה\"פ תשא ל, טז."],["10","9","פרש\"י עה\"פ שם לג, יא."],["11","10","איכה ב, ג."],["12","11","דרושי ר\"ה נו, ב – הובא ברשימות הצ\"צ לאיכה שם (אוה\"ת נ\"ך כרך ב ע' א'עח)."],["13","12","ראה המשך תרס\"ו ע' רעג."],["14","13","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370275\" data-slug=\"torah-or\" data-id=\"3901370275\">תו\"א בשלח סא, סע\"ב</a>. אוה\"ת חנוכה שא, ב. וראה סידור עם דא\"ח עה\"פ וירם קרן (סז, א-ב)."],["15","14","תהלים קמח, יד."],["16","15","סה\"מ תרצ\"ז ע' 147 ואילך."],["17","16","משפטים כב, כד."],["18","17","שמו\"ר פרשתנו ס\"פ לא."],["19","18","ד\"ה אם כסף תלוה באוה\"ת פרשתנו ע' א'קסא ואילך. שם כרך ח ע' ג'יז ואילך. סה\"מ תרכ\"ז ע' קכג ואילך (וראה שם ע' קכה-ו). תרכ\"ט ע' סא ואילך. תרס\"ה ס\"ע קלח ואילך. ובכ\"מ."],["20","19","כ\"ה באוה\"ת שם ריש ע' א'קסו. כרך ח שם ע' ג'יח."],["21","20","הושע ו, ו."],["22","21","ראה תנחומא נשא טז. בחוקותי ג. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו."],["23","22","ברכות יד, סע\"ב."],["24","23","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380472\" data-slug=\"likkutei-torah\" data-id=\"4001380472\">לקו\"ת שלח (מ, סע\"א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380478\" data-slug=\"likkutei-torah\" data-id=\"4001380478\">שם מא, ג</a> ואילך. וראה גם דרושים שבהערה 18), דהטעם שמדמה ק\"ש ותפילין לזבח ונסכים הוא, כי ק\"ש הוא העלאה מלמטלמ\"ע ותפילין הוא המשכה מלמעלמ\"ט."],["25","24","כ\"ה הלשון ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380480\" data-slug=\"likkutei-torah\" data-id=\"4001380480\">לקו\"ת שם (מב, א</a>). ושם (מא, ג) \"שהקרבן אינו לריח ניחוח אלא עם הנסכים\". וראה לקו\"ת שם (מב, א) בהחצע\"ג."],["26","25","שם (מב, ג)."],["27","26","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310028\" data-slug=\"tanya\" data-id=\"3401310028\">תניא רפכ\"ג</a> \"שהמצוות הן פנימיות רצון העליון וחפצו האמיתי\". ופשוט, שקאי על כל המצוות, גם המצוות דקרבנות. ועכצ\"ל, דמ\"ש בהדרושים שבהערה 18 בנוגע לקרבנות – הכוונה בזה היא שהרצון דקרבנות הוא <i>דוגמת</i> חיצוניות הרצון. וראה הערה הבאה."],["28","27","אבל לא ממש. וי\"ל הביאור בזה: כשאדם רוצה לנסוע לאיזה מקום לקנות סחורה – באם הסחורה היתה נמצאת במקומו, לא הי' נוסע. משא\"כ בהנמשל, רצון העליון הוא שההמשכה שע\"י נסכים תהי' ע\"י העלאה דקרבנות. וזה שההמשכה תהי' דוקא ע\"י ההעלאה הוא לפי שכן הוא \"פנימיות רצון העליון וחפצו האמיתי\"."],["29","28","ר\"ה יח, א."],["30","29","סה\"מ תרכ\"ז שם ע' קכו. תרכ\"ט שם ע' סב."],["31","30","שמואל-א ג, יד."],["32","31","משלי לא, כו."],["33","32","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380217\" data-slug=\"likkutei-torah\" data-id=\"4001380217\">לקו\"ת אמור לב, סע\"ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380810\" data-slug=\"likkutei-torah\" data-id=\"4001380810\">פ' ראה כג, ג</a>."],["34","33","ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, ב</a>), ובלקו\"ת ראה שם בתחלת הענין, <i>שצדקה</i> היא כללות המצוות, ובהמשך הענין שם \"<i>גמ\"ח</i> כללות המצוות\"."],["35","34","אוה\"ת פרשתנו שם ע' א'קסג."],["36","35","ריש מס' פאה."],["37","36","שמעוני – רמז תקכב."],["38","37","תהלים פט, ג."],["39","38","שבת קכז, סע\"א ואילך."],["40","39","ד\"ה ה\"ג – שבת שם, ריש ע\"ב."],["41","40","משלי יא, יז."],["42","41","שמואל-א א, טו."],["43","42","כ\"ה בר\"ש פאה שם. ובמסורת הש\"ס שבת שם, שכצ\"ל גם בפרש\"י שבת שם."],["44","43","ראה רמב\"ם הל' תפלה פ\"א ה\"ד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380441\" data-slug=\"likkutei-torah\" data-id=\"4001380441\">לקו\"ת בהעלותך לב, ד</a>."],["45","44","ברכות כו, ב."],["46","45","שהש\"ר פ\"א, ט (ו)."],["47","46","שה\"ש א, ט. ועוד."],["48","47","זח\"ג ז, ב."],["49","48","פנחס כח, כג."],["50","49","כ\"ה בסה\"מ תרס\"ה שם ע' קמג-ד."],["51","50","וירא כא, ח."],["52","51","ראה <i>עד\"ז</i> <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191442\" data-slug=\"likkutei-sichot\" data-id=\"1300191442\">לקו\"ש חי\"ט ע' 428</a>. <i>וש\"נ</i>."],["53","52","כ\"ה להדיא בסה\"מ קונטרסים ח\"א קכו, א. ובסהמ\"צ להצ\"צ מצות וידוי ותשובה (לט, ב), דהמשכת הרצון חדש הוא \"מבחינת רעוא דרעוין מקור הרצונות\". ויש לומר, שהיינו הך – כי ההדגשה ד\"בעל הרצון\" בענין זה הוא שממנו יכול להיות תמיד המשכת הרצון, דזהו\"ע \"מקור הרצונות\"."],["54","53","ראה דרושים שבהערה 3, שמקשר זה עם (תוקפא דגופא) חולשא דנשמתא."],["55","54","ראה סה\"מ פר\"ת ע' עד. קונטרסים ח\"א קלד, סע\"ב ואילך."],["56","55","תהלים קיב, ט."]]],[1500380003,"<h3>בס\"ד. מוצאי ש\"פ משפטים, מבה\"ח אדר ראשון – בחדרו – ה'תשל\"ח<sup data-n=\"57\">*</sup></h3>\n<b>ואלה</b> המשפטים אשר תשים לפניהם<sup data-n=\"58\">1</sup>, ומדייק בזה כ\"ק אדמו\"ר הזקן בתו\"א ריש פרשתנו<sup data-n=\"59\">2</sup> דצלה\"ב דלפניהם משמע לשון רבים וכי תקנה הוא לשון יחיד, והול\"ל כי יקנו. גם ידוע הדיוק<sup data-n=\"60\">3</sup> מפני מה התחיל כל המשפטים בדין עבד עברי דוקא [דזהו גם כוונת המדרש<sup data-n=\"61\">4</sup> עה\"פ באמרו אני קניתי אתכם במצרים וכו', לבאר טעם התחלת ואלה המשפטים בדין עבד עברי]. ועוד כמה דיוקים עה\"פ, כמבואר בדרושי רבותינו נשיאינו ממלאי מקומו.\nב) <b>והענין</b> הוא, דהנה מ\"ש ואלה המשפטים וגו' הו\"ע כללי כמובן גם מפי' רז\"ל שקאי על כללות ענין לימוד התורה. וזהו ג\"כ מ\"ש תשים (ל' יחיד) דקאי על משה, כי ענינו של משה הו\"ע התורה<sup data-n=\"62\">5</sup>, ואח\"כ אומר לפניהם (ל' רבים), היינו שע\"י היתה המשכת התורה לכאו\"א מישראל עד סוף כל הדורות, וכמ\"ש<sup data-n=\"63\">6</sup> זכרו תורת משה עבדי, עד לתינוק המתחיל לדבר שאביו מלמדו תורה<sup data-n=\"64\">7</sup>, והיינו הפסוק<sup data-n=\"65\">8</sup> תורה צוה לנו <i>משה</i> גו'. וכמו\"כ ישנה הוראה כללית בפסוק זה גם באופן לימוד התורה, שצ\"ל באופן מסויים דוקא כדרז\"ל<sup data-n=\"66\">9</sup> במ\"ש תשים לפניהם שהרב שלמד כו' חוזר ושונה הדבר אפי' כמה פעמים עד שיבינו עומק ההלכה בטעמה היטב, ומוסיף עוד אדה\"ז בזה בסיום הל' ת\"ת שלו<sup data-n=\"67\">10</sup> דצריך אתה לשים לפניהם טעם המיישב תלמודם ומשימו בלבם [וי\"ל דבמ\"ש אדה\"ז שמשימו <i>בלבם</i> מפרש דמ\"ש (תשים) לפניהם היינו לפנימיותם<sup data-n=\"68\">11</sup>, דזהו כשמשימו בהלב], שזהו ענין כללי בלימוד התורה דכאו\"א מישראל (שהרי לימוד התורה היא מצוה שבגופו, שכל א' מחויב בה). וכמ\"ש<sup data-n=\"69\">12</sup> ושננתם לבניך ודרז\"ל<sup data-n=\"70\">13</sup> שיהיו דברי תורה שנונים ומחודדים בפיך (שזהו כענין הנ\"ל שההלכה צ\"ל ברורה ומסודרה וכו'), דזהו חיוב על כאו\"א מישראל[שהרי נוסף על החיוב דושננתם <i>לבניך</i>, צ\"ל השינון בדברי תורה גם בלימוד האב (והרב) עצמו, ואדרבה, דוקא עי\"ז שתחלה ישנו אצלו השינון בדברי תורה אפ\"ל אח\"כ ושננתם (גם) לבניך]. ועפ\"ז מובן<sup data-n=\"71\">14</sup> מ\"ש ואלה המשפטים אשר תשים לפניהם מיד לאחר פרשת מ\"ת, כי בפסוק זה ישנה הוראה כללית באופן [לימוד התורה דכאו\"א [הן בהלימוד עם עצמו, וכן בושננתם לבניך כפשוטו, ולבניך אלו התלמידים כדחז\"ל<sup data-n=\"72\">15</sup> עה\"פ] ע\"פ דרז\"ל הנ\"ל ובעיקר באופן] עבודת האדם לקונו.\nג) <b>וממשיך</b> הכתוב לבאר פרטי העבודה ובסדר מן הקל אל הכבד, דהרי העבודה צ\"ל באופן דמעט מעט אגרשנו<sup data-n=\"73\">16</sup>. והתחלת העבודה היא במ\"ש<sup data-n=\"74\">17</sup> כי תקנה עבד עברי גו', דבזה כלולים ב' בחינות בעבודה, בחי' עבד כנעני ובחי' עבד עברי, כמובן ממה דאיתא במכילתא<sup data-n=\"75\">18</sup> והובא בפרש\"י עה\"ת<sup data-n=\"75\">18</sup> (דמזה מובן שזהו גם ע\"פ פשש\"מ<sup data-n=\"76\">19</sup>) דעבד עברי היינו עבד שהוא עברי או אינו אלא עבדו של עברי (עבד כנעני שלקחתו מישראל) ת\"ל כו', דהמסקנה היא שקאי על עבד שהוא עברי, אך מ\"מ ישנו קס\"ד (גם בפשש\"מ כנ\"ל) שהוא עבד כנעני וצריכים לימוד מיוחד (ת\"ל) לשלול סברה זו, דמזה מובן שיש מקום לומר (בתור קס\"ד) דקאי גם על עבד כנעני. ובזה (בבחי' עבד כנעני) הוא תחלת העבודה<sup data-n=\"77\">20</sup>, ואח\"כ מתעלה בעבודתו ומגיע לבחי' עבד עברי, ועד שמגיע לבחי' אמה העברי', וכדלקמן.\nד) <b>והענין</b> הוא, כמבואר בהדרושים<sup data-n=\"78\">21</sup> בארוכה [ובפרט בהדרוש שכותב עליו כ\"ק אדמו\"ר הצ\"צ באוה\"ת<sup data-n=\"79\">22</sup> שהדרוש הזה מרבינו הגדול נ\"ע כו' והוא דרוש נכבד מאד וכו' והוא מענין מדריגת צדיק ורשע ובינוני הנזכר בתניא] דיש ג' מדריגות בנפש האדם, עבד כנעני, עבד עברי ואמה העברי', וענינם הוא ג' המדריגות נר\"ן, ומבואר שם שהם ענין צדיק ורשע ובינוני. ובזה הוא סדר העבודה דתחלה הוא העבודה דבחי' עבד כנעני ואח\"כ עבד עברי ואמה העברי', וכדאיתא בזהר בסבא דמשפטים<sup data-n=\"80\">23</sup> דב\"נ כד אתיליד יהבין לי' נפשא כו' זכה יתיר יהבין לי' רוחא כו' זכה יתיר יהבין לי' נשמתא, דמיד בשעת הלידה נמשך לכל אחד בחי' נפש (שבמדריגות הנשמה), שמצד בחי' זו העבודה היא בבחי' נפש, ואח\"כ ע\"י עבודתו עולה לבחי' רוח שהיא נעלית יותר, ועד שמגיע לבחי' נשמה (ולהעבודה שמצד בחינות אלו), כמבואר פרטי החילוקים שבהעבודה דנר\"ן בקונטרס העבודה<sup data-n=\"81\">24</sup>.ה) <b>והנה</b> בביאור ענין עבד כנעני שקו\"ט בהגהות והערות וביאורי כ\"ק אדמו\"ר הצ\"צ שבאוה\"ת<sup data-n=\"82\">25</sup> אם זהו בחי' רשע וטוב לו או בינוני הנזכר בתניא, ומסיים שם<sup data-n=\"83\">26</sup> דשניהם אמת. ולפ\"ז, בחי' עבד כנעני קאי הן על רשע והן על בינוני. ולכאורה צלה\"ב, דאיך אפשר שגם מי שהוא בבחי' עבד, דעבדא בהפקירא ניחא לי'<sup data-n=\"84\">27</sup> [שעיקר רצונו ונחת רוח שלו הוא בהפקירא כו' וילך אחר שרירות לבו, ומה שעושה ועובד הוא רק בע\"כ מצד אימת הדין שלא יכהו בשבט, כמבואר בארוכה בהדרושים<sup data-n=\"85\">28</sup>], יהי' בבחי' בינוני [ויקיים השבועה להיות בינוני<sup data-n=\"86\">29</sup>], שהרי הבינוני לא עבר עבירה מימיו ולא יעבור לעולם כמבואר בתניא<sup data-n=\"87\">30</sup>, וכידוע פתגם חסידים הראשונים דהלואי בינוני. אך הענין הוא, שלהיות בינוני הוא ביכלתו של כאו\"א (כולל זה דבהפקירא ניחא לי'<sup data-n=\"88\">31</sup>) כמובן מזה שבהשער ד\"ספר של בינונים\" (שענינו תוכן הספר) כותב כ\"ק אדה\"ז [וכידוע<sup data-n=\"89\">32</sup> שגם השער כתבו אדה\"ז] <i>דקרוב</i> אליך הדבר <i>מאוד</i><sup data-n=\"90\">33</sup> בפיך ובלבבך לעשותו<sup data-n=\"91\">34</sup>, ובפנים התניא<sup data-n=\"92\">35</sup> כותב עוד דמדת הבינוני היא מדת <i>כל אדם</i> [והיינו דגם מצד מדידה והגבלה (דענין המדה (מדת) שייך לומר רק כשישנו גדר מדוה\"ג) הנה בחי' הבינוני היא לפי\"ע ומדידת <i>כל אדם</i>, כי יהי' מי שיהי' מישראל (כל אדם) הוא בכלל אתם קרויין <i>אדם</i><sup data-n=\"93\">36</sup> ע\"ש אדמה לעליון<sup data-n=\"94\">37</sup>. ויתירה מזו (כמו שממשיך בתניא שם) ד]ואחרי' כל אדם<sup data-n=\"95\">38</sup> ימשוך [דבזה (בתיבת ימשוך) ב' פירושים –כמו בואהבת<sup data-n=\"96\">39</sup> – ציווי והבטחה לעתיד]. וטעם הדבר הוא, כי אף זה דבהפקירא ניחא לי' (כנ\"ל) זהו רק בחיצוניות, אבל פנימיותו – מדת כל אדם ואחרי' כל אדם ימשוך – הוא מה שהוא חלק אלוקה ממעל ממש<sup data-n=\"97\">40</sup>, וכפס\"ד הרמב\"ם הידוע<sup data-n=\"98\">41</sup> דכשכופין אותו (כי לי' ניחא בענין אחר) ואומר רוצה אני הרי\"ז רצונו האמיתי [כי מה דבהפקירא ניחא לי' איז דאָס ניט ער כ\"א יצרו אנסו], ובודאי תבוא (הפנימיות שלו) בפועל כנ\"ל (דימשוך הוא לשון עתיד והבטחה) בפיך ובלבבך לעשותו, במחדו\"מ, כולל קיום השבועה דמשביעין אותו<sup data-n=\"99\">42</sup> (עכ\"פ אל תהי רשע (כ\"אבינוני&lt;29&gt;)) כבתניא [דזהו ג\"כ הפי' בואחרי' כל אדם ימשוך, שהאדם (מצד נשמתו) נמשך להיות בינוני, וואָס דאָס נעמט אים אַרויס מאיזה מעמד ומצב שיהי' בעבודתו], כי בודאי ש(גם אם צריך לעשות תשובה<sup data-n=\"100\">43</sup>) סופו לעשות תשובה וכההבטחה<sup data-n=\"101\">44</sup> כי לא ידח ממנו נדח<sup data-n=\"102\">45</sup> [ואדרבה, ע\"י התשובה יבוא לדרגא נעלית יותר, כמאמר<sup data-n=\"103\">46</sup> במקום שבע\"ת עומדין אין צדיקים גמורין יכולין לעמוד בו]. ועד אשר מצד הפנימיות שלו, הנה תמיד <i>קרוב</i> הוא לזה (שיהי' בפיך ובלבבך לעשותו, במחדו\"מ – כבינוני) <i>מאוד</i>. ועפ\"ז יובן גם בנדו\"ז דאף שעבד כנעני בהפקירא ניחא לי' מ\"מ מדריגתו היא בחי' הבינוני, כי סו\"ס בודאי יאמר רוצה אני (מצד הפנימיות שלו) כי לא ידח כו'.\nו) <b>והנה</b> זה שאפשר להיות קס\"ד בתורה ד\"או אינו אלא עבדו של עברי\" אבל הוא עצמו עבד כנעני, והיינו שתהי' דרגת העבודה בבחי' עבד כנעני דבהפקירא ניחא לי', הוא רק מצד ירידת הנשמה למטה, שירדה מאיגרא רמה לבירא עמיקתא<sup data-n=\"104\">47</sup>. [וגם אז אין קס\"ד שיהי' עבד כנעני לגמרי ח\"ו כ\"א \"עבדו (כנעני) של עברי\", דישנה עליו השפעת ואדנות של \"עברי\", כי גם מי שהוא בדרגא הכי פחותה שבישראל (בבחי' עבד כנעני, מצד ירידת הנשמה למטה) מ\"מ להיותו בן לאברהם אבינו [דאחד הי' אברהם<sup data-n=\"105\">48</sup>, אברהם <i>העברי</i><sup data-n=\"106\">49</sup>] יש לו בירושה האהבה (והיראה) המסותרת כמבואר בארוכה בתניא<sup data-n=\"107\">50</sup>, שאהוי\"ר זו פועלת אצל כאו\"א (גם אם נדמה לו דבהפקירא ניחא לי', שרצונו הוא בענינים אחרים, גם בענינים כאלו שהם היפך הרצוי ח\"ו) אַז ער מוז טאָן ווי דער אויבערשטער וויל, ולכן אא\"פ שיהי' כנעני לגמרי ח\"ו כ\"א עבד כנעני של עברי, שבגלוי הוא בבחי' עבד כנעני, אבל נמצא בו (בהעלם) האהבה המסותרת שבירושה מאברהם העברי]. וכוונת ירידה זו, שישנו קס\"ד בתורה ד\"או אינו אלא עבדו של עברי\", היא רק בכדי שע\"י עבודתו ב\"תלמוד לומר\" – לימוד התורה באופן שילמוד ממנה מהו רצון התורה – הנה יראה מיד ויגלה האמיתיות שלו ש\"אף כאן עבד שהוא עברי\"<sup data-n=\"108\">51</sup>, ושהוא בעצמו הוא עברי (ולא שהוא כנעני ויש עליו רק אדנות העברי), והיינו שמקומו ומדרגתו הוא בבחי' עבר הנהר<sup data-n=\"109\">52</sup>, וגם כדאיתא במדרש<sup data-n=\"110\">53</sup> דמה שאברהם נקרא אברהם העברי הוא ע\"ש שכל העולם כולו מעבר אחד והוא מעבר אחד, וכן פועל בעבודתו להיות (עבד) עברי,אַז ער שטעלט זיך אַנטקעגן דער גאַנצער וועלט, מתחיל מהעלם והסתר (עולם מלשון העלם<sup data-n=\"111\">54</sup>) נפשו הבהמית, ומהפך אותה, והולך ועולה מדרגא לדרגא, מבחי' עבד כנעני (שלקחתו מישראל) לבחי' עבד (שהוא) עברי, ואח\"כ גם לבחי' אמה העברי', ועד שפועל בעבודתו שיהי' לו או לבנו יעדנה<sup data-n=\"112\">55</sup> כמבואר בארוכה בדרוש הנכבד לרבינו הגדול נ\"ע הנ\"ל<sup data-n=\"113\">56</sup>.\nז) <b>והנה</b> כללות ענין הנ\"ל ישנו גם בעבודת כאו\"א בכל יום<sup data-n=\"114\">57</sup>. והענין הוא, דבחי' עבד כנעני הוא כאשר ישראל הם בבחי' התלבשות בעניני העולם בכדי<sup data-n=\"115\">58</sup> לברר אותם, וכמ\"ש<sup data-n=\"116\">59</sup> ועשית כל מלאכתך, שצ\"ל מלאכה בעניני עוה\"ז הגשמי וגם בחומריות העולם בכדי להפכו לקדושה, שמצד התלבשות זו בעניני העולם, ע\"י הבירור אפשר שיתדבק בהמברר ענין בלתי רצוי מדבר המתברר כדאיתא בתניא<sup data-n=\"117\">60</sup>, ועי\"ז אפשר שיהי' נראה בתחלת העבודה כבחי' עבד כנעני. אמנם ירידה זו היא לצורך עלי', ולכן היא לרגע בלבד, ומיד לאח\"ז היא התחלת העלי', ויתירה מזו הנה ע\"י הירידה נעשה עלי' ביתר שאת ויתר עוז, ע\"ד המבואר בתניא<sup data-n=\"118\">61</sup> בנוגע לענין המבלבל את האדם בתפלתו, שמהבלבול עצמו צריך להתעורר להתפלל יותר בכוונה מעומקא דלבא. והוא כשיתבונן שמכיון שהקב\"ה הוא המחי' את הענין המבלבלו הנה בודאי שזה שהראו לו (מלמעלה) בלבול זה, והבלבול נמצא בתוך הד\"א שלו, ועד שגם מבלבלו בתפלתו, הוא (לא מפני שהוא ענין בפ\"ע ח\"ו, כ\"א) רק בכדי שהאדם ע\"י עבודתו יעשה מהבלבול מטעמים ל' רבים, תחלה ע\"י העבודה שבבחי' אתכפיא (כללות עבודת הבינונים), עד שיגיע גם לבחי' אתהפכא (כללות עבודת הצדיקים) כמבואר בתניא<sup data-n=\"119\">62</sup>, ועד\"ז הוא בענין הנ\"ל שמהירידה גופא צריך להתעורר ביתר שאת לעבוד עבודתו בבחי' עבד כנעני, עבד עברי ואמה העברי', עד שיגיע להיות לו או לבנו יעדנה, ועד ויצאה חנם אין כסף<sup data-n=\"120\">63</sup> [שכ\"ז הוא כללות העבודה דאתכפיא ואתהפכא הנ\"ל] כמבואר בארוכה בדרוש הנ\"ל.\n<b>וע\"י</b> עבודה הנ\"ל דשש שנים יעבוד, ד(יעבוד) קאי על כללות עבודת האדם לקונו, הנה מגיעים לובשביעית (יצא לחפשי חנם)<sup data-n=\"121\">64</sup>, דקאי על השלימות הכי נעלית שתהי' לע\"ל, יום<sup data-n=\"122\">65</sup> שכולו שבת ומנוחה לחיי העולמים<sup data-n=\"123\">66</sup>, שאז יהי' גילוי אלקותלמטה, דירה לו ית' בתחתונים [ומעין גילוי זה מאיר גם עתה בשבת<sup data-n=\"124\">67</sup> ובפרט<sup data-n=\"125\">68</sup> בהזמן דרעוא דכל רעוין].\nח) <b>ויש</b> לקשר זה עם ענין המשכן המבואר בפ' תרומה [פרשת שבוע הבא שקראו בשבת בזמן המנחה, כי אז הוא כבר התחלת השייכות למוצאי שבת], שענינו הוא להיות על ידו ושכנתי בתוכם<sup data-n=\"126\">69</sup>. ובעיקר היתה השראה זו ע\"י הארון [שלכן הקדים ציווי עשיית הארון לכל שאר עניני המשכן, כי פנימיות ותכלית כוונת כל המשכן הי' (השראת השכינה שב)הארון כמבואר בארוכה ברמב\"ן עה\"ת<sup data-n=\"127\">70</sup>. וזהו ע\"ד פירוש המדרש שהובא לעיל דמה שהתחיל ואלה המשפטים בדין עבד עברי דוקא הוא כי במצוה זו מרומזת הנקודה הפנימית שבעבודתם של ישראל – דאני נבראתי לשמש את קוני<sup data-n=\"128\">71</sup>, וכמבואר במדרש שם דאני קניתי אתכם במצרים כו'. ועד\"ז גם בעבודה בפועל שמקדים תחלה תכלית העבודה, שהיא המשכת השכינה ע\"י הארון] שע\"י נמשך לעשות לו ית' דירה בתחתונים. דע\"י שתחלה הוא ושכנתי בתוכם<sup data-n=\"129\">72</sup>, בתוך כאו\"א<sup data-n=\"130\">73</sup>, הנה אח\"כ נמשך להיות ושכנתי בתוכם כפשוטו בהמשכן ובביהמ\"ק ועד לכל העולם כולו (וזה יהי' בשלימות בשביעית, באלף השביעי<sup data-n=\"131\">74</sup>). והעבודה לפעול המשכת השכינה היא עשיית הארון שהו\"ע התורה, שעי\"ז נמשכת אח\"כ השכינה גם בעולם, כי נר מצוה ותורה אור<sup data-n=\"132\">75</sup>, שהתורה מאירה<sup data-n=\"133\">76</sup> ומראה דרכו של כאו\"א מישראל לדעת את המעשה אשר יעשון<sup data-n=\"134\">77</sup> ואלה אשר לא תעשינה<sup data-n=\"135\">78</sup>. ותחלה ממשיכים השראת השכינה בזהב וכסף ונחושת וגו'<sup data-n=\"136\">79</sup> של המשכן, ומהמשכן ומקדש הנה אורה יוצאה לעולם<sup data-n=\"137\">80</sup>, עד שהעולם מתמלא מאור זה באופן גלוי, וכמאמר<sup data-n=\"138\">81</sup> עתידה ירושלים שתתפשט בכל ארץ ישראל ועתידה ארץ ישראל שתתפשט בכל הארצות בגאולה האמיתית והשלימה. דגאולה זו תלוי' במעשינו ועבודתינו בהשיתא אלפי שני דהוה עלמא<sup data-n=\"139\">82</sup>, ובפרטבהעבודה שבזמן הגלות<sup data-n=\"140\">83</sup>, ובמיוחד בהעבודה שבסיום וחותם זמן הגלות בעקבתא דמשיחא [והכל הולך אחר החיתום<sup data-n=\"141\">84</sup>], שעי\"ז מביאים הגאולה שאז יבנה ביהמ\"ק במקומו בגלוי וכפשוטו, ובהעילוי שיהי' בביהמ\"ק השלישי דמקדש אד' כוננו ידיך<sup data-n=\"142\">85</sup> שזהו למעלה גם מביהמ\"ק הראשון והשני<sup data-n=\"143\">86</sup> וגם למעלה מהעילוי שהי' במשכן. דאף שהמשכן הי' מעשה ידי משה ומעשי ידי משה הם נצחיים כדאיתא בגמרא<sup data-n=\"144\">87</sup> ומשו\"ז גם המשכן הוא נצחי, מ\"מ ע\"י עבודת ישראל בזמן הגלות יהי' (בביהמ\"ק השלישי) עילוי שלמעלה גם ממעלת המשכן [בדוגמת העילוי שבמשיח על משה רבינו<sup data-n=\"145\">88</sup>], שיהי' העילוי דעבודת התשובה, שמהעלם והסתר העולם גופא עושים דירה לו ית' בתחתונים, וכידוע דענינו של משיח הו\"ע התשובה<sup data-n=\"146\">89</sup>, כמאמר<sup data-n=\"147\">90</sup> משיח אתא לאתבא צדיקיא בתיובתא. ויצא חוטר מגזע ישי ונצר משרשיו יפרה<sup data-n=\"148\">91</sup> עד שומלאה הארץ דעה את הוי' כמים לים מכסים<sup data-n=\"149\">92</sup>, בגאולה האמיתית והשלימה.\n<b>וע\"י</b> עבודה הנ\"ל הנה ממהרים, מזרזים ומחישים עוד יותר את ביאתה, שבאה בהקדם הכי גדול בימינו ממש למטה מעשרה טפחים. ויהי' נראה בגלוי דוהלכו גוים לאורך<sup data-n=\"150\">93</sup>, והיו מלכים אומניך ושרותיהם מניקותיך<sup data-n=\"151\">94</sup>, וכן תהי' לנו עוד בימים האחרונים שבימי הגלות, דהגם דאכתי עבדי אחשורוש אנן<sup data-n=\"152\">95</sup> מ\"מ גם אז נפל פחד היהודים עליהם<sup data-n=\"153\">96</sup> ועד אשר אחשורוש עצמו בעט זיך און גיט את בית המן לאסתר המלכה<sup data-n=\"154\">97</sup>, וזהו הכנה קרובה לקיום היעוד<sup data-n=\"155\">98</sup> דאז אהפוך אל עמים שפה ברורה וגו', בגאולה האמיתית והשלימה ע\"י משיח צדקנו.\n**********",[["57","*","יצא לאור בשעתו, \"<i>ז' אד\"ר ה'תשל\"ח</i>\"."],["58","1","משפטים כא, א."],["59","2","<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550758\" data-slug=\"torat-chaim\" data-id=\"2300550758\">עד, ג</a>. וראה ג\"כ <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550833\" data-slug=\"torat-chaim\" data-id=\"2300550833\">תו\"ח שמות תט, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550047\" data-slug=\"torat-chaim\" data-id=\"2300550047\">תכה, ב</a> [בהוצאה החדשה – משפטים ח\"ב רעז, א. רפד, א]. דרמ\"צ פ, א."],["60","3","אוה\"ת משפטים ע' א'עז. וראה ג\"כ <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161255\" data-slug=\"likkutei-sichot\" data-id=\"1300161255\">לקו\"ש חט\"ז ע' 255</a> ובהנסמן שם בהערה 34."],["61","4","שמו\"ר פ\"ל, ה. הובא באוה\"ת שם."],["62","5","ראה שמו\"ר שם, ד. וש\"נ."],["63","6","מלאכי ג, כב."],["64","7","סוכה מב, א. הל' ת\"ת לאדה\"ז רפ\"א."],["65","8","ברכה לג, ד."],["66","9","ראה עירובין נד, ב. ובפרש\"י שם ד\"ה להראות. רמב\"ם הל' ת\"ת פ\"ד ה\"ד. הל' ת\"ת לאדה\"ז פ\"ד סי\"ח."],["67","10","שם."],["68","11","ראה ג\"כ <a class=\"ft-cite\" href=\"#/read/torah-or/3901370336\" data-slug=\"torah-or\" data-id=\"3901370336\">תו\"א שם עה, ג</a>. אוה\"ת שם ע' א'קכ. ועוד."],["69","12","ואתחנן ו, ז. וראה שיחת כ\"ד טבת שנה זו (תשל\"ח) סוף סי\"ד ובהערות שם (נדפסה ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211280\" data-slug=\"likkutei-sichot\" data-id=\"1300211280\">לקו\"ש חכ\"א ע' 280</a>)."],["70","13","ספרי ופרש\"י שם. קידושין ל, סע\"א. הל' ת\"ת לאדה\"ז פ\"ב ס\"ג."],["71","14","וראה ג\"כ <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161243\" data-slug=\"likkutei-sichot\" data-id=\"1300161243\">לקו\"ש חט\"ז ע' 243</a> ס\"ד ואילך (באופן אחר)."],["72","15","ספרי ופרש\"י."],["73","16","משפטים כג, ל."],["74","17","שם כא, ב."],["75","18","עה\"פ שם."],["76","19","ראה בארוכה לקו\"ש הנ\"ל."],["77","20","ובקרא (המסקנא היא ד)מתחיל בע\"ע, וי\"ל שהוא ע\"ד המבואר בקונטרס העבודה (פ\"ב ואילך) דהתפלה ענינה פולחנא <i>דרחימותא</i> ואף שצ\"ל עבודת היראה ה\"ז קודם לזה ולא זו היא העבודה דתפלה."],["78","21","<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550052\" data-slug=\"torat-chaim\" data-id=\"2300550052\">תו\"ח שם עא, ב</a> ואילך [בהוצאה החדשה – משפטים ח\"ב רצג, א ואילך]. דרך חיים שער התפלה פס\"ו ואילך. דרמ\"צ שם ואילך. אוה\"ת שם ע' א'קמ ואילך."],["79","22","שם ע' א'קכז."],["80","23","צד, ב."],["81","24","בתחלתו ואילך."],["82","25","שם ע' א'קכח."],["83","26","ע' א'קכט."],["84","27","גיטין יג, א."],["85","28","אוה\"ת שם ע' א'קכח. ובכ\"מ."],["86","29","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310019\" data-slug=\"tanya\" data-id=\"3401310019\">תניא פי\"ד (כ, א</a>)."],["87","30","רפי\"ב."],["88","31","ראה דרך חיים שם דמשמע דבהפקירא ניחא לי' היינו לכל הדרגות דעבד כנעני."],["89","32","ראה לקוטי ביאורים לתניא (להר\"י קאָרף) ע' תכח."],["90","33","שזהו עוד יותר מיכולת סתם (כ\"א קרוב ומאוד – וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310022\" data-slug=\"tanya\" data-id=\"3401310022\">תניא פי\"ז</a> ואילך)."],["91","34","לשון הכתוב – נצבים ל, יד."],["92","35","רפי\"ד."],["93","36","יבמות סא, א."],["94","37","של\"ה כ, ב. רסח, ב. שא, ב. ובכ\"מ."],["95","38","להעיר מכפל הל' \"כל אדם\". וי\"ל שבזה מדגיש עוד יותר איך שזהו מדתו ולזה ימשוך כל א' מישראל יהי' מי שיהי'. ראה יומא נא, ב."],["96","39","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370388\" data-slug=\"torah-or\" data-id=\"3901370388\">תו\"א תשא פו, ג</a>. ובכ\"מ."],["97","40","<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>."],["98","41","הל' גירושין ספ\"ב."],["99","42","נדה ל, ב. <a class=\"ft-cite\" href=\"#/read/tanya/3401310006\" data-slug=\"tanya\" data-id=\"3401310006\">תניא רפ\"א</a>."],["100","43","ואין זה סתירה למה שהובא לעיל מתניא דהבינוני \"לא עבר עבירה מימיו\" – כי הפירוש הוא <i>שעכשיו</i> (לאחרי שעשה תשובה) הוא במצב ש\"לא עבר עבירה מימיו\" שלא נשאר רושם כלל מהעבירה שעשה. וראה בליקוט פירושים וכו' לתניא פי\"ב (ע' רכט) הע' 4."],["101","44","ע\"פ ש\"ב יד, יד."],["102","45","<a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא ספל\"ט</a>. וראה הל' ת\"ת לאדה\"ז פ\"ד ס\"ג."],["103","46","רמב\"ם הל' תשובה פ\"ז ה\"ד."],["104","47","ראה חגיגה ה, ב."],["105","48","יחזקאל לג, כד."],["106","49","לך לך יד, יג."],["107","50","פי\"ח."],["108","51","מכילתא שם."],["109","52","לשון הכתוב – יהושע כד, ב. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370337\" data-slug=\"torah-or\" data-id=\"3901370337\">תו\"א משפטים עה, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550837\" data-slug=\"torat-chaim\" data-id=\"2300550837\">תו\"ח שם תיא, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550207\" data-slug=\"torat-chaim\" data-id=\"2300550207\">תכו, ב</a> [בהוצאה החדשה – ח\"ב רעח, ב. רפד, ב]. דרמ\"צ פב, ב. ובכ\"מ."],["110","53","ב\"ר פמ\"ב, ח."],["111","54","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380463\" data-slug=\"likkutei-torah\" data-id=\"4001380463\">לקו\"ת שלח לז, ד</a>. ובכ\"מ."],["112","55","משפטים שם, ח-ט."],["113","56","וראה גם בהמקומות שנסמנו לעיל בהערה 21."],["114","57","ראה ג\"כ אוה\"ת שם ר\"ע א'קלח, א'קמז."],["115","58","שזה כנעני – גם לשון כנען, סוחר (כמבואר בדרושים הנ\"ל)."],["116","59","יתרו כ, ט. וראה מכילתא דרשב\"י עה\"פ. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171245\" data-slug=\"likkutei-sichot\" data-id=\"1300171245\">לקו\"ש חי\"ז ע' 245</a> הע' 20."],["117","60","פכ\"ח (לה, ב)."],["118","61","אגה\"ק סכ\"ה (קמא, א). וראה ג\"כ ד\"ה וארא דמוצאי ש\"פ וארא שנה זו (תשל\"ח)."],["119","62","פכ\"ז."],["120","63","משפטים שם, יא."],["121","64","שם, ב."],["122","65","תמיד בסופה."],["123","66","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370338\" data-slug=\"torah-or\" data-id=\"3901370338\">תו\"א שם עו, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370340\" data-slug=\"torah-or\" data-id=\"3901370340\">עו, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550777\" data-slug=\"torat-chaim\" data-id=\"2300550777\">תו\"ח שם תיא, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550796\" data-slug=\"torat-chaim\" data-id=\"2300550796\">תטז, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550833\" data-slug=\"torat-chaim\" data-id=\"2300550833\">תכה, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550841\" data-slug=\"torat-chaim\" data-id=\"2300550841\">תכז, ב</a> ואילך [בהוצאה החדשה – ח\"ב רעח, ב. רפא, ב. רפה, א ואילך. רצב, ב]. דרמ\"צ פג, א ואילך. וראה ג\"כ אוה\"ת שם ס\"ע א'קכב ואילך."],["124","67","להעיר משמו\"ר שם, ה (הובא באוה\"ת שם ס\"ע א'עז ואילך): לא תעבוד באחיך יותר מששה שנים שלא בראתי את העולם אלא לששה ימים כו'. רמב\"ן משפטים כא, ג."],["125","68","ראה המשך תרס\"ו בסופו (ע' תקמד ואילך)."],["126","69","תרומה כה, ח."],["127","70","ר\"פ תרומה. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111128\" data-slug=\"likkutei-sichot\" data-id=\"1300111128\">לקו\"ש חי\"א ע' 120</a> ואילך. וב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041345\" data-slug=\"likkutei-sichot\" data-id=\"1300041345\">לקו\"ש ח\"ד ע' 1346</a> <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041026\" data-slug=\"likkutei-sichot\" data-id=\"1300041026\">הע' 24</a> שכ\"ה גם לשיטת הרמב\"ם. וראה ג\"כ שם הע' 26."],["128","71","קידושין בסופה."],["129","72","וכמו שהמשכן בא לאחרי יוהכ\"פ."],["130","73","ר\"ח שער האהבה פ\"ו קרוב לתחלתו. ובכ\"מ."],["131","74","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו</a> בהג\"ה."],["132","75","משלי ו, כג."],["133","76","להעיר משמו\"ר רפ\"נ: פתח דבריך יאיר וכו' פותחין באורה וכו' פתח בארון שנא' ועשו ארון, ובמ\"כ שם: שבו כו' התורה שנק' אור."],["134","77","יתרו יח, כ."],["135","78","ויקרא ד, ב."],["136","79","תרומה שם, ג."],["137","80","ירושלמי ברכות פ\"ד ה\"ה. וראה פרש\"י ד\"ה שקופים – מנחות פו, ב."],["138","81","יל\"ש ישעי' רמז תקג."],["139","82","ר\"ה לא, א."],["140","83","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>."],["141","84","ברכות יב, א."],["142","85","בשלח טו, יז ובפרש\"י. וראה פרש\"י ותוס' סוכה מא, סע\"א. תוס' שבועות טו, רע\"ב. ועוד."],["143","86","ראה בארוכה ד\"ה גדול יהי' כבוד הבית ה'תשכ\"ב (לקמן ח\"ד ע' קיא ואילך). ד\"ה איכה ישבה ה'תשל\"א (שם ע' קנב ואילך)]. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091026\" data-slug=\"likkutei-sichot\" data-id=\"1300091026\">לקו\"ש ח\"ט ע' 26</a> ואילך. וש\"נ."],["144","87","סוטה ט, סע\"א."],["145","88","ראה תנחומא ס\"פ תולדות. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380144\" data-slug=\"likkutei-torah\" data-id=\"4001380144\">לקו\"ת צו יז, א</a>."],["146","89","וגם הגאולה עצמה תבוא ע\"י התשובה – ראה רמב\"ם הל' תשובה פ\"ז ה\"ה. במקומות שנסמנו לעיל בהע' 86."],["147","90","הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381329\" data-slug=\"likkutei-torah\" data-id=\"4001381329\">לקו\"ת שמע\"צ צב, ב</a>. שה\"ש נ, סע\"ב. וראה זח\"ג קנג, ב."],["148","91","ישעי' יא, א."],["149","92","שם, ט."],["150","93","שם ס, ג."],["151","94","שם מט, כג."],["152","95","מגילה יד, א."],["153","96","אסתר ח, יז."],["154","97","ראה שם, א. ולהעיר משמו\"ר פ\"ל, ד שישראל נקראו על שמה של אסתר."],["155","98","צפני' ג, ט."]]],[1500380004,"<h3>בס\"ד. ש\"פ משפטים, פ' שקלים, מבה\"ח וער\"ח אדר ה'תש\"מ<sup data-n=\"156\">*</sup></h3>\n<b>זה</b> יתנו כל העובר על הפקודים מחצית השקל בשקל הקודש עשרים גרה השקל מחצית השקל תרומה לה' וגו'<sup data-n=\"157\">1</sup> ומסיים<sup data-n=\"158\">2</sup> לכפר על נפשותיכם. ומדייק בהמאמר דש\"פ משפטים ופ' שקלים תר\"פ (פר\"ת)<sup data-n=\"159\">3</sup>, דצלה\"ב מהו\"ע ב\"פ מחצית בשקל, שאומר מחצית השקל בשקל הקודש, וכופל עוד מחצית השקל תרומה לה'. גם מהו\"ע עשרים גרה השקל, שהרי צריך ליתן רק מחצית השקל. גם צלה\"ב מ\"ש לכפר על נפשותיכם, וכמו שממשיך ומבאר שם דענין מחצית השקל הוא לכפר על חטא העגל<sup data-n=\"160\">4</sup>, וצלה\"ב מהו מעלת מחצית השקל כ\"כ שמכפר על החטא. ויש להוסיף בזה (בתור הערה בדא\"פ), דחטא העגל הוא חטא כללי והוא המקור והשורש לכל החטאים ועונות ופשעים. וכדאיתא בגמרא<sup data-n=\"161\">5</sup> דבשעת מ\"ת פסקה זוהמתן (שהטיל נחש בחוה), ואחרי חטא העגל חזרה<sup data-n=\"162\">6</sup>. והגם שלא חזרה לגמרי כמו שהיתה לפני זה<sup data-n=\"163\">7</sup>, שהרי גם אחרי חטא העגל נשאר ענין הבחירה בעם ישראל, ובנו בחרת<sup data-n=\"164\">8</sup>, בהגוף החומרי הנדמה בחומריותו לגופות אומות העולם<sup data-n=\"165\">9</sup> (וראה בגמרא שם<sup data-n=\"166\">10</sup> מפני מה עכו\"ם מזוהמים כו'), מ\"מ הרי חטא העגל הוא החטא הכללי, ועליו כתיב<sup data-n=\"167\">11</sup> וביום פקדי (על כל חטא) ופקדתי וכו'. ולפי זה דרוש ביאור ביותר מהי מעלת מחצית השקל שמכפר על חטא זה. והנה מתרומה זו (דמחצית השקל) קנו את הקרבנות ציבור במשך כל השנה, דענין הקרבנות עתה הוא ענין התפלה, וכמרז\"ל<sup data-n=\"168\">12</sup> תפלות במקום קרבנות תקנום, ומזה מובן, דענין מחצית השקל ישנו ג\"כ בעבודת התפלה.\nב) <b>ולהבין</b> כ\"ז ממשיך לבאר בהמאמר<sup data-n=\"169\">13</sup> ענין התפלה, ומביא ע\"ז מארז\"ל<sup data-n=\"170\">14</sup> אין עומדין להתפלל אלא מתוך כובד ראש. ויש להוסיף בזה, ע\"פ מ\"ש בתוס' במס' מנחות<sup data-n=\"171\">15</sup> שהלשון אין כו' אלא כו' בא למעט שפסול בדיעבד. וכן הואפירוש הענין בפשטות, דאין עומדין להתפלל, היינו שאינו שייך ענין התפלה, אלא מתוך כובד ראש. ומביא ע\"ז את פירוש הרב המגיד נ\"ע<sup data-n=\"172\">16</sup> שהתפלה תהי' על הכובד שבראש, דכאשר מתפלל על החסרון לא יתפלל על החסרון שלו כ\"א על החסרון שלמעלה, כי לא יש חסרון למטה שלא יש חסרון למעלה. ומבאר, דענין החסרון שלמעלה הוא כמרז\"ל<sup data-n=\"173\">17</sup> בזמן שהאדם מצטער השכינה מה לשון אומרת כבי' קלני מראשי קלני מזרועי, דשכינה היא בחי' המלכות שיש בה עליות וירידות וכו'. וזהו\"ע הכובד ראש דשכינה, וזהו אין עומדין להתפלל אלא מתוך כובד ראש, היינו על הכובד והחסרון שבראש. ואח\"כ מביא את פירוש רבינו הזקן (וכ\"ה גם בד\"ה אין עומדין להתפלל לכ\"ק מו\"ח אדמו\"ר<sup data-n=\"174\">18</sup>) דראש קאי על נשמות ישראל. ישראל לי ראש, ובזה ישנו ענין הכובד ראש שע\"י העונות, וכמ\"ש<sup data-n=\"175\">19</sup> כי עונותי עברו ראשי כמשא כבד יכבדו ממני.\n<b>וזהו</b> אין עומדין להתפלל אלא מתוך כובד ראש, וע\"י התפלה הנה לא זו בלבד שמבטל את הכובד ראש, אלא עוד זאת שנעשה שאו את ראש גו' בני ישראל גו' לגולגלותם<sup data-n=\"176\">20</sup> (כמבואר בלקו\"ת ר\"פ במדבר), שמגבי' את ראש עד לבחי' גולגלותם, שלמעלה מהראש. והוא ע\"י העבודה בבירור נה\"ב, שעי\"ז מגבי' את הראש דנה\"א, כי שרש נה\"ב הוא מבחי' התוהו שקדם לתיקון, כי עשו הוא בנה הגדול<sup data-n=\"177\">21</sup>, והאורות מרובים דתוהו מעלים את האורות דתיקון.\nג) <b>וזהו</b> ענין מחצית השקל, שהנתינה מלמטה היא רק מחצית<sup data-n=\"178\">22</sup>, וכתורת הה\"מ<sup data-n=\"179\">23</sup> עשה לך שתי חצוצרות<sup data-n=\"180\">24</sup>, שתי חצאי צורות, שהקב\"ה וכנס\"י הם ב' חצאי צורות המשלימים זא\"ז כביכול, וכמרז\"ל<sup data-n=\"181\">25</sup> תמתי תאומתי. היינו, שע\"י עבודתו בעשר הכחות שלו ה\"ה פועל עלי' גם למעלה. ובעבודתו גופא ענין מחצית השקל הוא, שמעלה את עשר הכחות דנה\"ב, ועי\"ז פועל עלי' בנה\"א, וכנ\"ל דהאורות מרובים דתוהו מעלים את האורות דתיקון.\n<b>ויש</b> לומר, דזהו גם הקישור<sup data-n=\"182\">26</sup> דב' הפירושים בכובד ראש, ראש שלמעלה וראש דנשמה (נה\"א). כי כשם שע\"י בירור עשר כחות דנה\"ב, עשר גרה, מעלים את המחצית העליון, עשר כחות דנה\"א, עד\"ז הוא להפי' דקאי על ראש שלמעלה, כיע\"י ש(הקב\"ה עוזרו ה\"ה) מעלה את עשר כחות נפשו, שהנשמה ירדה למטה, והרשות והיכולת נתונה לכל אדם<sup data-n=\"183\">27</sup> וכו', ועי\"ז פועל עלי' כביכול גם בשכינה וכו'.\nד) <b>ובזה</b> יובן מה שמסיים לכפר על נפשותיכם, שעי\"ז פועל תיקון של החטאים עד לחטא העגל. כי מכיון שע\"י הבירורים מתעלה למקום נעלה ביותר, בחי' התוהו שקדם אל התיקון, ולמעלה מזה, במקום שיעקב הוא הבכור (וכמשל השפופרת שהטיפה הנכנסת ראשונה תצא אחרונה<sup data-n=\"184\">28</sup>), עד למעלה מזה, במקום ששניהם שוים, הלא אח עשו ליעקב<sup data-n=\"185\">29</sup>, עד לבחי' אחדות הפשוטה, הרי פשוט הוא שמשם נמשך תיקון כל החסרונות והפגמים וכו'. וזהו ענין עשרים גרה הנ\"ל, דאיתא בספר הבהיר<sup data-n=\"186\">30</sup> ע\"ס מלמטלמ\"ע לא ידענו מלמעלמ\"ט ידענו, כי ע\"י העבודה בבחי' ע\"ס מלמטלמ\"ע ממשיכים מבחי' לא ידענו, שלמעלה לגמרי מענין הידיעה וכו'.\n<b>וזהו</b> גם מה שזה הי' התיקון לחטא העגל, דחטא העגל הי' כאשר בושש משה לרדת גו'<sup data-n=\"187\">31</sup>, וארז\"ל<sup data-n=\"188\">32</sup> א\"ת בושש אלא באו שש, שבאה שעה ששית, חצי היום, ולא בא, והתיקון לזה הוא ע\"י העבודה דמחצית השקל דוקא<sup data-n=\"189\">33</sup>.\nה) <b>והנה</b> כשם שע\"י נתינת מחצית השקל הקריבו קרבנות בכל השנה, עד\"ז בעבודה, שצ\"ל העבודה הנ\"ל בכל השנה, ובאופן של שמחה וטוב לבב, מרוב כל, היינו דתמורת זה שהי' חוסר כל יהי' מרוב כל, ולמעלה מזה, שהרי יפה שעה אחת בתשובה ומעשים טובים בעוה\"ז מכל חיי העוה\"ב<sup data-n=\"190\">34</sup>. אלא שמפני טעם הידוע ליוצרם הרי עכשיו אין הענינים בגלוי, ובקרוב ממש יהי' ונגלה כבוד הוי' וראו כל בשר יחדיו גו'<sup data-n=\"191\">35</sup>. ויה\"ר שבקרוב נקיים מצות מחצית השקל בביהמ\"ק השלישי, נשמות בגופים ומתוך בריאות הנכונה ובהרחבה, והקיצו ורננו שוכני עפר<sup data-n=\"192\">36</sup> ואהרן ומשה עמהם<sup data-n=\"193\">37</sup>, וקהל גדול ישובו הנה<sup data-n=\"194\">38</sup>, בקרוב ממש.\n**********",[["156","*","יצא לאור בשעתו, \"<i>ז' אדר</i>,<i> ה'תש\"מ</i>\"."],["157","1","תשא ל, יג."],["158","2","שם, טז."],["159","3","ד\"ה כי תשא גו' זה יתנו (סה\"מ פר\"ת ע' רסג ואילך)."],["160","4","שקלים פ\"ב ה\"ג. תנחומא תשא י."],["161","5","שבת קמו, א. ע\"ז כב, ב."],["162","6","זח\"א נב, ב. קכו, ב. ח\"ב קצג, ב. ועוד. וראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו</a>."],["163","7","נצוצי אורות (להחיד\"א) לזח\"ג יד, ב."],["164","8","ראה שו\"ע אדה\"ז או\"ח ס\"ס ס\"ד: כשיאמר ובנו בחרת יזכור מתן תורה."],["165","9","<a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא פמ\"ט (סט, סע\"ב</a> ואילך)."],["166","10","שבת קמה, ב."],["167","11","תשא לב, לד ובפרש\"י. מסנהדרין קב, סע\"א."],["168","12","ראה ברכות כו, ב."],["169","13","וראה גם אוה\"ת תשא ע' א'תתלד ואילך."],["170","14","ברכות ל, ב."],["171","15","פג, ב – ד\"ה מתני'."],["172","16","או\"ת (הוצאת קה\"ת) קח, ג."],["173","17","חגיגה טו, ב. סנהדרין מו, א במשנה."],["174","18","נדפס בסה\"מ תש\"ב ע' 89 ואילך."],["175","19","תהלים לח, ה."],["176","20","במדבר א, ב."],["177","21","תולדות כז, כט. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370275\" data-slug=\"torah-or\" data-id=\"3901370275\">תו\"א בשלח סא, ב</a>. ובכ\"מ."],["178","22","ראה סד\"ה זה יתנו וסד\"ה כי תשא תרע\"ה (המשך תער\"ב ח\"ב ע' תתעד. תתקא)."],["179","23","או\"ת מה, ד ואילך. הובאה ונתבארה ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490241\" data-slug=\"or-hatorah-hb\" data-id=\"8316490241\">אוה\"ת</a> לתהלים צח, ו (ע' שנז ואילך). ובארוכה – המשך תער\"ב פשפ\"ד ואילך (שם ע' תשצ ואילך). ובנדו\"ד – באוה\"ת תשא ריש ע' א'תתקח. תהלים שם."],["180","24","בהעלותך י, ב."],["181","25","שהש\"ר פ\"ה, ב."],["182","26","וראה אוה\"ת תשא ע' א'תתלה, ובסה\"מ פר\"ת שם ע' רסז – הקישור באופן אחר."],["183","27","ראה רמב\"ם הל' תשובה רפ\"ה."],["184","28","פרש\"י עה\"פ תולדות כה, כו. מב\"ר פס\"ג, ח."],["185","29","מלאכי א, ב."],["186","30","סקע\"א. הובא בפרדס שט\"ו רפ\"ד. לקו\"ת חוקת סג, ג."],["187","31","תשא לב, א."],["188","32","שבת פט, א. הובא בפרש\"י עה\"פ."],["189","33","ראה אוה\"ת שם ע' א'תתקכט. ועוד."],["190","34","אבות פ\"ד מי\"ז."],["191","35","ישעי' מ, ה."],["192","36","שם כו, יט."],["193","37","יומא ה, ב. וראה גם תוד\"ה אחד – פסחים קיד, ב."],["194","38","ירמי' לא, ז."]]],[1500380005,"<h3>בס\"ד. ש\"פ משפטים, מבה\"ח אדר ראשון ה'תשמ\"א<sup data-n=\"195\">*</sup></h3>\n<b>ואלה</b> המשפטים אשר תשים לפניהם כי תקנה עבד עברי גו'<sup data-n=\"196\">1</sup>, וידוע הדיוק בזה<sup data-n=\"197\">2</sup>, דלפניהם הוא לשון רבים ולשון נסתר ותקנה הוא לשון יחיד ולשון נוכח. גם צריך להבין מה דאיתא בירושלמי<sup data-n=\"198\">3</sup> עה\"פ ואלה המשפטים אשר תשים לפניהם, דתשים הוא מלשון סימה (אוצר) שאינה נגלית כו', רזי תורה. וצריך להבין, הרי משפטים הם הדינים שמובנים גם בשכל אנושי<sup data-n=\"199\">4</sup> [ואפילו בשכל דאומות העולם<sup data-n=\"200\">5</sup>], ומהי השייכות דמשפטים לתשים מלשון סימה, <i>רזי</i> תורה. גם צריך להבין<sup data-n=\"201\">6</sup> מה שמתחיל המשפטים בדין עבד עברי<sup data-n=\"202\">7</sup>.\nב) <b>והנה</b> מבואר באוה\"ת<sup data-n=\"203\">8</sup>, דענין עבד עברי ברוחניות הוא, שעבודתו את השם היא בדרך קבלת עול, עבודת עבד. ועפ\"ז יש לומר, דזה שהתחלת המשפטים הוא בדין עבד עברי, הוא לרמז, שגם קיום המצוות דמשפטים, שהם מובנים בשכל, צריך לקיימם מצד קבלת עול, בדרך עבודת עבד<sup data-n=\"204\">9</sup>. דהגם שמזה שמצוות אלו נקראים בתורת אמת בשם משפטים מובן שמצוות אלה צריך לקיימם גם מצד הטעם<sup data-n=\"205\">10</sup>, מ\"מ, עיקר קיומם צ\"ל בדרך קבלת עול, הן מצד האדם המקיים את המצוות, שקיום המצוות שלו צריך להיות בדרך עבודת עבד<sup data-n=\"206\">11</sup>, וגם מצד המצוות, כי כל המצוות (גם המצוות דמשפטים) עיקרם הוא שהם רצון הקב\"ה, רצון שלמעלה מטעם, אלא שכך גזר הקב\"ה שהרצון דמצוות אלו יתלבש גם בטעם<sup data-n=\"207\">12</sup>. ולהוסיף, דזה שגם קיום המצוות דמשפטים צ\"ל בדרך קבלת עול, הוא גם בענין המשפטים שבהם. היינו דזה שמצוות אלו צריך לקיימם גם מצד הטעם הוא מפני שכך הוא ציווי הקב\"ה שקיוםמצוות אלו יהי' גם מצד הטעם<sup data-n=\"208\">13</sup>. ויש לומר, דזהו שארז\"ל<sup data-n=\"209\">14</sup> עה\"פ ואלה המשפטים, ואלה מוסיף על הראשונים, מה הראשונים מסיני אף אלו מסיני, דבמתן תורה (סיני) נעשו ישראל עבדים להקב\"ה<sup data-n=\"210\">15</sup>, והרמז אף אלו מסיני הוא, שגם קיום המצוות דמשפטים, כולל גם ענין זה שצריך לקיימם גם מצד הטעם [אף אלו, משפטים], צריך להיות בדרך עבודת עבד. ולכן התחלת המשפטים הוא בדין עבד עברי, בכדי לרמז, שגם המצוות דמשפטים, הגישה הראשונה (דער ערשטער צוגאַנג) ללימודם וקיומם הוא קבלת עול, עבודת עבד<sup data-n=\"211\">16</sup>. וביאור נוסף, דכיון שעיקר ענין העבדות הוא בעבד כנעני [דנוסף לזה שעבד עברי עובד רק שש שנים<sup data-n=\"212\">17</sup> (וגם עבד נרצע יוצא ביובל<sup data-n=\"213\">18</sup>) ובעבד כנעני כתיב<sup data-n=\"214\">19</sup> לעולם בהם תעבודו, השעבוד (העבדות) דעבד עברי (גם בהיותו עבד) אינו כהשעבוד (עבדות) דעבד כנעני<sup data-n=\"215\">20</sup>], הרי בכדי לרמז ענין הנ\"ל (שקיום המצוות דמשפטים צ\"ל בדרך עבודת עבד) הי' צריך לכאורה להתחיל המשפטים בדין עבד כנעני.\nג) <b>ויובן</b> בהקדים דרשת רז\"ל<sup data-n=\"216\">21</sup> עה\"פ ואלה המשפטים אשר תשים לפניהם, דמזה שנאמר אשר תשים לפניהם (ולא אשר תלמדם וכיו\"ב) למדין שאין מספיק שהרב שונה לתלמידיו ההלכות כמה פעמים עד שיהיו סדורים בפיהם אלא צריך גם לשום לפניהם טעם המיישב תלמודם. ועפ\"ז יש לומר, דמ\"ש לאח\"ז כי תקנה לשון יחיד הוא לרמז, דכי תקנה קאי (גם) על אשר תשים<sup data-n=\"217\">22</sup>, שהרב צריך לשנות לתלמידיו באופן שענין הנלמד יהי' הקנין שלהם. וכמארז\"ל<sup data-n=\"218\">23</sup> עה\"פ<sup data-n=\"219\">24</sup> בתורת ה' חפצו ובתורתו יהגה יומם ולילה, שבתחלה נקראת התורה על שמו של הקב\"ה (תורת ה') ואח\"כ נקראת על שמו (תורת<i>ו</i>), תורה דילי' היא<sup data-n=\"220\">25</sup>. וזה שהתורה נעשית קנינושל האדם העוסק בתורה (תורה דילי' היא) הוא דוקא כשיודע <i>טעמי</i> ההלכות<sup data-n=\"221\">26</sup>. וזהו אשר תשים לפניהם כי תקנה, דע\"י הלימוד באופן דתשים לפניהם, עי\"ז נעשית התורה קנינו של האדם הלומד, כי תקנה.\n<b>גם</b> יש לומר, דזה שלאחרי אומרו אשר תשים לפניהם ממשיך כי תקנה, הוא לפי שכי תקנה הוא ציווי נוסף על הציווי דתשים לפניהם. ויובן זה בהקדים שלכאורה אינו מובן, הרי זה שהתורה מתלבשת בשכלו של האדם הלומד עד שנעשית תורת<i>ו</i> הוא ירידה (לכאורה) לגבי התורה כמו שהיא תורת הוי', וממארז\"ל הנ\"ל (ואח\"כ נקראת על שמו) משמע דזה שהתורה נעשית תורתו (של האדם הלומד) הוא מעלה. ונקודת הביאור בזה, דירידת והמשכת התורה למטה היא באופן שגם לאחרי שירדה למטה ונתלבשה בשכל אנושי היא חכמתו של הקב\"ה שלמעלה משכל הנבראים. וזה שהיא מובנת גם בשכל אנושי הוא מפני ששרשה הוא באוא\"ס הבל\"ג שאינו מוגבל בהגדרים דמעלה ומטה, ולכן ביכלתה להיות גם למטה<sup data-n=\"222\">27</sup>. והיינו, דנוסף לזה שגם בירידתה למטה היא נשארת במהותה – חכמתו של הקב\"ה, הנה אדרבה, ע\"י ירידתה למטה נעשה בה יתרון לגבי דרגת התורה כמו שהיתה למעלה לפני ירידתה למטה. כי ע\"י ירידתה למטה מתגלה בה שרשה באוא\"ס הבל\"ג<sup data-n=\"223\">28</sup>. ועד\"ז הוא בנוגע לזה שע\"י לימוד התורה בהבנה והשגה נעשית תורת<i>ו</i> של האדם הלומד, שגם לאחרי שהיא נעשית תורתו של האדם הלומד היא נשארת במהותה תורת הוי', ויתירה מזה, דע\"י שתורת הוי' נעשית תורתו של האדם, נעשה בה יתרון לגבי דרגת התורה כמו שהיא מצד עצמה, תורת הוי'<sup data-n=\"224\">29</sup>. כי זה שתורת הוי' נעשית תורתו של האדם<sup data-n=\"225\">30</sup> [ובאופן שגם לאחרי שנעשית תורתו של האדם היא נשארת במהותה, תורת הוי'<sup data-n=\"226\">31</sup>, ואעפ\"כ היא תורתו של האדם], הוא ע\"י גילוי אוא\"ס (שלמעלה מהוי'), שמחבר ומאחד את האדם עם הוי', ישראל וקוב\"ה כולא חד.ד) <b>והנה</b> שני ענינים הנ\"ל שבתורה, כמו שהיא תורת הוי' וכמו שהיא תורתו (של האדם הלומדה), הם (בדרך כלל) התורה כמו שהיא באצילות וכמו שהיא בבריאה. כדאיתא בל\"ת להאריז\"ל<sup data-n=\"227\">32</sup>, דהטעם על זה שהתורה מתחלת בבי\"ת הוא כי האל\"ף דתורה הוא התורה שבאצילות והתורה שאנו לומדים בהבנה והשגה היא התורה כמו שהיא בבריאה, הבי\"ת דתורה. ומבואר בחסידות<sup data-n=\"228\">33</sup> דזהו מ\"ש<sup data-n=\"229\">34</sup> ועל תורתך שלמדתנו, ועל תורתך באצילות שלמדתנו בבריאה. והנה ידוע<sup data-n=\"230\">35</sup> שאצילות נקרא בשם קנין. כמ\"ש<sup data-n=\"231\">36</sup> ברוך עושך ברוך יוצרך ברוך בוראך ברוך קונך, דעושך יוצרך ובוראך הם ג' העולמות עשי' יצירה ובריאה, וקונך הוא אצילות. דכמו שקנין אינו הוויית דבר חדש אלא גילוי ההעלם [דגם קודם הקנין הי' הדבר, אלא שקודם הקנין, כשהדבר הי' ברשות המוכר, הי' בהעלם לגבי הלוקח, וע\"י הקנין בא הדבר אליו בגילוי], כן האצילות הוא גילוי ההעלם. וזהו שלאחרי אומרו אשר תשים לפניהם מוסיף כי תקנה, דהגם שלימוד התורה צריך להיות בהבנה והשגה (אשר תשים לפניהם), ועד שנקראת על שמו, תורת<i>ו</i> (של האדם הלומדה), מ\"מ צריך להיות הלימוד באופן שיהי' נרגש אצלו שהתורה שלומד (גם לאחרי שנעשית חכמתו) היא תורת הוי', תורתך שבאצילות, תקנה. ועפ\"ז יש לבאר מה דאיתא בירושלמי דתשים הוא מלשון סימה שאינה נגלית, רזי תורה, כי בכדי שבהתורה שהאדם לומד ומבין בשכלו (שכל אנושי) יהי' נרגש שהיא תורת הוי', תורתך שבאצילות (כי תקנה), הוא ע\"י גילוי הנשמה כמו שהיא באצילות, בחינת טהורה<sup data-n=\"232\">37</sup> היא (שלמעלה מבחינת אתה<sup data-n=\"232\">37</sup> בראתה)<sup data-n=\"233\">38</sup>, וגילוי בחינה זו דהנשמה (סתים דנשמה) הוא ע\"י לימוד פנימיות התורה, סתים דאורייתא<sup data-n=\"234\">39</sup>. וזהו אשר תשים לפניהם כי תקנה, דע\"י תשים מלשון סימה, לימוד פנימיות התורה, נעשה הגילוי דפנימיות הנשמה<sup data-n=\"235\">40</sup> – לפניהם לפנימיותם<sup data-n=\"235\">40</sup>, ועי\"ז גם בהתורה שלומד באופן דתשים לפניהם [הבנה והסברה, טעם שמיישב תלמודו], נרגש תורתך שבאצילות, כי תקנה.\nה) <b>והנה</b> הפירוש דואלה המשפטים אשר תשים לפניהם בפשטות הוא, שהקב\"ה אמר למשה רבינו שהוא (משה) ישים את המשפטים לפני ישראל<sup data-n=\"236\">41</sup>. ומזה מובן גם בנוגע לכי תקנה [דכי תקנה לשון יחיד קאי על אשר תשים, כנ\"ל סעיף ג], שזה קאי על משה. והענין הוא, דאיתא בזהר<sup data-n=\"237\">42</sup>, בכולהו אתר דשמא אדכר תרי זימניפסיק טעמא בגווייהו, כגון אברהם אברהם כו', חוץ ממשה משה דלא פסיק טעמא בגווייהו. ומבואר בחסידות<sup data-n=\"238\">43</sup>, דאברהם, ע\"י שירדה נשמתו למטה, נעשה בה שינוי לגבי שרשה שבאצילות<sup data-n=\"239\">44</sup>, משא\"כ במשה, גם בהיותו למטה האיר בגילוי מקורו כמו שהוא באצילות, ועד שאין מחיצה והפסק ביניהם, לא פסיק טעמא. והטעם על זה שגם בהיותו למטה הי' כמו שהוא באצילות, הוא, כי השרש דנשמת משה הוא מבחינת העיגולים שלמעלה מהשתלשלות, ולגבי למעלה מהשתלשלות, אצילות ועשי' הם בשוה<sup data-n=\"240\">45</sup>. וזהו שלמשה נאמר אשר תשים לפניהם כי תקנה, כי החיבור דב' הדרגות שבתורה [כמו שנתלבשה בשכל האדם (תשים לפניהם) וכמו שהיא תורתך שבאצילות (קנין)] הוא ע\"י הגילוי דלמעלה מהשתלשלות שנמשך ע\"י משה. וכמו שנתבאר לעיל (סעיף ג) שהחיבור דתורתו (של האדם) עם תורת הוי', הוא ע\"י גילוי אוא\"ס.\nו) <b>והנה</b> פירוש הנ\"ל בכי תקנה, שקאי על אשר תשים לפניהם, יש לקשר עם הפירוש הפשוט דכי תקנה קאי אלאח\"ז, כי תקנה עבד, כי כשלימוד התורה שלו היא באופן דכי תקנה, שנרגש אצלו שהתורה שלומד היא תורת הוי', הלימוד שלו הוא בתכלית הביטול, בדוגמת ביטול העבד להאדון. דהגם שענין הלימוד הוא (לא שהאדם יבטל את שכלו להתורה, אלא אדרבה) שיבין את התורה בהשכל שלו, שענין זה קשור (לכאורה) עם <i>המציאות</i> שלו, ועאכו\"כ כשהלימוד שלו הוא באופן שהתורה היא תורת<i>ו</i> (של האדם), מ\"מ, ע\"י שנרגש אצלו שהתורה (גם לאחרי שירדה למטה ונתלבשה בשכל אנושי) היא תורת הוי', חכמתו של הקב\"ה שלמעלה משכל הנבראים, [וזה שהאדם מבין את התורה בהשכל שלו הוא מפני שהקב\"ה אינו מוגבל בשום הגבלות (גם לא בהגדר דבל\"ג) ולכן ביכלתו ית' לחבר ההפכים דבל\"ג וגבול<sup data-n=\"241\">46</sup>, ששכל האדם (המוגבל) ישיג חכמתו של הקב\"ה (הבלתי מוגבל)], זה שהוא מבין את התורה בהשכל שלו אינו סותר לענין הביטול, כי זה שהוא מבין את התורה בהשכל שלו [וגם זה שהתורה דילי' היא] אינו מצד המציאות שלו אלא מצד זה שהקב\"ה הוא כל יכול.\nז) <b>ועפ\"ז</b> יובן לשון חז\"ל<sup data-n=\"242\">47</sup> עולה של תורה, דלכאורה, כיון שמצות תלמוד תורה היא (לא שהאדם יבטל את שכלו להתורה, אלא אדרבה) שיבין את התורה בהשכל שלו דוקא [וגם הפס\"ד דהאדם העוסק בתורה צריך להיות כפי הבנתו דהאדם, דתורה לא בשמים היא וקוב\"ה קא חייך ואמר נצחוני בני נצחוני<sup data-n=\"243\">48</sup>], מהו\"ע <i>עולה</i> של תורה, דעול הו\"ע הביטול. והביאור בזה הוא (כנ\"ל), דע\"י הידיעה וההרגששהתורה היא תורת הוי' [וזה שהיא ניתנה לרשותו של האדם, נצחוני בני נצחוני, הוא מפני שהוא ית' הוא כל יכול, ולכן ביכלתו ית' לתת את תורת<i>ו</i> (תורת הוי') לרשותו של האדם], גם זה שהוא מבין את התורה בהשכל שלו הוא באופן דעולה של תורה, שהתורה היא האדון שלו והוא בטל להתורה כעבד שמוטל עליו עול האדון. וזה שהתורה ניתנה לרשותו (נצחוני בני נצחוני), הוא מפני שכן הוא רצון ה\"אדון\", נותן התורה.\n<b>ויש</b> לקשר זה עם זה שארז\"ל עה\"פ ואלה המשפטים, ואלה מוסיף על הראשונים, מה הראשונים מסיני אף אלו מסיני, שהכח על החיבור דשני ההפכים שבמשפטים [שהם מובנים בשכל, והלימוד (שלהם<sup data-n=\"244\">49</sup>) צריך להיות באופן דאשר תשים לפניהם, טעם המיישב תלמודם, שעי\"ז נעשית התורה תורתו של האדם הלומד. וביחד עם זה צריך להיות הלימוד שלהם באופן דכי תקנה, שירגיש שהיא תורת הוי' (תורתך שבאצילות, קנין), ויתירה מזה, שהלימוד שלהם צ\"ל באופן דעבד, <i>עולה</i> של תורה], ניתן מסיני<sup data-n=\"245\">50</sup>, שגם בו הוא חיבור דשני ההפכים, מציאות וביטול. וכמבואר בלקו\"ת<sup data-n=\"246\">51</sup>, דזה שהתורה ניתנה על הר סיני דמכיך מכל טוריא<sup data-n=\"247\">52</sup>, הוא מפני שבהר סיני ישנם שני ההפכים. הר – הגבהה, ומכיך – ביטול.\nח) <b>והנה</b> אמרו רז\"ל<sup data-n=\"248\">53</sup> גדול תלמוד שמביא לידי מעשה. ויש לומר, שע\"י החיבור דשני ההפכים (מציאות וביטול) שבלימוד התורה, נמשך עד\"ז גם במעשה המצוות. אלא שבלימוד התורה החידוש הוא הביטול. דהגם שלימוד התורה הוא בהבנה והשגה (מציאות) מ\"מ צריך להיות הלימוד בביטול. ובקיום המצוות החידוש הוא המציאות. דהגם שקיום המצוות צ\"ל מצד <i>ציווי</i> הקב\"ה [כמובן גם מזה שמצוות הוא לשון ציווי], בדרך עבודת עבד<sup data-n=\"249\">54</sup>, מ\"מ הביטול שלו צריך להיות באופן שהביטול אינו שולל את מציאותו אלא אדרבה זה גופא הוא מציאותו. היינו, דזה שהוא עבדו של הקב\"ה הוא [לא רק מצד ההכרח, אלא] שהוא רוצה להיות עבדו של הקב\"ה ויש לו חיות ותענוג בזה.\n<b>ויש</b> לומר, דמהטעמים על זה שהתחלת הציווים דפרשת משפטים הוא בפסוק ואלה המשפטים אשר תשים לפניהם שמדבר בלימוד התורה כדרשת חז\"ל, הובאה לעיל סעיף ג [דלא כרוב הציווים שבתורה שבתחילתם הוא דבר אל בני ישראל, צואת בני ישראל, ולא נזכר בהם ענין הלימוד], כי זה שהתחלת הציווים דפרשת משפטים הוא בדיני עבד מרמז שקיום כל המצוות צ\"ל בדרך עבודת עבד (כנ\"ל סעיף ב), וכיון שגם הביטול דקבלת עול (עבודת עבד) צ\"ל בחיות ובתענוג (כנ\"ל), לכן, התחלת הפרשה היא בהענין דלימוד התורה, דמהתענוג והחיות שבלימוד התורה נמשך מעין התענוג וחיות דתורה גם בהעבודה דקבלת עול<sup data-n=\"250\">55</sup>.\nט) <b>ועפ\"ז</b> יובן מה שהתחלת הפרשה היא בדין עבד עברי, אף שעיקר ענין העבדות הוא בעבד כנעני (כנ\"ל סעיף ב), כי השלימות דענין העבדות (קבלת עול) הוא שהביטול דעבדות יהי' בתענוג ובחיות, וענין זה הוא בעבד עברי דוקא. ויובן זה ע\"פ מ\"ש אדמו\"ר הזקן בד\"ה וכי ימכור איש את בתו לאמה<sup data-n=\"251\">56</sup> [והצ\"צ כותב<sup data-n=\"252\">57</sup> על מאמר זה שהוא דרוש נכבד מאד מדבר מענין צדיק רשע ובינוני], דג' מיני העבדים שבפרשת משפטים, עבד כנעני עבד עברי ואמה העברי', הם ג' מדריגות בעבודת הוי'. עבד כנעני הוא שהרצון והתענוג שלו הם בפריקת עול, כמארז\"ל<sup data-n=\"253\">58</sup> עבדא בהפקירא ניחא לי', שהנח\"ר שלו (ניחא) הוא בהפקירות, פריקת עול, ועבודתו את השם הוא רק מצד ההכרח, מחמת אימת הכאת השבט, דענין הכאת השבט ברוחניות הוא שמאיר בו נפשו האלקית (אלא שהגילוי דנפש האלקית הוא רק בנוגע לעשי' בפועל). [ומבאר שם<sup data-n=\"254\">59</sup>, שבעבד (כנעני) נכלל גם רשע וטוב לו. דכמו שבעבד כפשוטו, אפשר שהעבד יחטא לרבו ואעפ\"כ כשרבו מכהו בשבט הוא חוזר לעבודתו, עד\"ז הוא בעבודת ה', דגם מי שמצד התענוג שלו בפריקת עול הוא עובר על מצוות השם, מ\"מ, כיון שאח\"כ, כשמאיר בו גילוי נפשו האלקית (הכאת השבט) הוא מתחרט על חטאיו, לא יצא מכלל עבד. ולאידך, גם הבינוני (דרגא תחתונה שבבינוני) נכלל בעבד כנעני. דהגם שלא עבר עבירה מימיו<sup data-n=\"255\">60</sup>, מ\"מ, כיון שהרצון והתענוג שלו הוא בתאוות עוה\"ז ועבודתו את השם הוא רק מצד ההכרח (אלא שהגילוי דנפש האלקית <i>מכריח</i> אותו להיות סור מרע ועשה טוב במשך כל היום כולו), לא יצא מכלל עבד כנעני]. ועבד עברי הוא שהרצון והתענוג שלו הוא (בעיקר) בעבודת השם, והענינים דפריקת עול (כולל התענוג בעניני עוה\"ז) הם אצלו יסורים גדולים וצער<sup data-n=\"256\">61</sup>. והגם שכשבאים לו עניני עוה\"ז הוא מתענג מהם, <i>רצונו</i> הוא שלא להמשך אחריהם. והוא מתמרמר על זה שהתענג בעניני עוה\"ז. [והוא <i>עיקר</i> מדריגת הבינוני]. ואמה העברי' היא מדריגת צדיק, שהמדות שלו <i>נהפכו </i>לקדושה (אתהפכא שלמעלה מאתכפיא), כמבואר שם בארוכה.<b>וזהו</b> שבפרשת משפטים מדובר בקנין עבד עברי ואמה העברי' [כי תקנה עבד עברי גו' וכי ימכור איש את בתו לאמה<sup data-n=\"257\">62</sup> גו'], והענין דעבד כנעני (בהפרשיות שמדברים <i>בקניני</i> עבד<sup data-n=\"258\">63</sup>), לא תצא כצאת העבדים<sup data-n=\"257\">62</sup>, הוא רק כמו בדרך אגב (ובאופן שלילי), כי זה שהתחלת פרשת משפטים היא בדיני עבד הוא מפני שבפרשה זו [שהיא בהמשך למתן תורה, מה הראשונים מסיני אף אלו מסיני] מדבר בכללות הענין דעבודת ה', שצריכה להיות בדרך עבודת עבד, וכיון שהעבדות צריכה להיות בתענוג וחיות, לכן מדבר בדיני עבד עברי ואמה העברי'. בתחלה מדבר בעבד עברי, מדריגת הבינוני, כי מדת הבינוני היא מדת כל אדם ואחרי' כל אדם ימשוך<sup data-n=\"259\">64</sup>. ואח\"כ מדבר באמה העברי', מדריגת צדיק, שגם עבודה זו שייכת לכל אחד, כמבואר בתניא<sup data-n=\"260\">65</sup>, דגם כשיודע בנפשו שלא יגיע למדריגה זו באמת לאמיתו מ\"מ הוא יעשה את שלו לקיים את השבועה שמשביעין אותו תהי צדיק. ויש לומר דזה שמדבר [כמו בדרך אגב עכ\"פ] גם בעבד כנעני, הוא מצד המעלה דאתכפיא. וכמ\"ש אדמו\"ר הזקן בדרוש הנ\"ל<sup data-n=\"261\">66</sup>, שגם בצדיק גמור צריכה להיות העבודה דעבד כנעני, מצד המעלה שבאתכפיא. דזהו שארז\"ל<sup data-n=\"262\">67</sup> אל יאמר אדם אי אפשי כו' אלא אפשי ומה אעשה ואבי שבשמים גזר עלי, דזה שצריך לומר אפשי כו' הוא בכדי שתהי' אצלו העבודה דאתכפיא.\nיו\"ד) <b>ולהעיר</b><b>,</b> דבאתכפיא זו הוא רק המעלה דאתכפיא. דהגם שבזה שאומר אפשי הוא רחוק מאד מאלקות<sup data-n=\"263\">68</sup>, הרי זה שאומר אפשי הוא מצד ציווי התורה, וכוונתו בזה שאומר אפשי ומעורר רצון לזה<sup data-n=\"264\">69</sup> הוא בכדי שתהי' אצלו העבודה דאתכפיא (שיעשה <i>נגד</i> רצונו). ועפ\"ז מובן, דזה שעבודת הצדיקים היא לא מצד ההכרח אלא שזהו התענוג שלהם, הוא גם בנוגע להעבודה דאתכפיא שלהם. דהגם שהיא אתכפיא באמת, כי זה שאומרים אפשי הוא שמעוררים <i>הרצון</i> שלהם לזה, אלא שכופין את עצמם ועושים <i>נגד</i> רצונם, זה גופא הוא התענוג שלהם, כיון שהכוונה בהרצון שלהם היא בכדי שיעשו נגד רצונם.\n<b>והנה</b> ידוע<sup data-n=\"265\">70</sup> שההמשכה שעל ידי העבודה דאתכפיא היא המשכה נעלית יותר מההמשכה שעל ידי העבודה דאתהפכא. כמאמר<sup data-n=\"266\">71</sup> כד אתכפיא סט\"א אסתלק יקרא דקוב\"ה בכולהו עלמין, שע\"י העבודה דאתכפיא הוא המשכת האור שבבחינתרוממות, אסתלק. ויש לומר, דההמשכה שע\"י אתכפיא דצדיקים (שהאתכפיא גופא היא התענוג שלהם), היא המשכה נעלית עוד יותר. והענין הוא, דמהטעמים על זה שהמשכה זו היא ע\"י אתכפיא דוקא, הוא<sup data-n=\"267\">72</sup>, דע\"י שהאדם כופה את עצמו לעשות כנגד רצונו וטבעו, המשכת הגילויים דלמעלה היא לא כפי הטבע שלהם. שגם האור שבבחינת רוממות, שמצד \"טבעו\" הוא למעלה מגילוי, נמשך בגילוי. ויש לומר דכאשר האתכפיא דהאדם היא בדרך הכרח, היפך התענוג שלו, זה שנמשך בגילוי האור שלמעלה מגילוי (היפך הטבע שלו), הוא כמו בדרך הכרח כביכול<sup data-n=\"268\">73</sup>, היינו שההמשכה היא מבחינת חיצוניות הרצון, וע\"י שהאתכפיא דהאדם הוא באופן שזהו התענוג שלו, ההמשכה היא מבחינת פנימיות הרצון והתענוג.\nיא) <b>וזהו</b> ואלה המשפטים אשר תשים לפניהם וארז\"ל ואלה <i>מוסיף</i> על הראשונים, דירידת והמשכת התורה במשפטים שהם מובנים גם בשכל האדם, ובפרט שעי\"ז ניתן הכח לאדם שיוכל ללמוד תורה באופן דאשר תשים לפניהם (בהבנה והסברה ועד שהתורה נקראת על שמו), היא הוספה על הראשונים, כי ע\"י ירידה זו מתגלה שורש התורה באוא\"ס הבל\"ג (כנ\"ל סעיף ג). ולהוסיף, דע\"י לימוד התורה דהאדם באופן שהתורה נקראת על שמו, מיתוסף בהתורה עוד יותר. כי בירידת והמשכת התורה במשפטים, מה שנמשך בגילוי למטה הוא <i>חכמתו</i> של הקב\"ה (חכמה דאצילות), אלא שהחיבור דחכמתו של הקב\"ה שלמעלה משכל הנבראים עם שכל האדם הוא ע\"י ההמשכה מאוא\"ס הבל\"ג שלמעלה מחכמה [היינו שהגילוי דאוא\"ס הבל\"ג הוא רק נתינת כח לבחי' החכמה דאצילות שתתחבר עם שכל האדם, ולא שמתגלה אוא\"ס הבל\"ג עצמו], וע\"י עסק התורה דהאדם באופן שהתורה היא תורת<i>ו</i>, נמשך בתורה הגילוי דאוא\"ס הבל\"ג עצמו. וכמבואר בהדרושים<sup data-n=\"269\">74</sup> דזה שהתורה נקראת תורת<i>ו</i> (דהאדם), הוא לפי שע\"י עסק התורה לשמה (לשם התורה) הוא ממשיך בה הגילוי דאוא\"ס הבל\"ג, ולכן נקראת התורה על שמו, לפי שהוא המשיך בה גילוי זה. ויש לומר, דזהו שואלה הוא וא\"ו אלה, וא\"ו המוסיף הוא ההוספה שנעשית בתורה, אלה הוא לשון גילוי, ופירוש ואלה (וא\"ו אלה) הוא, שההוספה בתורה (שנמשך בה אוא\"ס הבל\"ג) היא בגילוי. היינו, דזה שנמשך בה אוא\"ס הבל\"ג הוא לא רק באופן דנתינת כח אלא שהאור עצמו מאיר בגילוי.\nיב) <b>וממשיך</b> בכתוב אשר תשים לפניהם, ויש לומר, שאשר הוא (גם) מלשון אושר ותענוג. היינו, שהענין דואלה (וא\"ו אלה), ההוספה שנמשכת בתורה בבחינת גילוי מעצמות אוא\"ס, היא מבחינת התענוג. דזה שלימוד התורה שלו הוא באופן <i>דעול</i> תורה, ביטול <i>דעבד</i> (כנ\"ל סעיף ו-ז), הוא דוגמת הענין דאתכפיא, וזה שהביטול שלו הוא באופן (שהביטול אינו שולל את מציאותו אלא אדרבה) שמצדהביטול גופא הוא מרגיש שהתורה היא תורתו (כנ\"ל סעיף ז) הוא ע\"ד האתכפיא דצדיקים שהאתכפיא עצמה היא התענוג שלהם, ולכן, ההמשכה שעי\"ז היא מבחינת אשר, תענוג.\n<b>וע\"י</b> לימוד התורה באופן דאשר תשים לפניהם, כי תקנה עבד, שהלימוד הוא בהבנה והסברה וביחד עם זה בביטול דעבד [שבכדי שלימוד הנגלה יהי' באופן זה הוא ע\"י לימוד פנימיות התורה, תשים לשון סימה, אוצר], עי\"ז יזכו לגילוי תורתו של משיח, תורה חדשה מאתי תצא<sup data-n=\"270\">75</sup>, בגאולה האמיתית והשלימה ע\"י משיח צדקנו, במהרה בימינו ממש.\n**********",[["195","*","יצא לאור ב<b>קונטרס כ\"ב שבט – תשנ\"ב</b>, \"לקראת יום ב' פ' משפטים, כ\"ב שבט הבע\"ל, יום היאָרצייט-הילולא הרביעי של הרבנית הצדקנית מרת חי' מושקא נ\"ע זי\"ע . . <i>ט\"ו בשבט</i>,<i> ה'תשנ\"ב</i>\"."],["196","1","ריש פרשתנו (משפטים)."],["197","2","רד\"ה ואלה המשפטים ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370330\" data-slug=\"torah-or\" data-id=\"3901370330\">תו\"א (עד, ג</a>) וב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550833\" data-slug=\"torat-chaim\" data-id=\"2300550833\">תו\"ח (תט, א</a> [בהוצאה החדשה – משפטים ח\"ב רעז, א]). וראה גם רד\"ה כי תקנה בתו\"ח (תכה, ב [שם רפד, א]). סהמ\"צ להצ\"צ מצות דין עבד עברי פ\"א (דרמ\"צ פ, א)."],["198","3","ע\"ז פ\"ב סוף ה\"ז. וראה בפי' פני משה שם."],["199","4","כידוע בענין ג' הסוגים משפטים עדות וחוקים – ראה רמב\"ן עה\"פ ואתחנן ו, כ. לקמן ח\"ד ע' יג. <i>וש\"נ</i>."],["200","5","שלכן צריך להזהיר שלא לדון המשפטים בערכאות (פרש\"י עה\"פ)."],["201","6","כהדיוק דכמה מפרשים (ראב\"ע, רמב\"ן, ועוד). וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161255\" data-slug=\"likkutei-sichot\" data-id=\"1300161255\">לקו\"ש חט\"ז ע' 255</a>. וראה גם רד\"ה זה ה'תשל\"ח (לעיל ע' ח)."],["202","7","דבר של צער להאדם. ובפרט ע\"פ מחז\"ל (מכילתא הובא בפרש\"י) שמדובר בקונה מיד בי\"ד גנב שאין ידו משגת לשלם וכו', דבר שאינו רגיל."],["203","8","פרשתנו ע' א'קיא. שם ע' א'קכא."],["204","9","ראה לעיל ח\"ב ע' קסד ואילך. וש\"נ."],["205","10","ראה שמונה פרקים להרמב\"ם פ\"א – הובא באוה\"ת פרשתנו ע' א'קלח ובסהמ\"צ להצ\"צ שם (פד, ב)."],["206","11","<a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא רפמ\"א</a>."],["207","12","ראה בארוכה בכ\"ז לעיל ח\"ב שם."],["208","13","וגם בזה שני ענינים הנ\"ל: כי ישראל הם <i>עבדים</i> להקב\"ה, דאמיתית ענין העבד הוא שכולו וכל הכחות והענינים שלו (לא רק כח המעשה) משועבדים להאדון, ולכן גם זה שמתבוננים בשכלם בטעמי המצוות הוא מצד <i>ציווי</i> הקב\"ה; וגם מצד המצוות, כי זה שהרצון דמצוות אלו (משפטים) נתלבש בטעם הוא (לא מפני שהרצון דמצוות אלו הוא בדרגא נמוכה יותר מהרצון דחוקים, אלא) מפני שכך <i>גזר</i> הקב\"ה."],["209","14","מכילתא הובא בפרש\"י עה\"פ."],["210","15","ראה לקמן ס\"ע שנז, ובהערה 29 שם."],["211","16","ראה עד\"ז של\"ה מס' פסחים שלו קנא, ב (הובא באוה\"ת פרשתנו ע' א'עז) \"והתחיל ואלה המשפטים במצות עבד עברי להיות רושם העבדות קיים, כי עבדי הם\"."],["212","17","פרשתנו כא, ב."],["213","18","קידושין טו, סע\"א. פרש\"י עה\"פ פרשתנו כא, ו."],["214","19","בהר כה, מו. ויתירה מזה, דמפסוק זה למדין <i>שאסור</i> לשחרר עבד כנעני (ברכות מז, ב. וש\"נ)."],["215","20","וכמה דינים בזה – ראה רמב\"ם הל' עבדים פ\"א ה\"ה ואילך."],["216","21","עירובין נד, ב ובפרש\"י שם. הל' ת\"ת לאדה\"ז פ\"ד סי\"ח. וצ\"ע, דבהל' ת\"ת שם כמה שינויים (לכאורה) מבגמרא עירובין שם. ואכ\"מ."],["217","22","כ\"ה גם בהדרושים שבהערה 2. ושם, דענין כי תקנה הוא שמשה ימשיך לישראל בחינת הדעת. וע\"פ מ\"ש ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370336\" data-slug=\"torah-or\" data-id=\"3901370336\">תו\"א שם (עה, ג</a>) דהמשכת הדעת הוא ע\"י לימוד ההלכות [כי כשמשיג ההלכות הוא \"גילוי דעת התורה במחשבת האדם\", ולכן, עי\"ז זוכה \"שיומשך בו בחי' הדעת\"], יש לקשר הפירוש שבפנים עם הפירוש שבדרושים הנ\"ל."],["218","23","ע\"ז יט, א. וראה פרש\"י קידושין לב, ריש ע\"ב."],["219","24","תהלים א, ב."],["220","25","קידושין שם."],["221","26","ראה שיורי ברכה להחיד\"א יו\"ד סרמ\"ג ס\"ו דשונה הלכות אינו יכול למחול על כבודו כי \"לא הגיע למדריגת תורה דילי' היא\"."],["222","27","ראה המשך תרס\"ו ע' תכב, \"דשרש ההמשכה (דתורה) הוא מאוא\"ס שלפני הצמצום כו' (ולכן) היא נמשכת עד למטה ממש\"."],["223","28","בהמשך תרס\"ו שם (ס\"ע תכב ואילך) (וראה בארוכה לקמן ע' קיח ואילך), דזה שהתורה היא בכל מקום (למעלה ולמטה) בשוה הוא לפי ששרש המשכתה הוא מאוא\"ס הבל\"ג, וזה שעיקר התורה הוא דוקא למטה הוא מצד שרשה בהעצמות. ועפ\"ז, היתרון שנעשה בהתורה ע\"י ירידתה למטה הוא לפי שעי\"ז מתגלה בה (לא רק שרש המשכתה באוא\"ס הבל\"ג, אלא גם) שרשה האמיתית, כמו שהיא מושרשת בהעצמות."],["224","29","ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550821\" data-slug=\"torat-chaim\" data-id=\"2300550821\">תו\"ח פרשתנו תכב, סע\"ב</a> [בהוצאה החדשה – ח\"ב רצ, ב] ואילך (וראה עד\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380516\" data-slug=\"likkutei-torah\" data-id=\"4001380516\">לקו\"ת שלח נא, א</a>), ד\"תורת<i>ו</i>\" היא למעלה מ\"תורת הוי'\". אלא ששם מדובר בענין ההמשכה שע\"י <i>עסק</i> התורה דהאדם, כדלקמן סעיף יא."],["225","30","ויש לומר, דזה שהתורה נעשית תורת<i>ו</i> (של האדם), שנמסרה לבעלותו [שלכן יכול למחול על כבודה], היא ירידה גדולה יותר מזה שהתורה ירדה להתלבש בשכל אנושי. ולכן, גם העלי' [הגילוי דאוא\"ס הבל\"ג] שע\"י ירידה זו, היא עלי' גדולה יותר."],["226","31","להעיר, דזה שאין דברי תורה מקבלים טומאה למדין מהכתוב (ירמי' כג, כט) הלא כה דברי כאש (ברכות כב, א). ויש לומר הפירוש ב\"דברי כאש\", דכיון שהוא \"דבר<i>י</i>\" (דהקב\"ה), לכן הוא \"כאש\" שאינו מקבל טומאה. והרי דין זה (שד\"ת אין מקבלין טומאה) הוא גם בזה שהתורה נקראת על שמו – כי הגם שתורה <i>דילי'</i> היא, היא תורת הוי', \"דבר<i>י</i>\" דהקב\"ה."],["227","32","ר\"פ בראשית."],["228","33","סה\"מ ה'ש\"ת ע' 68. ובכ\"מ."],["229","34","בנוסח ברכת המזון."],["230","35","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370337\" data-slug=\"torah-or\" data-id=\"3901370337\">תו\"א פרשתנו עה, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550775\" data-slug=\"torat-chaim\" data-id=\"2300550775\">תו\"ח שם תיא, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550833\" data-slug=\"torat-chaim\" data-id=\"2300550833\">שם תכה, ב</a> ואילך [בהוצאה החדשה – ח\"ב רעח, א ואילך. רפד, א ואילך]. סה\"מ להצ\"צ מצות דין עבד עברי פ\"ג (דרמ\"צ פב, א ואילך). אוה\"ת פרשתנו ע' א'קכא."],["231","36","בנוסח קידוש לבנה."],["232","37","נוסח ברכת אלקי נשמה כו' (מברכות ס, ב. רמב\"ם הל' תפלה פ\"ז ה\"ג. ועוד)."],["233","38","ראה המשך תרס\"ו ע' תעב. שם ע' תפה ואילך. <i>ובכ\"מ</i>."],["234","39","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380096\" data-slug=\"likkutei-torah\" data-id=\"4001380096\">ראה זח\"ג עג, א</a>. לקו\"ת ויקרא ה, ג. אוה\"ת וסה\"מ עת\"ר שבהערה הבאה. ובכ\"מ."],["235","40","ראה אוה\"ת פרשתנו ע' א'קכא. סד\"ה ואלה המשפטים עת\"ר (סה\"מ עת\"ר ע' קנא)."],["236","41","ויש לומר, שהשייכות דפירוש רז\"ל ש\"תשים לפניהם\" קאי על רב ששונה לתלמידיו (כנ\"ל ס\"ג) עם הפירוש הפשוט שזה קאי על משה, הוא כי \"כל ראשי ישיבות שבכל דור הן בחי' משה\" (<a class=\"ft-cite\" href=\"#/read/torah-or/3901370310\" data-slug=\"torah-or\" data-id=\"3901370310\">תו\"א יתרו סט, ג</a>)."],["237","42","ח\"ג (באד\"ר) קלח, רע\"א."],["238","43","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370340\" data-slug=\"torah-or\" data-id=\"3901370340\">תו\"א פרשתנו שם (עה, ג</a>. עו, ג). המשך תרס\"ו ע' רטז. ובכ\"מ."],["239","44","ויתירה מזה, דנשמת אברהם כמו שירדה למטה היא \"עפר ואפר\" לגבי שרשה באצילות (אגה\"ק סט\"ו (קכא, ב))."],["240","45","תו\"א שם."],["241","46","ויש לומר, דענין זה מרומז בזה שמקום הארון אינו מן המדה (יומא כא, א). דארון הו\"ע התורה, וזה שהתורה מושגת בשכל האדם הוא ע\"ד החיבור דלמעלה ממקום ומקום שבארון, מצד זה שהוא ית' הוא כל יכול ונמנע הנמנעות."],["242","47","ראה במדב\"ר פי\"ח, כא. תדא\"ר רפ\"ב. מדרש שמואל פכ\"ט. וראה לקו\"ת פ' ראה ד\"ה וכל בניך ס\"ב (כט, ג ואילך)."],["243","48","ב\"מ נט, ב."],["244","49","הדין ד\"צריך אתה לשום לפניהם טעם המיישב תלמודם\" הוא בכל דיני התורה. אלא שבחוקים \"טעם המיישב תלמודם\" הוא המקור דהדינים ואיך למדין אותם מהפסוקים (וכיו\"ב). ובמשפטים הוא גם טעם ההלכות עצמם."],["245","50","ומה שאמרו \"הראשונים מסיני\" – כי גם לימוד \"הראשונים\" ואפילו הדינים דחוקים הוא בהבנה והשגה, וגם הפס\"ד דהלכות אלו ניתן לרשותו של האדם (נצחוני בני נצחוני), ויתירה מזה שגם החוקים \"ראוי להתבונן בהם, וכל מה שאתה יכול ליתן לו טעם תן לו טעם\" (רמב\"ם סוף הל' תמורה). אלא שעיקר הענין דהבנה והשגה הוא במשפטים."],["246","51","במדבר טו, ג."],["247","52","ראה תיב\"ע עה\"פ שופטים ה, ה. תיב\"ע ומדרש תהלים עה\"פ סח, יז."],["248","53","קידושין מ, ב."],["249","54","<a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא רפמ\"א</a>. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380472\" data-slug=\"likkutei-torah\" data-id=\"4001380472\">לקו\"ת שלח מ, א</a>. ובארוכה – עטרת ראש דרוש לעשי\"ת נז, א. שם נט, ב."],["250","55","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ\"א (נז, א</a>) \"<i>והתורה</i> אמרה ועבדתם את ה' אלקיכם וגו'\". ולעיל ח\"ב ע' תטו, דע\"י שהעבודה דקבלת עול (עבודת עבד) הוא לפי <i>שהתורה</i> אמרה ועבדתם גו', נמשך מעין התענוג דתורה גם בהעבודה דקבלת עול."],["251","56","נדפס (עם הגהות הצ\"צ) באוה\"ת פרשתנו ע' א'קכז ואילך. וראה גם ד\"ה זה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540097\" data-slug=\"torat-chaim\" data-id=\"2300540097\">תו\"ח שמות עא, ב</a> ואילך [בהוצאה החדשה – משפטים ח\"ב רצג, א ואילך]. דרך חיים שער התפלה פס\"ו ואילך. סהמ\"צ להצ\"צ מצות יעוד ופדיון אמה העברי' (פג, ב אילך)."],["252","57","אוה\"ת שם ע' א'קכז."],["253","58","גיטין יג, א."],["254","59","אוה\"ת שם ע' א'קכח. סהמ\"צ שם פד, ב."],["255","60","<a class=\"ft-cite\" href=\"#/read/tanya/3401310017\" data-slug=\"tanya\" data-id=\"3401310017\">תניא רפי\"ב</a>."],["256","61","כ\"ה הלשון באוה\"ת שם ע' א'קלא."],["257","62","פרשתנו כא, ז."],["258","63","דהתחלת פרשיות אלה היא כי <i>תקנה</i> גו', וכי <i>ימכור</i> גו'. משא\"כ עבד כנעני שלאח\"ז [כא, כ ואילך. כא, כו ואילך]."],["259","64","<a class=\"ft-cite\" href=\"#/read/tanya/3401310019\" data-slug=\"tanya\" data-id=\"3401310019\">תניא ריש פי\"ד</a>."],["260","65","ספי\"ד."],["261","66","אוה\"ת שם ע' א'קלח. סהמ\"צ שם פד, ב."],["262","67","תו\"כ קדושים כ, כו. פרש\"י שם."],["263","68","כ\"ה הלשון בסהמ\"צ שם. ומבאר שם, שלכן יש בזה המעלה דאתכפיא <i>סט\"א</i>."],["264","69","כ\"ה להדיא באוה\"ת שם. וכמובן גם בפשטות, דכיון <i>שהתורה</i> ציותה לומר אפשי, צריכה להיות אמירה אמיתית."],["265","70","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370402\" data-slug=\"torah-or\" data-id=\"3901370402\">תו\"א ויקהל פט, ג</a>-ד. הוספה ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370511\" data-slug=\"torah-or\" data-id=\"3901370511\">תו\"א שם קיד, ג</a>-ד. ובכ\"מ."],["266","71","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310032\" data-slug=\"tanya\" data-id=\"3401310032\">תניא פכ\"ז</a> ולקו\"ת ר\"פ פקודי (מזח\"ב קכח, ב. וראה גם שם סז, ב. קפד, א). תו\"א שם. לקו\"ת חוקת סה, ג."],["267","72","ראה בארוכה לעיל ח\"ב ע' שסב. וראה עד\"ז תו\"א שם פט, סע\"ג \"ובאתעדל\"ת זו בבחי' ביטול שמסלק את עצמו כו' אתעדל\"ע כו' להיות נמשך בבחי' סוכ\"ע כו' שהוא ג\"כ בחי' הסתלקות עצמותו ומהותו ית' כו'\"."],["268","73","להעיר מלשון התו\"א שבהערה הקודמת \"<i>הסתלקות</i> עצמותו ומהותו ית' כו'\"."],["269","74","תו\"ח ולקו\"ת שבהערה 29."],["270","75","ישעי' נא, ד. ויק\"ר פי\"ג, ג."]]],[1500380006,"<h3>[בס\"ד. ש\"פ ויקהל, פ' שקלים, מבה\"ח אדר שני, ה'תשי\"א<sup data-n=\"271\">*</sup>].</h3>\nכי תשא את ראש בנ\"י, מרע\"ה דוקא רע\"מ ורעה אמונה\nאמונת או\"ה (סידור) בנ\"י, מקיף וצ\"ל ורעה, בפנימיות.\n<b>כי</b> תשא את ראש בנ\"י לפקודיהם ונתנו גו'. וצ\"ל דהול\"ל כי תפקוד את בנ\"י ומהו תשא ואת ראש דוקא, ולהבין זה הנה תוכן הפרשה הם ב' ענינים: שיקח משה מחה\"ש מכאו\"א לעבודת אוה\"מ. מצוה לדורות לתת בכל שנה מחה\"ש ללשכת המקדש ומשם היו מקריבים קרבנות הציבור וכו', וכמפורש במשנה שקלים, והנה ענין הראשון אינו חיוב תמידי כי משה נצטוה למנות את בנ\"י ואינו ציווי לדורות, ואדרבה, וכמאמר יואב שהשתמט ממנין בנ\"י. ענין הב' שנלקחו מחה\"ש לאדנים לא הי' אלא פ\"א, כמובן. חיוב הג' למדו רז\"ל – ומוכח ג\"כ מדה\"ב כד, ט – חיוב תמידי בכל שנה ושנה לתת מחה\"ש ושיקריבו ממנו קרבנות כו', ומנין בנ\"י בזה אינו נוגע כלל לידע סכומם, ומשמע בכ\"מ דגם לא מנו אותם. וא\"כ יקשה דמשטחיות הלשון משמע דלכל עניני הפרשה שייכת ההקדמה דכי תשא את ראש בנ\"י.\n<b>וכללות</b> הענין בזה בעבודה הוא, דבכדי להקריב את הקרבנות ע\"ג המזבח, שהיו מקריבים אותם ואש שלמעלה אכיל קרבנין ומחמת זה גם נה\"ב שבכאו\"א מישראל הי' נתמעט ונכלל בקדושה עד שכאו\"א הי' מקשר דעתו ובינתו לגדולת ה' להבטל אליו, ועתה נעשה זה ע\"י התפלה שכנגד קרבנות תקנום, הנה צ\"ל מתחילה נתינת כח וסיוע ע\"ז מלמעלה. וזהו\"ע שמשה רועה את האמונה ע\"י תורה וגמ\"ח, ועי\"ז נעשה הנשיאות והגבהת ראש בנ\"י, ההעלאה מלמטלמ\"ע ע\"י הקרבנות והתפלה.\n<b>ולהבין</b> שייכות ענין זה למשה רעיא מהימנא דוקא, אשר לו נאמר, כי תשא את ראש, זה יתנו גו' מחה\"ש, הנה נק' הוא רע\"מ ע\"ש שרועה את האמונה זן ומפרנס אותה. כי אמונה מצ\"ע יכולה להיות בדרך מקיף, וגנבא אפום מחתרתא ר\"ק<sup data-n=\"272\">1</sup>, ובדקות אפשר למצוא בכאו\"א בבעלי עסק שאף שמאמין שהוא הנותן לך כח גו', בכ\"ז מתעמק בתחבולות שהם מבלבלים אותו מתו\"ע<sup data-n=\"273\">2</sup> ושיעורים הקבועים גם לב\"ע<sup data-n=\"274\">3</sup>, שה\"ז דבר והיפוכו. וכן ביושבי אוהל שמאמין שזהו חכ' ורצונו שלהק', וכשמצליח בלימודו ועושה חיל ה\"ז מתפאר בזה ואצ\"ל כשלומד ע\"מ זה, ובמילא לפעמים יטה את הענין ובלבד שידו תהי' על העליונה. ולכן צריך להמשיך את האמונה בפנימיות בכחות נפשו שיתנהגו בפועל מתאים לאמונתו. וזהו נעשה דוקא ע\"י התבוננתו אליבא דנפשא ויתקע מח' בחוזק כדי שהתולדה מזה לא יהיו דמיונות שוא.\n<b>ובמה</b> היא ההתבוננות, הנה ידוע החילוק באמונה הבאה ע\"י חכ' החקירה והיא אמונת חסידי או\"ה, ואמונת בנ\"י. ממכ\"ע וסוכ\"ע. חיות המתלבש ונפרט לפרטים, ובמילא העולם מציאות אלא שבטל הוא להחיות המתלבש בתוכו, שם אלקים. סוכ\"ע מקיף כללי למעל' מהטו\"ד ומהתחלקות, אמונת בנ\"י. וזהו ג\"כ הטעם שלא נזהרו על השתוף.\n**********",[["271","*","המאמר שלפנינו – נעתק מגוכתי\"ק אדמו\"ר שליט\"א, שהתחיל לרשמו בעצמו, ולא סיים רשימתו.\nהנחה מהמאמר (בהוספת מ\"מ) נדפסה בתורת מנחם – התוועדויות ח\"ב ע' 259 ואילך."],["272","1","= רחמנא קריא."],["273","2","= מתורה ועבודה."],["274","3","= לבעלי עסק."]]],[1500380007,"(הנחה)\n<b>כי</b> תשא גו', הנה בפרשה זו<sup data-n=\"275\">1</sup> מבואר ענין העבודה במשכן ובמקדש דאקרי משכן<sup data-n=\"276\">2</sup>, ענין מעשה הקטרת, שזה הי' מהעבודות העקריות במשכן, ואעפ\"י שגם בפרשה הקודמת, פ' תצוה<sup data-n=\"277\">3</sup>, מדובר מענין הקטרת, וכן בפרשה הבאה, פ' ויקהל<sup data-n=\"278\">4</sup>, אבל שם מדובר רק בכללות, ובפרשה זו מבואר הענין בפרטות, דהיינו ההכנות לזה, וממה שהי' הקטרת נעשית, וכן גודל הענין שבזה, והלאוים הקשורים בזה וחומר הענין שבהם ועד לענין של היפך החיים להעובר עליהם, אשר גם ענין זה דהיפך החיים מבואר דוקא בפרשה זו מאחר שכאן מבואר חומר הענין, והגם שגם בקרבנות ישנם כו\"כ לאוים כמו חולין בעזרה ושחוטי חוץ וכו', אך אין זה מגיע לקטרת שחמורה כ\"כ עד לענין של היפך החיים להעושה במתכונתה.\n<b>והנה</b> ענין הקרבנות ומעשה הקטרת ה\"ז עבודת המשכן, וכמשנ\"ת במאמר דיום ההילולא שעיקר העבודה במשכן ומקדש הו\"ע עבודת הקרבנות (שכולל גם מעשה הקטרת), ולכן הי' המשכן מעצי שטים דוקא וכו' (כמבואר שם) ועיכ\"ז נעשה הושכנתי בתוכם, דהנה כללות ענין הקרבנות הו\"ע קירוב כל הכחות<sup data-n=\"279\">5</sup> ועד להקירוב אשר רזא דקורבנא עולה עד רזא דא\"ס<sup data-n=\"280\">6</sup>, אך ישנו חילוק בין קרבנות סתם למעשה הקטרת, דקרבנות נקראים אכילה וכמ\"ש<sup data-n=\"281\">7</sup> את קרבני לחמי לאשי גו', ולכן נקראים ישראל רעיתי<sup data-n=\"282\">8</sup>, דפי' רעיתי פרנסתי בשני תמידין כו' וכדאיתא במדרש<sup data-n=\"283\">9</sup> ישראל מפרנסין לאביהן שבשמים, משא\"כ מעשה הקטרת הו\"ע הריח, ואע\"פ שמצד ענין ההתכללות שבקדושה הנה גם בקרבנות ישנו ענין הריח, וכמ\"ש ריח ניחוח לה'<sup data-n=\"284\">10</sup> אך בעיקר הקרבנות הם ענין האכילה, וע\"כ היכן מחלקים בין נוקבא דפרדשקא הימנית לפרדשקא השמאלית, גבי קטרת דוקא, כיון שדוקא בקטרת הנה עיקר ענינה הוא הריח, וע\"כ הנה בכח הקטרת דוקא הוא להפך הלעו\"ז, דהנה הקרבנות צ\"ל מן המותר בפיך דוקא, משא\"כ בקטרת ישנו גם ענין המור שזהו\"ע הלעו\"ז וכמו שמבאראדמו\"ר הזקן<sup data-n=\"285\">11</sup> בענין ששה חדשים בשמן המור ומרדכי מירא דכיא, ולא רק שהמור הוא מלעו\"ז, אלא שכל אחד ואחד מסממני הקטרת קשור עם ענין הלעו\"ז, שהרי בקטרת דוקא י\"א סממנים (ואם חסר א' כו'), היינו שכל אחד מסממני הקטרת הוא אחד מן י\"א, שי\"א הוא ענין הלעו\"ז שאינו (כמו בקדושה ששם הוא) עשר ולא אחד עשר, ועוד שהרי י\"א סממנים אלו הם כנגד י\"א אלופי עשו, דהיינו שכל אחד מסממני הקטרת הוא כנגד אחד מאלופי עשו, וא\"כ כל אחד מן הי\"א סממנים קשור עם ענין הלעו\"ז, שענין הקטרת הוא להפך את הלעו\"ז לקדושה, והכח לזה הוא מאחר שקטרת הו\"ע הריח שמגיע למעלה יותר מקרבנות.\n<b>והנה</b> מעלת הריח הוא שמגיע בעצם הנפש, וע\"כ בכח הריח, ודוקא ריח חזק, לעורר מהשינה, שזה בכח הריח דוקא ואי\"ז בכח האכילה, ואדרבה, שאכילה גורמת לשינה, וע\"כ איתא במס' יומא<sup data-n=\"286\">12</sup> שהכ\"ג צריך למעט באכילתו בערב יוה\"כ, מפני שהמאכל מביא את השינה, משא\"כ ריח מעורר מהשינה, מאחר שמגיע בעצם הנפש, וזהו מה שעבודת הכה\"ג ביוה\"כ אחת בשנה היתה בקטרת דוקא שהו\"ע הריח, דכמו באדם למטה הנה הריח בכחו לעורר את עצם הנפש, כמו\"כ הוא במקדש שעבודה בריח הוא בקה\"ק, ואע\"פ שהי' נכנס לשם גם עם דם הקרבנות, אך עיקר העבודה בקה\"ק היתה בקטרת, וחידוש מעשה הקטרת ביוה\"כ הוא בקה\"ק, ומצד מעלת ענין הקטרת ע\"כ וכל אדם לא יהי' באהל מועד וגו'<sup data-n=\"287\">13</sup>, וגם בכל השנה (שבחסידות מבואר ענין זה לגבי יוה\"כ<sup data-n=\"288\">14</sup> – אבל כן הוא בכל השנה<sup data-n=\"289\">15</sup> מצד מעלת הקטרת), שהו\"ע הריח שמגיע בעצם הנפש, והנה כמו שבגשמיות בכח הריח דוקא לעורר מהשינה כמו\"כ הוא ברוחניות שבכדי לעורר מהשינה הוא ע\"י הריח דוקא, והנה ענין השינה נתבאר במאמר דפורים<sup data-n=\"290\">16</sup> בענין מש\"כ<sup data-n=\"291\">17</sup> אני ישנה ולבי ער קול דודי דופק וגו', והיינו שהגם דכנסת ישראל ישנה בגלותא, אך מאחר שלבי ער, דהיינו שהיחידה שבנפש היא בשלימות וער אצל כאו\"א, ע\"כ קול דודי דופק פתחי לי, בכדי שיהי' אחותי רעיתי יונתי תמתי (והנה במאמר הנ\"ל נתבאר פסוק זה דאני ישנה וגו' והמשך הפסוקים פשטתי את כתנתי וגו', אשר הביאור בהם הוא דלאחר הקול דודי דופק) הנה ע\"ז עונה כנסת ישראל פשטתי את כתנתי איככה אלבשנה, ומביא אדמו\"ר מהר\"ש ואדמו\"ר הצ\"צ ברשימותיו לשה\"ש (עה\"פ<sup data-n=\"292\">18</sup> דודי שלח ידו וגו') דבמד\"ר שה\"ש עה\"פ פשטתי את כתנתי וגו' איתא, דקאי על בגדי כהונה ובגדי מלכות שפשטו ממנו בגלות, דלכאורה אינו מובן השייכות דבגדי כהונה וכו' לכאן, ומבארים, דמאחר שאני ישנה בגלותא וקול דודי דופק לעורר מהשינה, ע\"כ התשובהע\"ז היא דפשטתי את כתנתי, שחסרים לה הבגדי כהונה כו', ולכן אי אפשר שתהי' עבודת הקרבנות שנק' ריח ניחוח לה', ובפרט מעשה הקטרת שהו\"ע הריח, והריח מעורר מהשינה, ומאחר דפשטתי בגדי כהונה ואין ריח הקרבנות והקטרת, א\"כ איככה אלבשנה להתעורר בבחי' אחותי רעיתי כו', וע\"ז משיבה רוח הקדש בשם הקב\"ה רחצתי את רגלי איככה אטנפם, דהנה ביהמ\"ק נקרא<sup data-n=\"293\">19</sup> הדום רגליו של הקב\"ה, ובביהמ\"ק הי' השראת השכינה, כמ\"ש<sup data-n=\"294\">20</sup> הנה השמים ושמי השמים לא יכלכלוך אף כי הבית הזה, שזו היא תמיהה קימת, אך לאחר שרחצתי את רגלי, אַז איך האָב זיך אָפּגעוואַשן מלהיות מתלבש בבית המקדש, א\"כ איככה כו'.\n<b>ואע\"פ</b> שגם בזמן הגלות ישנו ענין הקרבנות דתפלות כנגד קרבנות תקנום<sup data-n=\"295\">21</sup>, וכמו\"כ ישנו גם ענין הקטרת עכשיו, שזהו ענין תפלת מנחה, שנקראת מנחת קטרת, וכמבואר בהדרושים המבארים מעלת תפלת המנחה על שאר התפלות, ואף אלי' לא נענה אלא בתפלת המנחה<sup data-n=\"296\">22</sup>, כמ\"ש בהפטרה דשבת זו<sup data-n=\"297\">23</sup>. אך ההמשכה שע\"י התפלה היא רק בפנימיות העולמות, וידוע שההמשכה צריכה להיות גם בחיצוניות העולמות כמבואר בענין התורה שצריך להיות למוצאיהם בפה<sup data-n=\"298\">24</sup> דוקא, וכמו שמאריך אדמו\"ר הזקן בתניא<sup data-n=\"299\">25</sup>, וכן במצוות צריך להיות מעשה המצוות דוקא, ועד שכללות ענין התורה ומצות הוא דוקא למטה בעוה\"ז דלמצרים ירדתם<sup data-n=\"300\">26</sup>, ובקרבנות אמנם כן הוא שעל ידם הוא גילוי ההמשכה גם בחיצוניות העולמות, משא\"כ ע\"י התפלות דבמקום קרבנות תקנום ההמשכה היא רק בפנימיות העולמות, ולהיות שע\"י המצוות ההמשכה היא בחיצוניות העולמות, הנה ע\"ז עונה כנסת ישראל פשטתי את כתנתי וגו'.\n<b>וע\"ז</b> ממשיך בהפסוק, דודי שלח ידו מן החור, והיינו שהגם דרוה\"ק משיבה בשם הקב\"ה רחצתי את רגלי איככה גו', אבל מצד הענין דדודי שלח ידו, אשר דודי הו\"ע האהבה עצמית של הקב\"ה לנשמות ישראל (וכמו שמבאר אדמו\"ר הזקן בהמאמר על הפסוק קמתי אני לפתוח לדודי, ונתבאר בשיחת כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע<sup data-n=\"301\">27</sup>), ומצד האהבה עצמית, הנה שלח ידו מן החור, דחור הוא גם מל' חור כרפס וכן מל' חרות<sup data-n=\"302\">28</sup> ועי\"ז נעשה הפתחי לי, ולאחר הפתחי לי הד' דרגות דאחותי רעיתי יונתי תמתי, שאלו הן ד' מדריגות בין בהעבודה בענין האהבה, דליתפולחנא כפולחנא דרחימותא<sup data-n=\"303\">29</sup>, ובין בעבודה דקיום המצוות, דד' מדריגות אלו הן כנגד ד' אותיות דשם הוי'<sup data-n=\"304\">30</sup>, ועי\"ז הנה ליהודים היתה אורה ושמחה וששון ויקר<sup data-n=\"305\">31</sup>, אשר בד\"א י\"ל שהד' ענינים דאורה ושמחה וגו' הם כנגד הד' אותיות דשם הוי', דאורה זו תורה<sup data-n=\"306\">32</sup> וכמ\"ש<sup data-n=\"307\">33</sup> כי נר מצוה ותורה אור, שזהו\"ע ספירת החכמה, שמחה הו\"ע מועדים<sup data-n=\"304\">30</sup> לשמחה, שהו\"ע ספירת הבינה, וששון זו מילה<sup data-n=\"304\">30</sup> שזהו\"ע ספירת היסוד שהוא עיקר הז\"א, ויקר אלו תפלין<sup data-n=\"304\">30</sup> שהם בחי' המלכות וכמבואר בסוף דשערי אורה<sup data-n=\"308\">34</sup> וכמו שהיא בשרשה בעצמות א\"ס ב\"ה, שזהו מש\"כ בזהר חדש<sup data-n=\"309\">35</sup> שתפלין הם דיוקנאה דחותמי' דמלכא עילאה, דדיוקנא וחותם הו\"ע ספירת המלכות, והיינו שע\"י הפתחי לי נמשך הד' אותיות דשם הוי' בעבודה, וכן בהאורה ושמחה וגו'.\n<b>וזהו</b> ג\"כ מש\"כ <i>ליהודים</i> היתה אורה וגו' וכמ\"ש בגמרא<sup data-n=\"310\">36</sup> דכל הכופר בע\"ז נק' יהודי, והיינו שקודם ישנו ענין המס\"נ שבזה עמדו אז בימי הפורים, וזהו\"ע הפתחו לי כחודה של מחט שהו\"ע המס\"נ, ואח\"כ הן הד' מדרי' דאורה ושמחה וששון ויקר, וזהו ג\"כ מש\"כ<sup data-n=\"311\">37</sup> איש יהודי הי' בשושן הבירה ושמו מרדכי, דמרדכי מן התורה מנין שנאמר<sup data-n=\"312\">38</sup> מר דרור, ומתרגמינן מירא דכיא<sup data-n=\"313\">39</sup>, וכמבואר בתו\"א<sup data-n=\"314\">40</sup>, ויהודי הו\"ע המס\"נ כנ\"ל, דיהודי הוא מל' הודאה שלמעלה מטו\"ד, וזה פעל בכולם את ענין המס\"נ שכולם נק' יהודיים דוקא וכבמרז\"ל שזהו היפך מצבם הקודם שהשתחוו לאנדרטי' כמסופר בגמרא<sup data-n=\"315\">41</sup>, ואח\"כ נמשך ממס\"נ זה בהד' אותיות דשם הוי', אורה ושמחה וששון וגו' ועד לאורה ושמחה וששון ויקר למטה מעשרה טפחים, כפשוטו של מקרא.\n**********",[["275","1","ל, לד ואילך."],["276","2","עירובין ב, א. וש\"נ."],["277","3","ל, ז ואילך."],["278","4","לז, כט."],["279","5","ספר הבהיר סמ\"ו."],["280","6","זח\"ב רלט, א. זח\"ג כו, ב."],["281","7","פנחס כח, ב."],["282","8","שה\"ש א, ט."],["283","9","שהש\"ר א' ע\"פ לסוסתי. זח\"ג ז, ב."],["284","10","עטרת ראש לו, ב. ד\"ה וירח ה' את ריח הניחוח תרד\"ע ואילך (המשך תער\"ב ח\"א ע' תלו ואילך). זח\"ג קל, ב. רפט, א."],["285","11","בתו\"א דרושי פורים (צב, א. צט, א)."],["286","12","יח, א."],["287","13","אחרי טז, יז."],["288","14","אוה\"ת יוה\"כ ד\"ה וכל אדם (ע' א'תקנה ואילך)."],["289","15","יומא מד, א."],["290","16","ד\"ה בלילה ההוא פ\"ב (סה\"מ תשכ\"ח ע' קלב ואילך)."],["291","17","שה\"ש ה, ב."],["292","18","שם, ד."],["293","19","דברי הימים-א כח, ב."],["294","20","מלכים-א ח, כז."],["295","21","ברכות כו, ב."],["296","22","ברכות ו, ב."],["297","23","מלכים-א יח, לו."],["298","24","עירובין נד, א."],["299","25","פל\"ז."],["300","26","שבת פח, סע\"ב."],["301","27","בסה\"ש תורת שלום ליל שמח\"ת תרס\"ו – בהנחת כ\"ק מו\"ח אדמו\"ר (ע' 59 ואילך)."],["302","28","רשימות הצ\"צ (<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770161\" data-slug=\"or-hatorah-hb\" data-id=\"8316770161\">אוה\"ת שה\"ש ח\"ב ע' תקכט</a>)."],["303","29","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380482\" data-slug=\"likkutei-torah\" data-id=\"4001380482\">ראה זהר ח\"ב נה, ב</a>. ח\"ג רסז, א. לקו\"ת שלח מב, ג."],["304","30","וכמבואר ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381265\" data-slug=\"likkutei-torah\" data-id=\"4001381265\">לקו\"ת שה\"ש (לד, א</a> ואילך) ובמאמר דאדמו\"ר מוהר\"ש דשנת תרכ\"ח (ע' פב ואילך)."],["305","31","מגלת אסתר ח, טז."],["306","32","מגילה טז, ב."],["307","33","משלי ו, כג."],["308","34","מח, ב ואילך."],["309","35","שה\"ש עט, ב."],["310","36","מגילה יג, רע\"א."],["311","37","מג\"א ב, ה."],["312","38","תשא ל, כג."],["313","39","חולין קלט, ב."],["314","40","מג\"א צ, ד."],["315","41","מגילה יב, א. תוד\"ה שלא ע\"ז ג, א."]]],[1500380008,"<h3>בס\"ד. ש\"פ תצוה, יו\"ד אדר-ראשון ה'תשמ\"א<sup data-n=\"316\">*</sup></h3>\n<b>ואתה</b> תצוה את בני ישראל ויקחו אליך שמן זית זך כתית למאור להעלות נר תמיד<sup data-n=\"317\">1</sup>, וידועים הדיוקים בזה<sup data-n=\"318\">2</sup> דבכל הציווים שבתורה נאמר צו את בני ישראל וכיו\"ב, וכאן נאמר ואתה תצוה את בני ישראל. ולהוסיף, דהדיוק מ\"ש ואתה תצוה הוא לא רק בהלשון אלא גם בהתוכן, דלשון ואתה תצוה משמע שמשה הוא המצַוה, וצריך להבין, הרי משה הוא השליח למסור לישראל את ציווי הקב\"ה, ולמה נאמר ואתה תצוה. גם צריך להבין מ\"ש ויקחו אליך, שיביאו השמן למשה<sup data-n=\"319\">3</sup> (אליך), דלכאורה, כיון שהעלאת הנרות היתה ע\"י אהרן, למה הוצרך להביא את השמן למשה. גם צריך להבין מ\"ש שמן גו' כתית למאור, דלכאורה הול\"ל שמן גו' להאיר. גם צריך להבין, דבפסוק שלאח\"ז<sup data-n=\"320\">4</sup> נאמר מערב עד בוקר וכאן נאמר להעלות נר תמיד.\nב) <b>ומבאר</b> כ\"ק מו\"ח אדמו\"ר (במאמרו הידוע ד\"ה וקבל היהודים<sup data-n=\"321\">5</sup> שנאמר בפורים קטן תרפ\"ז<sup data-n=\"322\">6</sup>), דציווי (תצוה) הוא צוותא וחיבור<sup data-n=\"323\">7</sup>. וזהו ואתה תצוה את בני ישראל, שמשה הוא מקשר ומחבר את בני ישראל עם אוא\"ס<sup data-n=\"324\">8</sup>. וע\"י שמשה משפיע לישראל (שמקשר אותם עם אוא\"ס), עי\"ז נעשה יתרון והוספה במשה. [דמשה וישראל הם דוגמת ראש ורגל, כמ\"ש<sup data-n=\"325\">9</sup> שש מאות אלף רגלי העם אשר אנכי בקרבו, דכל ישראל הם הרגלים דמשה, ומשה הוא הראש שלהם. וכמו שבאדם הרגלים מוליכים את הראש למקום שהראש מצד עצמו אינו יכול להגיע לשם, כמו\"כ הוא במשה וישראל, שע\"י ישראל (הרגלים דמשה) מיתוסף עילוי במשה. דזהו מ\"ששש מאות אלף רגלי העם אשר אנכי בקרבו, שע\"י רגלי העם נמשך הגילוי דאנכי בקרבו של משה<sup data-n=\"326\">10</sup>]. וזהו ואתה תצוה את בני ישראל ויקחו אליך שמן זית גו', דע\"י שמשה יצַוה ויקשר את בני ישראל עם אוא\"ס, עי\"ז יביאו בני ישראל שמן זית למשה (ויקחו אליך), שיוסיפו תוספות אור במשה.\nג) <b>ולבאר</b> זה, מקדים בהמאמר<sup data-n=\"327\">11</sup> שמשה רבינו נקרא רעיא מהימנא, דשני פירושים בזה. שהוא רועה נאמן של ישראל ושהוא זן ומפרנס את ישראל בענין האמונה. דהאמונה שישנה בישראל מצד עצמם, שישראל הם מאמינים בני מאמינים<sup data-n=\"328\">12</sup>, אפשר שתהי' בבחינת מקיף, וזה שמשה רועה ומפרנס את ישראל בענין האמונה הוא שהאמונה תהי' בפנימיות. וזהו מ\"ש בזהר<sup data-n=\"329\">13</sup> ההיא אמונה דלעילא יתזן ויתפרנס מני' על ידך (ע\"י משה), דזה שמשה זן ומפרנס את האמונה הוא שממשיך אותה בפנימיות. וממשיך בהמאמר, דזה שמשה הוא רעיא מהימנא, הכוונה בזה היא גם לאתפשטותא דמשה שבכל דור<sup data-n=\"330\">14</sup>, דראשי אלפי ישראל שבכל דור הם מחזקים את האמונה דישראל (שבדורם), שהאמונה שלהם תהי' בפנימיות. וכמו מרדכי<sup data-n=\"331\">15</sup>, שהי' האתפשטותא דמשה שבדורו, כמארז\"ל<sup data-n=\"332\">16</sup> שמרדכי בדורו כמשה בדורו, שגם בזמן גזירת המן, שלימוד התורה וקיום המצוות אז הי' קשור עם מס\"נ, הקהיל קהילות ברבים לחזק את אמונתם של ישראל בהוי' ולעמוד חזק בלימוד התורה וקיום המצוות. ולאחרי שמבאר בארוכה שמשה ואתפשטותא דילי' שבכל דרא מחזקים את האמונה דישראל, מבאר<sup data-n=\"333\">17</sup> דיוק לשון הכתוב שמן גו' כתית למאור (למאור ולא להאיר), שבזמן הגלות, שכאו\"א הוא נשבר ונדכא, כתית, עי\"ז מגיעים למאור (העצם) שממנו נמצא האור. וצריך להבין השייכות דהפירוש בכתית למאור להמבואר (בהמאמר) לפנ\"ז שמשה [ואתפשטותא דילי' שבכל דרא] זן ומפרנס את האמונה שתהי' בפנימיות.\nד) <b>והנה</b> הביאור בפסוק ואתה תצוה בא (בהמאמר) בהמשך להמבואר בתחלת המאמר, דפירוש וקבל היהודים את אשר החלו לעשות<sup data-n=\"334\">18</sup> הוא שקבלו מה שהחלו בהזמן דמתן תורה<sup data-n=\"335\">19</sup>. דבמתן תורה היתה ההתחלה (החלו לעשות), ובימי אחשורוש (בזמן גזירת המן) היתה הקבלה, וקבל היהודים. [וע\"ד מארז\"ל<sup data-n=\"336\">20</sup> עה\"פ<sup data-n=\"337\">21</sup>קיימו וקבלו היהודים, קיימו מה שקבלו כבר, דזה שהקדימו נעשה לנשמע במ\"ת היתה רק הקבלה, ובימי אחשורוש<sup data-n=\"338\">22</sup> <i>קיימו</i> מה שקבלו<sup data-n=\"339\">23</sup>]. ומדייק בהמאמר, שלכאורה הוא דבר פלא<sup data-n=\"340\">24</sup>, דבמתן תורה היו ישראל בתכלית העילוי, והי' אז אצלם גילוי אלקות בדרגא הכי נעלית [דנוסף לזה שגם קודם מ\"ת היו גילויים נעלים ביותר, הגילוי שהי' ביציאת מצרים ובפרט בקריעת ים סוף, הנה הגילוי שהי' בשעת מ\"ת הי' גילוי נעלה עוד יותר], ובימי אחשורוש היו ישראל בתכלית הירידה, דנוסף לההעלם וההסתר שבכל גלות [דכל גלות הוא בדוגמת גלות מצרים<sup data-n=\"341\">25</sup>, וכמו שבגלות מצרים כתיב<sup data-n=\"342\">26</sup> ולא שמעו אל משה מקוצר רוח ומעבודה קשה, עד\"ז הוא בכל גלות, שישנם כמה נסיונות בקיום התורה והמצוות], הנה אז (בזמן גזירת המן) הי' ההעלם וההסתר עוד יותר, ואעפ\"כ, בזמן מתן תורה, כשהיו ישראל בתכלית העילוי, היתה רק ההתחלה (החלו לעשות), ובזמן גזירת המן, כשהיו בתכלית השפלות, אז דוקא קבלו מה שהחלו במתן תורה. ומבאר בזה, דבזמן הגזירה, הי' קיום התומ\"צ שלהם במס\"נ. [דנוסף לזה שהי' להם מס\"נ שלא לכפור ח\"ו [כמבואר בתו\"א<sup data-n=\"343\">27</sup>, שבאם היו ממירים דתם לא היו עושים להם כלום, כי הגזירה היתה רק על היהודים, ואעפ\"כ לא עלתה על דעתם מחשבת חוץ ח\"ו], הי' להם מס\"נ גם על קיום התומ\"צ<sup data-n=\"344\">28</sup>, ועד שהקהילו קהילות ברבים ללמוד תורה במס\"נ<sup data-n=\"345\">29</sup>]. והתעוררות המס\"נ שלהם היתה ע\"י מרדכי היהודי, משה שבדורו. וזהו וקבל היהודים את אשר החלו לעשות, דבמתן תורה היתה רק ההתחלה ובזמן גזירת המן היתה הקבלה, כי ע\"י שהי' להם אז מס\"נ בפועל על תומ\"צ נתעלו (בענין זה) למדריגה נעלית יותר מכמו שהיו בזמן מתן תורה, ולכן אז דוקא היתה הקבלה, וקבל היהודים.\n<b>ולכאורה</b> יש לומר, שהפירוש בכתית למאור, שע\"י כתית (נשבר ונדכא) מגיעים להמאור, הוא ביאור על זה שבזמן הגזירה דוקא באו למס\"נ באופן נעלה ביותר<sup data-n=\"346\">30</sup>. כי מס\"נ היא מצד עצם הנשמה שלמעלה מגילוי, מאור (שממנו נמצא האור), וע\"י שהיו אז במצב דכתית (נשבר ונדכא), נתגלה עצם הנשמה, מאור. אבל מהמשך וסדר הענינים בהמאמר שהפירוש בכתית למאור בא לאחרי הענין דרעיא מהימנא, משמע, דענין כתית למאור שייך גם לזה שמשה זן ומפרנס את האמונה שתהי' בפנימיות.ה) <b>ויש</b> לבאר זה ע\"פ הידוע<sup data-n=\"347\">31</sup> דזה שישראל מאמינים באלקות באמונה פשוטה ואין צריכים ראיות על זה הוא מצד שני טעמים. לפי שמזלייהו חזי<sup data-n=\"348\">32</sup>. דהנשמה שלמעלה <i>רואה</i> אלקות (ראי' שלמעלה משכל), וזה פועל בהנשמה שבגוף האמונה באלקות. ועוד ביאור, דשורש האמונה הוא מעצם הנשמה (שלמעלה ממזלי' חזי). דזה שעצם הנשמה מקושרת באלקות היא התקשרות עצמית (שאינה תלוי' בסיבה, גם לא בענין הראי' שלמעלה משכל). ויש לומר, דמהחילוקים שבין שני הביאורים (הענינים) הוא, דהאמונה בהנשמה המלובשת בגוף הבאה מראיית הנשמה שלמעלה היא בבחינת מקיף. דכיון שהנשמה שלמעלה היא למעלה מהתלבשות לכן פעולתה בהנשמה המלובשת בגוף היא בבחינת מקיף. ובכדי שהאמונה (בהנשמה המלובשת בגוף) תהי' בפנימיות, הוא ע\"י גילוי ההתקשרות עצמית דעצם הנשמה. כי עצם הנשמה היא העצם של הנשמה המלובשת בהגוף, ולכן, האמונה דהנשמה המלובשת בהגוף שמצד עצם הנשמה היא בפנימיותה.\n<b>ועפ\"ז</b> יש לבאר קשר הענינים שבהמאמר, שהענין ד(כתית) למאור בא בהמשך לביאור הענין דרעיא מהימנא, כי זה שמשה זן ומפרנס את האמונה שתהי' בפנימיות הוא ע\"י שהוא מגלה את עצם הנשמה (שלמעלה ממזלי' חזי), מָאור שלמעלה מאור. ומ\"ש <i>כתית</i> למאור, ומבאר בהמאמר שבכדי להגיע להמאור הוא ע\"י הענין דכתית שבזמן הגלות, הוא, כי <i>עיקר</i> הגילוי דעצם הנשמה (מאור) הוא בענין המס\"נ (שעיקרו הוא בזמן הגלות), כדלקמן.\nו) <b>והענין</b> הוא, דזה שהאמונה דישראל היא באופן שהוא מוסר נפשו על זה, הוא (בעיקר) בהאמונה שמצד עצם הנשמה. דהאמונה מצד זה שהוא רואה (מזלי' חזי), הגם שהיא בתוקף גדול [כידוע דההתאמתות שמצד הראי' היא התאמתות גדולה ביותר<sup data-n=\"349\">33</sup>], מ\"מ, כיון שהאמונה שלו היא מצד סיבה (מצד זה שרואה) ואינה קשורה עם עצם מציאותו, אינו מוכרח שימסור נפשו על זה, וזה שהאמונה דישראל היא באופן שהוא מוסר נפשו על זה הוא מפני שהאמונה באלקות היא העצם שלו, ולכן אי אפשר כלל שיכפור ח\"ו.\n<b>ועפ\"ז</b> יש לבאר מ\"ש בהמאמר דזה שמשה הוא רעיא מהימנא (שהוא זן ומפרנס את האמונה) הוא גם בנוגע לרועי ישראל שבכל דור (אתפשטותא דמשה שבכל דרא) שהם מחזקים את האמונה דישראל שיעמדו במס\"נ בקיום התומ\"צ. דלכאורה, זה שמשה זן ומפרנס את האמונה הוא (כמבואר בכ\"מ<sup data-n=\"350\">34</sup> וגם במאמר זה עצמו<sup data-n=\"351\">35</sup>) ע\"י שמשפיע לישראל דעת באלקות שעי\"ז באה האמונה בפנימיות, וזהשרועי ישראל שבכל דור מחזקים האמונה (המבואר במאמר זה<sup data-n=\"352\">36</sup>) הוא שהאמונה דישראל תהי' באופן דמס\"נ. וע\"פ הנ\"ל יש לומר, <i>שעיקר</i> הענין דרעיא מהימנא הוא זה שהוא זן ומפרנס את האמונה עצמה, שהאמונה תהי' לא רק כמו שהיא מצד הגילויים (מצד זה שהנשמה שלמעלה רואה אלקות) אלא מצד עצם הנשמה. וזה שמשה ממשיך את האמונה בפנימיות (בדעת והשגה) הוא <i>תוצאה</i> מזה שהוא זן ומפרנס את האמונה עצמה (המשכת וגילוי האמונה כמו שהיא מצד עצם הנשמה). וכנ\"ל (סעיף ה), דהמשכת האמונה בפנימיות (בדעת) הוא ע\"י גילוי ההתקשרות עצמית דעצם הנשמה. ועפ\"ז יש לומר, דבזה שבהדורות שהוצרכו למס\"נ בפועל חיזקו רועי ישראל (אתפשטותא דמשה) את האמונה דישראל שתהי' במס\"נ, נתגלה הענין דרעיא מהימנא (בענין זה<sup data-n=\"353\">37</sup>) עוד יותר מבמשה עצמו. כי המשכת וגילוי האמונה כמו שהיא מצד עצם הנשמה [שע\"י משה ואתפשטותא דילי' שבכל דרא], עיקר התגלותה הוא מס\"נ בפועל.\nז) <b>והנה</b> ידוע שהמס\"נ בפועל על תומ\"צ של <i>כל ישראל</i> היתה בפורים (בזמן גזירת המן). שהמס\"נ דחנוכה (בזמן גזירת יון) היתה (בעיקר) במתתיהו ובניו, והמס\"נ בזמן גזירת המן היתה <i>בכל ישראל</i>. ועפ\"ז יש לבאר מה שמובא בהמאמר<sup data-n=\"354\">38</sup> ממדרש&lt;16&gt; שמרדכי הי' שקול בדורו כמשה בדורו, דהגם שאתפשטותא דמשה הוא בכל דור מ\"מ איתא במדרש שמרדכי (דוקא) הי' שקול בדורו כמשה בדורו. ויש לומר, שמהמעלות דמרדכי היהודי הוא שהוא הי' הרעיא מהימנא (<i>בגילוי</i>) של <i>כל ישראל</i> שבדורו. בדוגמת משה רעיא מהימנא שהמשיך דעת לכל ישראל שבדורו, כמובן גם מזה שדורו של משה (כל אנשי דורו) נק' דור דעה<sup data-n=\"355\">39</sup>. [אלא שבמשה הי' גילוי ענין זה (שהוא רעיא מהימנא דכל ישראל) ע\"י שהמשיך דעת לכל אנשי דורו, ובמרדכי הי' גילוי ענין זה ע\"י שגילה כח המס\"נ שבכל אנשי דורו]. ויש לומר, דע\"י שמביא בהמאמר מ\"ש במדרש שמרדכי בדורו הי' שקול כמשה בדורו, עי\"ז פסק בעל המאמר את הדין על עצמו<sup data-n=\"356\">40</sup>, שהוא הרעיא מהימנא (<i>בגילוי</i>) של כל אנשי הדור.\nח) <b>ועפ\"ז</b> יש לבאר קשר (וסדר) הענינים (בהמאמר) בביאור הפסוק ואתה תצוה גו', שבתחלה מבאר את הפירוש דואתה תצוה את בני ישראל, שמשה הוא מקשר ומחבר את בני ישראל (עם אוא\"ס) ע\"י שהוא זן ומפרנס את האמונה, ולאח\"ז מבאר שגם רועי ישראל שבכל דור (אתפשטותא דמשה) מחזקים את האמונה דישראל וכמו מרדכי (משה שבדורו) שחיזק את אמונתם של ישראל לעמוד חזק בלימוד התורה וקיום המצוות, ולאח\"ז מבאר הפירוש בכתית למאור (שבפסוק ואתהתצוה שמדבר לכאורה במשה עצמו), כי זה שמשה מגלה בחינת המאור דישראל (עצם הנשמה), הוא בעיקר ע\"י אתפשטותא דילי' שבזמן הגלות (כתית) שעוררו בישראל כח המס\"נ שלהם, שעי\"ז הוא <i>עיקר</i> גילוי עצם הנשמה, מאור.\n<b>וצריך</b> להבין, דלפי ביאור הנ\"ל, הענין דכתית למאור שייך לואתה תצוה את בני ישראל, לזה שמשה ואתפשטותא דילי' שבכל דור מקשרים ומחברים את ישראל עם אוא\"ס, ובהכתוב נאמר כתית למאור בהמשך לויקחו אליך שמן זית זך, דענין ויקחו אליך גו' (שישראל מביאים שמן למשה) הוא שישראל מוסיפים תוספות אור במשה (כמובא לעיל ס\"ב מהמאמר).\nט) <b>והנה</b> הכתוב וקבל היהודים את אשר החלו לעשות מדבר (בפשטות) בהזמן <i>שלאחרי</i> הנס דפורים. ויש לומר, דמ\"ש בהמאמר דפירוש וקבל היהודים את אשר החלו לעשות הוא שבימי אחשורוש קיבלו מה שהחלו במתן תורה, הוא גם לפי פשטות הכתוב שוקבל גו' הי' לאחרי הנס. ועפ\"ז, בזה שבימי אחשורוש קיבלו מה שהחלו במתן תורה, שני ענינים. הקבלה שהיתה בזמן הגזירה ע\"י המס\"נ שלהם (כמפורש בהמאמר), והקבלה שהיתה לאחרי הנס דפורים, שהיא נעלית יותר גם מהקבלה בזמן הגזירה (כדלקמן). ויש לומר, שעד\"ז הוא בנוגע כתית למאור, שע\"י הענין דכתית שבזמן הגלות מגיעים להמאור, דשני ענינים בזה. כשישראל נמצאים במצב של כתית מצד זה שישנם גזירות על קיום התומ\"צ (כמו שהי' בזמן אמירת המאמר), ועי\"ז מגיעים להמאור ע\"י המס\"נ שלהם. ועוד ענין בכתית למאור, שגם כשישראל נמצאים במצב של הרחבה, הרחבה בגשמיות וגם הרחבה ברוחניות, אלא שהם נמצאים בגלות<sup data-n=\"357\">41</sup> [וע\"ד המצב שהי' לאחרי הנס דפורים, שליהודים היתה אורה ושמחה וששון ויקר<sup data-n=\"358\">42</sup>, בפשטות וגם ברוחניות<sup data-n=\"359\">43</sup> [ויתירה מזה <i>שגם בית המן ניתן לאסתר</i><sup data-n=\"360\">44</sup>, שהי' אז גם המעלה דאתהפכא], אלא שאכתי עבדי אחשורוש אנן<sup data-n=\"361\">45</sup>], הם שבורים ונדכאים (כתית) מזה שהם בגלות. וע\"י הכתית דישראל מזה שנמצאים בגלות, מגיעים להמאור.\n<b>והענין</b> הוא, דזה שישראל הם שבורים מזה שהם בגלות (גם כשיש להם הרחבה בגשמיות וברוחניות), הוא, כי רצונו האמיתי של כל אחד מישראל הוא שיהי' גילוי אלקות, ועד שזה (גילוי אלקות) נוגע לעצם מציאותו, ולכן, זה שבזמן הגלות אין מאיר גילוי אלקות כמו שהי' בזמן הבית [ובפרט כשמתבונן בזה שארז\"ל<sup data-n=\"362\">46</sup> כל מי שלא נבנה ביהמ\"ק בימיו ה\"ז כאילו נחרב בימיו], הנה מזה עצמו איז ער אינגאַנצן צוטרייסלט, כתית. וגם כשהוא בדרגא נעלית ביותר שמאיר אצלו גילויאלקות בדוגמת הגילוי שהי' בזמן הבית<sup data-n=\"363\">47</sup>, מ\"מ, מזה שבכללות העולם אין מאיר הגילוי, מוכח, שגם הגילוי שמאיר אצלו הוא גילוי מוגבל. דכשמאיר גילוי אוא\"ס הבל\"ג הגילוי הוא בכל מקום, וכשישנו מקום אחד (אפילו פינה נדחת) שאין מאיר שם גילוי אלקות, הוא מפני שהגילוי (גם בהמקום שהוא מאיר) הוא גילוי מוגבל. [וזהו מה שמובא במאמר אדמו\"ר הזקן<sup data-n=\"364\">48</sup> דאיתא בתיקונים<sup data-n=\"365\">49</sup> שאפילו אם הי' צדיק אחד חוזר בתשובה שלימה בדורו הי' בא משיח, כי ע\"י תשובה שלימה ממשיכים גילוי אוא\"ס הבל\"ג, וגילוי זה הוא בכל מקום]. ומזה שאין מאיר אצלו גילוי עצמות אוא\"ס, הוא נשבר ונדכא, כתית. [וע\"ד הידוע שחולה בגימטריא מ\"ט, שגם כשמשיג מ\"ט שערי בינה אלא שחסר לו שער הנו\"ן, הוא חולה<sup data-n=\"366\">50</sup>]. וידוע מ\"ש הצ\"צ<sup data-n=\"367\">51</sup> שהי' נשמע ממורינו ורבינו נ\"ע (אדמו\"ר הזקן) איך וויל זע גאָר ניסט איך וויל ניט דאיין ג\"ע איך וויל ניט דאיין עוה\"ב כו' איך וויל מער ניט אַז דיך אַליין. וע\"י שהי' נשמע לשון זה מאדמו\"ר הזקן [דפירוש <i>הי'</i> נשמע הוא שזה הי' לא רק בזמנים מיוחדים אלא שזה הי' דבר הרגיל], ובפרט לאחרי שנתפרסם זה ע\"י הצ\"צ, ניתן הכח לכאו\"א מישראל שעיקר רצונו יהי' גילוי העצמות, ועד כדי כך, שכשאין מאיר גילוי זה, ומכש\"כ בזמן הגלות שאין מאיר אפילו הגילוי (גילוי <i>אור</i>) שהי' בזמן הבית, הוא במצב דכתית, ומבקש ג' פעמים בכל יום (או יותר) ותחזינה עינינו בשובך לציון ברחמים, שאז יהי' גילוי אלקות ועד לגילוי העצמות. וזהו כתית למאור, שע\"י הענין דכתית מזה שנמצאים בגלות מגיעים להמאור, כי זה שהרצון דכל אחד מישראל הוא גילוי אלקות ועד שזה נוגע לעצם מציאותו [שלכן הוא נשבר ונדכא (כתית) מזה שבזמן הגלות לא יש גילוי אלקות] הוא מצד עצם הנשמה, מאור שבנשמה, שהתקשרותה באלקות היא התקשרות עצמית.\nיו\"ד) <b>ויש</b> לומר, שבחינת המאור דהנשמה המתגלית ע\"י הענין דכתית מזה שנמצאים בגלות, היא נעלית יותר מבחינת המאור דהנשמה שמתגלית ע\"י מס\"נ. והענין הוא, דמהטעמים על זה שבמתן תורה היתה רק ההתחלה (החלו לעשות) ובימי אחשורוש היתה הקבלה (וקבל היהודים) הוא, כי זה שהקדימו נעשה לנשמע במתן תורה הי' מפני שכפה עליהם הר כגיגית<sup data-n=\"368\">52</sup>, גילוי מלמעלה<sup data-n=\"369\">53</sup>, ובימי אחשורוש היתה הקבלה מצד עצמם. ויש לומר, שהאמונה דישראל מצד זה שהנשמה שלמעלה <i>רואה</i> אלקות (אמונה שמצד סיבה) הוא ע\"ד שהקדימו נעשה לנשמע (במ\"ת) מצד הגילוי דלמעלה<sup data-n=\"370\">54</sup>, וזה שבימי אחשורוש היתה הקבלה מצד עצמם, הוא,כי אז נתגלה ההתקשרות באלקות שמצד עצם הנשמה, התקשרות עצמית שמצד עצם מציאותם. ובפרטיות יותר יש לומר, שגם בגילוי עצם הנשמה, ישנם (דוגמת) שני ענינים הנ\"ל. דגילוי עצם הנשמה בענין המס\"נ, יש לומר, שבנוגע <i>לכחות הגלויים</i> הוא <i>כמו</i> דבר נוסף. וכמו שרואים בפועל בכמה אנשים, שבהיותם במקום שהיו שם גזירות על תומ\"צ, הי' להם מס\"נ בפועל משך כו\"כ שנים, וכשבאו אח\"כ למדינות שאפשר לעסוק בתומ\"צ מתוך הרחבה, אין ניכר בהם (כ\"כ) המס\"נ שהי' להם מקודם. כי זה שעמדו במס\"נ משך כו\"כ שנים הוא לפי שהאיר בהם גילוי עצם הנשמה שלמעלה מכחות הגלויים ולא נעשה עי\"ז שינוי בכחות הגלויים עצמם<sup data-n=\"371\">55</sup>. [דזה שעצם הנשמה היא העצם (גם) <i>דכחות הגלויים</i> (כנ\"ל סעיף ה), הוא, שעצם הנשמה הוא <i>העצם</i> שלהם ואין זה שייך לענינם של כחות הגלויים עצמם, <i>להציור</i> שלהם]. והגילוי דעצם הנשמה בזה שהוא נשבר ונדכא מזה שהוא נמצא בגלות הוא שגם כחות הגלויים שלו (<i>הציור</i> דכחות הגלויים) הם כמו חד עם העצם<sup data-n=\"372\">56</sup>. ויש לומר, דזה שעצם הנשמה והציור דהכחות הם (דוגמת) שני ענינים, הוא לפי שגם עצם הנשמה היא מוגדרת בגדר, והגדר שלה היא למעלה מהציור דהכחות. אבל מצד עצם הנשמה כמו שהיא מושרשת בהעצמות, הפשיטות דהנשמה והציור דהכחות שלה הם כולא חד<sup data-n=\"373\">57</sup>. ועפ\"ז יש לומר, דבחינת המאור דהנשמה שמתגלית ע\"י מס\"נ היא עצם הנשמה כמו שהיא מוגדרת בענין הפשיטות שלמעלה מציור דכחות, ובחינת המאור דהנשמה שמתגלית ע\"י הענין דכתית מזה שנמצאים בגלות, הוא גילוי עצם הנשמה כמו שהיא מושרשת בהעצמות.\nיא) <b>ויש</b> לקשר זה עם המבואר בהמאמר<sup data-n=\"374\">58</sup> בפי' הכתוב ואתה תצוה את בני ישראל ויקחו אליך שמן זית גו', דלאחרי שמשה יצַוה ויקשר את בני ישראל אזי יביאו ישראל למשה שמן זית גו', שישראל ע\"י עבודתם יוסיפו גילוי אור במדריגת משה. ויש לומר מהביאורים בזה בעבודת האדם, דזה שמשה מצוה ומקשר את בני ישראל, הוא, שהוא זן ומפרנס את האמונה, שהאמונה תהי' נוסף על כמו שהיא מצד הגילויים דהנשמה (מצד זה שהנשמה שלמעלה רואה אלקות) גם מצד עצם הנשמה. [ויש לומר, דזהו מ\"ש ואתה תצוה את בני ישראל, דלשון ואתה תצוה את בני ישראלמשמע שמשה מצַוה (מקשר ומחבר) את בני ישראל עצמם, כי מצד עצם הנשמה, כל ישראל הם חד<sup data-n=\"375\">59</sup>]. וע\"י העבודה דישראל (לאחרי שנמשך בישראל גילוי עצם הנשמה ע\"י משה), שגם כחות הגלויים שלהם (<i>הציור</i> דהכחות) יהיו מתאימים לעצם הנשמה, עי\"ז נעשה יתרון והוספה בבחינת עצם הנשמה שנמשכה ונתגלתה בהם ע\"י משה (ויקחו אליך), כי עי\"ז מתגלה בה שרשה האמיתי כמו שהיא מושרשת בהעצמות.\n[<b>ולהעיר</b><b>,</b> שעי\"ז ניתוסף גם בהאחדות דישראל. שהאחדות דישראל ע\"י עצם הנשמה שמתגלית בהם היא <i>כמו</i> דבר נוסף על מציאותם. ולכן, אחדות זו היא ע\"י שעושים נפשם עיקר וגופם טפל<sup data-n=\"376\">60</sup>. וע\"י גילוי עצם הנשמה כמו שהיא מושרשת בהעצמות, שעי\"ז גם הציור דכחות הגלויים הוא חד עם העצם, האחדות דישראל היא בכל הענינים שלהם, גם בענינים השייכים להגוף].\n<b>ועפ\"ז</b> יובן מ\"ש בהמאמר<sup data-n=\"377\">61</sup>, דע\"י שישראל מוסיפים (ע\"י עבודתם) במדריגת משה, עי\"ז יהי' נר תמיד, דלכאורה, זה שהנר דהנשמה (נר<sup data-n=\"378\">62</sup> הוי' נשמת אדם<sup data-n=\"379\">63</sup>) הוא תמיד (בשוה, בלי שינוי), הוא ע\"י גילוי עצם הנשמה שנמשך ע\"י משה (ואתה תצוה), דבעצם הנשמה אין שייך שינוי, ובהמאמר אומר שהענין דנר תמיד הוא ע\"י שישראל מוסיפים במדריגת משה, ויקחו אליך. ויש לומר, שבהגילוי דעצם הנשמה בדרך מלמעלה למטה ע\"י ואתה תצוה, יש חילוק בין ערב ובוקר. שעיקר הגילוי שלה הוא כשישנם העלמות והסתרים (ערב) שעי\"ז מתעורר ומתגלה כח המס\"נ, וכמו שנתבאר לעיל (סעיף יו\"ד), שגם אלה שבזמן הגזירה (ערב) עמדו במס\"נ, כשבאו למקום שאפשר לעסוק בתומ\"צ מתוך הרחבה (בוקר), אין ניכר בהם המס\"נ שהי' להם מקודם. ואמיתית הענין דנר תמיד (שאין שייך בו שינוי) הוא ע\"י עבודתם של ישראל שגם כחות הגלויים יהיו חד עם עצם הנשמה, ויקחו אליך.\n<b>ועפ\"ז</b> יש לבאר זה שכתית למאור נאמר בכתוב בהמשך לויקחו אליך גו', כי בכתית למאור נכלל גם זה שישראל הם שבורים ונדכאים (כתית) מזה שהם בגלות, דענין זה הוא ע\"י עבודתם של ישראל שגם כחות הגלויים שלהם יהיו מתאימים לעצם הנשמה, ובחי' המאור דהנשמה שמתגלית עי\"ז היא עצם הנשמה כמו שהיא מושרשת בהעצמות, ולכן נאמר כתית למאור בהמשך לויקחו אליך גו'.\nיב) <b>והנה</b> הפירוש (בפשטות) בואתה תצוה את בני ישראל ויקחו אליך גו' הוא שמשה יצַוה את בני ישראל שיקחו אליך גו'. ומזה מובן גם בפנימיות הענינים, דזה שמשה מצוה ומקשר את בני ישראל הוא באופן שממשיך להם נתינת כח גם על ויקחו אליך גו'. וכמו\"כ הוא בנוגע למשה שבדורנו, כ\"ק מו\"ח אדמו\"רנשיא דורנו, שעבודתו לעורר ולגלות את האמונה שבכל אחד מישראל שמצד עצם הנשמה היא באופן שאח\"כ יעבדו עבודתם בכח עצמם, ועד שיהיו נר תמיד שאין שייך בו שינוי גם מצד כחות הגלויים.\n<b>ועי\"ז</b> זוכים בקרוב ממש לגאולה האמיתית והשלימה, שאז יהי' גילוי אלקות גם מצד המטה. ויהי' אז הבאת השמן והדלקת הנרות (ויקחו אליך שמן גו' להעלות נר תמיד) גם בגשמיות, בבית המקדש השלישי, בגאולה האמיתית והשלימה ע\"י משיח צדקנו, בקרוב ממש.\n**********",[["316","*","יצא לאור ב<b>קונטרס</b>*<b> פורים-קטן – תשנ\"ב</b>**, \"לקראת יום ג' שהוכפל בו כי טוב, פורים קטן . . <i>יום א' פ' כי תשא</i>,<i> ה'תשנ\"ב</i>\"."],["317","1","ריש פרשתנו (תצוה)."],["318","2","אוה\"ת פרשתנו (תצוה) ע' א'תקמא. ד\"ה וקבל היהודים תרפ\"ז ס\"ג (סה\"מ תרפ\"ז ע' קיג. ה'תשי\"א ע' 182)."],["319","3","רמב\"ן עה\"פ."],["320","4","פרשתנו כז, כא."],["321","5","השייכות דהביאור בואתה תצוה גו' לוקבל היהודים גו' – ראה לקמן ס\"ט ואילך."],["322","6","נדפס ב\"התמים\" חוברת ז לה, ג [שלו, ג] ואילך. סה\"מ תרפ\"ז ע' קי ואילך. ה'תשי\"א ע' 180 ואילך. – ראה שם ס\"ד."],["323","7","כ\"ה גם ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370366\" data-slug=\"torah-or\" data-id=\"3901370366\">תו\"א פרשתנו פב, א</a> (עה\"פ ואתה תצוה). ובכ\"מ. וראה בהנסמן לקמן ע' נט הערה 55."],["324","8","כ\"ה בסד\"ה ואתה תצוה עטר\"ת (סה\"מ עטר\"ת ע' רנו). ובכ\"מ. ובד\"ה זה תרפ\"ז ס\"ד בתחלתו (ועד\"ז רסט\"ו) \"תקשר את בני ישראל\" <i>ואינו</i> מוסיף \"עם אוא\"ס\". ויש לומר, דבהמאמר מפרש שמשה מקשר את בני ישראל עצמם, כדלקמן סי\"א."],["325","9","בהעלותך יא, כא.\n*) <i>קונטרס זה חילק כ\"ק אדמו\"ר שליט\"א בידו הק' לכאו\"א מאנשים נשים וטף</i>.\n**) <i>על הדו\"ח אודות הדפסת והפצת המאמר ענה כ\"ק אדמו\"ר שליט\"א</i>: \"ויה\"ר שיפעל הפעולה הרצוי' והזמ\"ג וברי מזלי' כו'. אזכיר עה\"צ\"."],["326","10","ראה בכ\"ז בד\"ה הנ\"ל תרפ\"ז ס\"ה."],["327","11","סעיף ד."],["328","12","שבת צז, א."],["329","13","ח\"ג רכה, ב."],["330","14","תקו\"ז תס\"ט (קיב, א. קיד, א)."],["331","15","ראה בד\"ה הנ\"ל תרפ\"ז ס\"ג וסט\"ו."],["332","16","אסת\"ר פ\"ו, ב."],["333","17","בד\"ה הנ\"ל תרפ\"ז סט\"ו."],["334","18","אסתר ט, כג."],["335","19","כ\"ה גם ברד\"ה וקבל היהודים ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370432\" data-slug=\"torah-or\" data-id=\"3901370432\">תו\"א מג\"א צו, ג</a>. ובכ\"מ – נסמנו ברד\"ה וקבל היהודים ה'תשי\"א (לקמן ע' נד הערה 4)."],["336","20","שבת פח, א."],["337","21","אסתר ט, כז."],["338","22","מהמשך הענינים בהמאמר וב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370442\" data-slug=\"torah-or\" data-id=\"3901370442\">תו\"א</a> שבהערה הבאה (וראה גם תו\"א שם צט, רע\"א. ובכ\"מ) משמע, דזה שקבלוה בימי אחשורוש הוא בזמן הגזירה. ובפרש\"י ד\"ה בימי אחשורוש \"מאהבת <i>הנס</i> שנעשה להם\". ואולי יש לומר דשני ענינים בזה – ראה לקמן ס\"ט."],["339","23","כ\"ה גם ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370438\" data-slug=\"torah-or\" data-id=\"3901370438\">תו\"א מג\"א צח, א</a> דוקבל היהודים את אשר החלו לעשות הוא ע\"ד \"קיימו מה שקבלו\" – אף שלכאורה הם שני ענינים שונים, ראה לקמן ע' נד הערה 4."],["340","24","הביאור בדיוק לשון זה – ראה ד\"ה וקבל היהודים דפורים קטן ה'תשל\"ח ס\"א (לקמן ע' מד)."],["341","25","ראה ב\"ר פט\"ז, ה \"כל המלכיות נקראו על שם מצרים על שם שהם מצירות לישראל\"."],["342","26","וארא ו, ט."],["343","27","מג\"א צא, ב. צז, א. צט, ב. וראה גם במקומות שנסמנו לקמן ריש ע' נה הערה 12."],["344","28","שזהו חידוש גדול יותר, כי בנוגע לאמונה, גם קל שבקלים מוסר נפשו (תניא פי\"ח. ובכ\"מ)."],["345","29","שזהו חידוש גדול עוד יותר, כמובן בפשטות."],["346","30","ראה הערות הקודמות."],["347","31","ראה המשך תער\"ב ח\"א פס\"א (ע' קיד). וראה גם המשך הנ\"ל ח\"ב ע' א'קפב \"האמונה כו' משום דמזלי' חזי, דהנשמה כמו שהיא למעלה היא רואה כו', וכן ענין האמונה שמצד עצם הנשמה\"."],["348","32","לשון הגמרא – מגילה ג, א."],["349","33","שלכן \"אין עד נעשה דיין\" (ר\"ה כו, א). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061132\" data-slug=\"likkutei-sichot\" data-id=\"1300061132\">לקו\"ש ח\"ו ע' 121</a>. וש\"נ."],["350","34","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370335\" data-slug=\"torah-or\" data-id=\"3901370335\">תו\"א משפטים עה, ב</a>. ובכ\"מ. וראה גם תניא רפמ\"ב."],["351","35","סעיף יא."],["352","36","משא\"כ בתניא שם \"יורדין ניצוצין מנשמת מרע\"ה כו' <i>ללמד דעת</i> את העם\"."],["353","37","ראה לקמן הערה 56."],["354","38","סעיף ג."],["355","39","ראה ויק\"ר פ\"ט, א. במדב\"ר פי\"ט, ג. וש\"נ."],["356","40","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061293\" data-slug=\"likkutei-sichot\" data-id=\"1300061293\">ע\"ד</a> הפירוש בלשון המשנה (אבות רפ\"ג) \"דין וחשבון\" (דין ואח\"כ חשבון) – ע\"פ דברי המשנה (שם מט\"ז) ש\"נפרעין ממנו מדעתו ושלא מדעתו\", שלאחרי שהאדם פוסק מדעתו דינו של חבירו, פוסק דין לעצמו שלא מדעתו, כיון שע\"פ \"דין\" זה עושים \"חשבון\" בנוגע למצבו הוא (ראה לקו\"ש ח\"ו ע' 283. וש\"נ)."],["357","41","להעיר, דבפנים המאמר (סט\"ו) מובא (רק) \"זמן הגלות\", ובה\"קיצור\" – \"זמן הגלות והגזירה\"."],["358","42","אסתר ח, טז."],["359","43","ראה מגילה טז, ב."],["360","44","אסתר ח, א."],["361","45","מגילה יד, א."],["362","46","ראה ירושלמי יומא פ\"א ה\"א (ד, ב). מדרש תהלים עה\"פ קלז, ז."],["363","47","להעיר מהידוע ש\"לפני . . רשב\"י לא נחרב הבית כלל\" (פלח הרמון שמות ע' ז בשם אדה\"ז)."],["364","48","מאמרי אדה\"ז הקצרים ע' תג."],["365","49","כ\"ה במאמרי אדה\"ז הקצרים שם. וראה זהר חדש ס\"פ נח (כג, ד): דאי יחזרון בתשובה רישי כנישתא או חדא כנישתא יתכנש כל גלותא."],["366","50","טעהמ\"צ להאריז\"ל פ' וירא. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381116\" data-slug=\"likkutei-torah\" data-id=\"4001381116\">לקו\"ת ברכה צז, ב</a>. המשך וככה תרל\"ז פס\"ג (ע' צט)."],["367","51","הובא בשרש מצות התפלה להצ\"צ פ\"מ (קלח, סע\"א)."],["368","52","שבת פח, א."],["369","53","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370441\" data-slug=\"torah-or\" data-id=\"3901370441\">תו\"א מג\"א צח, ד</a> ואילך. ובכ\"מ. וראה גם בד\"ה הנ\"ל תרפ\"ז סוס\"ב."],["370","54","להעיר גם מהמשך תער\"ב ח\"ב ע' תתקצו."],["371","55","וראה ד\"ה בלילה ההוא ה'תשכ\"ה ס\"ח, ובהערה 49 שם (לקמן ע' עח)."],["372","56","ועד\"ז הוא בנוגע להמשכת האמונה בפנימיות (בדעת), דזה שהאמונה פועלת על הדעת הוא יתרון ועילוי לגבי ענין המס\"נ.\nויש לומר, דהמשכת האמונה בדעת, זה שנמשך בגילוי היא האמונה שמצד מזלי' חזי (מקיף דחי'*), אלא שהחיבור דהאמונה שלמעלה מדעת עם הדעת הוא ע\"י המשכת עצם הנשמה [היינו שהגילוי דעצם הנשמה הוא רק נתינת כח לבחי' האמונה שמצד המקיף דחי' שתתחבר עם הדעת, ולא שמתגלית עצם הנשמה עצמה].\nמשא\"כ זה שגילוי אלקות נוגע לעצם מציאותו, שלכן הוא נשבר ונדכא מזה שבזמן הגלות לא יש גילוי אלקות (ראה לעיל ס\"ט) – הרי הגילוי דהתקשרות העצמית שמצד עצם הנשמה שמתגלית בזה שגילוי אלקות נוגע <i>לעצם מציאותו</i> הוא [נוסף על אופן דנתינת כח, גם] שהתקשרות העצמית עצמה מאירה בגילוי (<i>בדוגמת</i> הגילוי שלה בענין המס\"נ), וגם גילוי זה (דעצם הנשמה עצמה) מתחבר עם הציור דכחות הגלויים."],["373","57","ראה גם לקמן ח\"ד ע' רנד."],["374","58","סעיף ד – הובא לעיל ס\"ב.\n*) <i>ראה סה\"מ עת\"ר ס\"ע קנד</i>.<i> ובכ\"מ</i>."],["375","59","וראה המשך תער\"ב ח\"א פס\"א, שבראי' ישנם חילוקי דרגות, וזה שהאמונה היא בכל ישראל בשוה הוא לפי ששרשה הוא התקשרות העצמית שמצד עצם הנשמה (שלמעלה ממזלי' חזי)."],["376","60","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310037\" data-slug=\"tanya\" data-id=\"3401310037\">תניא פרק לב</a>."],["377","61","סעיף ד."],["378","62","משלי כ, כז."],["379","63","ראה בהמאמר סט\"ו."]]],[1500380009,"<h3>בס\"ד. יום ג', פורים קטן ה'תשל\"ח<sup data-n=\"380\">*</sup>.</h3>\n<b>וקבל</b> היהודים את אשר החלו לעשות<sup data-n=\"381\">1</sup>, ומבאר בזה כ\"ק מו\"ח אדמו\"ר נשיא דורנו במאמרו הידוע<sup data-n=\"382\">2</sup> שאמרו בפורים קטן (תרפ\"ז) במוסקבא [אשר שנה זו היא התחלת יובל<sup data-n=\"383\">3</sup> השני<sup data-n=\"384\">4</sup> לאמירתו] דעתה בזמן הגלות הם קבלו מה שהחלו כבר בזמן דמתן תורה. וכמאמרם ז\"ל<sup data-n=\"385\">5</sup> על פסוק<sup data-n=\"386\">6</sup> קיימו וקבלו היהודים וכו', דקיימו עתה (בימי אחשורוש) מה שקבלו כבר בזמן דמ\"ת. ומדייק בזה בהמאמר, דלכאורה הוא דבר נפלא [ומדייק בשאלתו שזהו ענין \"נפלא\" (ולא כלשון הרגיל ברוב המאמרים – \"צלה\"ב\") כי הענין (דקבלו בזמן הגלות מה שהחלו בזמן מ\"ת) הוא בבחי' נפלא. וכמבואר<sup data-n=\"387\">7</sup> בענין לא נפלאת גו' ולא רחוקה<sup data-n=\"388\">8</sup>, דריחוק וקירוב הוא בערך זל\"ז, אבל נפלא מורה על ענין של הפלאה והבדלה ועד שהוא בבחי' פלא לגבי', והיינו שהוא ענין שבאין ערוך לגמרי. וכידוע<sup data-n=\"389\">9</sup> (בענין הספירות) שבחי' פלא הוא בחי' הכתר, ובפרטיות בחי' פנימיות הכתר, שזהו באי\"ע לגמרי לכל סדר ההשתלשלות. ומזה יובן גם בנוגע לענין הנפלא המובא בהמאמר], דבמתן תורה (כאשר החלו לעשות) היו ישראל בתכלית העילוי ובמעמד ומצב משובח, והי' אז לאחרי קריעת ים סוף ויציאת מצרים, שהם ענינים וואָס האָבן אַוועקגעשטעלט את כאו\"א מישראל ואת כללות עם ישראל במעמד נעלה ביותר, דביצי\"מ נגלה עליהם ממה\"מ הקב\"ה בכבודו ובעצמו וגאלם, ובשעת קרי\"ס [שהוא הסיום וחותם דיצי\"מ<sup data-n=\"390\">10</sup>] ראתה שפחה על הים מה שלא ראו נביאים<sup data-n=\"391\">11</sup>, ועאכו\"כ תכלית העילוי דבנ\"י בזמן מ\"ת, דמ\"ת הי' רק פעם אחת וכידוע<sup data-n=\"392\">12</sup> שמ\"ת לא יהי' עוד הפעם, וגם מבואר בתניא<sup data-n=\"393\">13</sup> שבשעת מ\"ת כבר הי' מעין תכלית שלימות העולם שיהי' לע\"ל, שהי' גילוי אלקות בראי' חושיית, שמצד גילויים אלו היו ישראל בתכלית המעלה. משא\"כ בזמן הגלות הוא ההיפך מזה ממש, שישראל הם בתחתית הירידה. ובפרט בזמן המן (כאשר הי' וקבל היהודים גו' קיימו גו') שבקש ח\"ו להשמיד להרוג ולאבד את כל היהודים מנער ועד זקן טף ונשיםביום אחד גו'<sup data-n=\"394\">14</sup>, דגזירה זו היתה קשה ביותר שהרי היתה בבת אחת על כל היהודים שבכל העולם, כי אחשורוש מושל בכיפה הי' כדאיתא במדרש<sup data-n=\"395\">15</sup>, ולא הי' ביכולת להמלט למקום שכבר הי' אחר הגזירה כיון שהיתה ביום אחד (בכל העולם), שזהו (בגלות גופא) גלות הכי נורא.\n<b>ומבאר</b> בהמאמר שם שתוקף (הגזירה ו)הגלות ברוחניות הי' הגזירה על ענין החינוך. וכדאיתא במדרש<sup data-n=\"396\">16</sup> אמר (המן) אין אני שולח ידי תחלה אלא באלו התינוקות. והיינו דבכדי להפיק ח\"ו זממו ומחשבתו הרעה אשר חשב על היהודים רח\"ל לאבדם<sup data-n=\"397\">17</sup>, הנה ההתחלה היא מאלו התינוקות של בית רבן. דהכוונה בזה היא הגזירה על כללות ענין החינוך, וי\"ל שאף שבהנ\"ל תשב\"ר קאי על תינוק בשנים אבל מעין זה הוא גם בתינוק בעניני יהדות, הגם שהוא איש גדול בשנים ובלשון כ\"ק מו\"ח אדמו\"ר ער האָט שוין ווייסע האָר, מ\"מ במצבו בעניני תומ\"צ הוא בבחי' תינוק. [ומזה גופא (שבהחינוך תלוי קיומו של עם ישראל) מובן גודל המס\"נ שצ\"ל על חינוך בנ\"י. שצריך למסור נפשו בכדי שיהי' אל תגעו במשיחי<sup data-n=\"398\">18</sup> אלו תינוקות של בית רבן כדאיתא במסכת שבת<sup data-n=\"399\">19</sup>, אשר זה נעשה ע\"י שמכניסים את התינוקות אל מקומם הראוי, אל בית רבן, ושם גופא אופן החינוך הוא באופן של \"בית (רבן)\" וקבע, היינו שהתינוקות יקבלו מרבן היסוד (דעם גאַנצן שטעל) על כל ימי חייהם].\n<b>ואחר</b> כ\"ז, הנה במ\"ת הי' רק \"החלו לעשות\", ענין של התחלה בלבד, והקיום (דהתורה דמ\"ת), קיימו וקבלו, הי' דוקא בזמן הגלות, ובפרט בזמן המן כשישראל היו בתכלית השפלות דגלות בגשמיות ורוחניות, שזהו ענין נפלא ביותר.\nב) <b>ויובן</b> זה (כמבואר בהמאמר<sup data-n=\"400\">20</sup>) ע\"פ הביאור במ\"ש<sup data-n=\"401\">21</sup> שמן גו' כתית למאור, שמדייק שם<sup data-n=\"402\">22</sup> שלא נאמר שמן להאיר כ\"א שמן גו' למאור, ומבאר בזה<sup data-n=\"403\">23</sup> דמאור קאי על המאור עצמו, היינו מקור האור. וזהו מ\"ש כתית למאור, שכאשר האדם הוא בבחי' כתית, שנשבר ונדכא, הנה אז מגיע למאור. וזה שנשבר ונדכא הוא גם כאשר בגשמיות הוא במצב של הרחבה הכי גדולה אלא שמ\"מ חסר ברוחניות, בעבודתו, ויתירה מזו, דאפילו אם גם ברוחניות הוא שלם בקיום התומ\"צ, ועד שהוא בתכלית העילוי וההרחבה שעובד עבודתו כדבעי לי' למיעבד<sup data-n=\"404\">24</sup>, מ\"מ כשיתבונן דועמךכולם צדיקים<sup data-n=\"405\">25</sup>, וכאו\"א מישראל הוא נצר מטעי מעשה ידי להתפאר (מטעיו ומעשה ידיו של הקב\"ה ושבהם הוא מתפאר), ויתבונן בגדולתו של הקב\"ה, הנה בכה יבכה במר נפשו, כי במה נחשבת כל עבודתו (גם אם היא בשלימות) לגבי ערכו ומדרגתו האמיתי שצ\"ל נצר מטעיו ומעשה ידיו להתפאר של הקב\"ה בגלוי עד שכל רואהו יכיר זה, וא\"כ גם שלימות עבודתו אינה כדבעי למהוי כלל, והרי אפילו מאן דמחוה במחוג קמי מלכא הרי זה היפך החיות והמציאות<sup data-n=\"406\">26</sup>, ועאכו\"כ כשעבודתו אינה כדבעי, שאינה בערך למה שהי' צ\"ל לפי\"ע הכחות שנתנו לו. והנה כשיתבונן בגודל ירידתו ויבכה במר נפשו, יבא לידי תשובה, ועד שיגיע להיות והרוח תשוב אל האלקים אשר נתנה<sup data-n=\"407\">27</sup> ולמעלה יותר, שתשוב הנפש במס\"נ למקורה ושרשה העליון שממנה לוקחה כו'<sup data-n=\"408\">28</sup>. וזהו מ\"ש כתית למאור, שעי\"ז שהאדם נשבר ונדכא, בבחי' כתית [מתוך הרחבה בגשמיות ומתוך הרחבה ברוחניות, כנ\"ל], הנה אז מגיע למאור עצמו, לבחי' האלקים אשר נתנה כו'.\nג) <b>והנה</b> עבודה הנ\"ל להיות בביטול בתכלית בבחי' כתית פועלת אח\"כ גם בהמעשה בפועל. והענין הוא, כמו שמבאר כ\"ק אדמו\"ר הזקן בתו\"א<sup data-n=\"409\">29</sup> שהיהודים מסרו עצמן למות כל השנה כולה ולא עלה להם מחשבת חוץ ח\"ו, דהפירוש בזה הוא שעמדו במס\"נ בכל אופני שינויים שהיו, דזהו שנה לשון שינוי<sup data-n=\"410\">30</sup> כי השנה כוללת בתוכה כל השינויים האפשריים<sup data-n=\"411\">31</sup>. וע\"ד הידוע<sup data-n=\"412\">32</sup> במעלת האתרוג שדר באילנו משנה לשנה<sup data-n=\"413\">33</sup> שסובל ע\"ע כל שינויי האוירים מד' תקופות השנה ואינו מתפעל מזה כלל ודר באילנו [שחיותו ומקום דירתו הוא באילנו, בשרשו ומקורו], ולא זה בלבד שאינו מתפעל מהשינויים אלא עוד זאת שגדל מהשינויים, כמבואר בהמשך וככה<sup data-n=\"414\">34</sup>, הנה עד\"ז הוא בעבודת האדם, דבכל אופני שינויי הדרגות שבעבודה, כל השנה כולה, עבודתו היא בתכלית השלימות, שלא עולה מחשבת חוץ ח\"ו. ולזה מגיע דוקא כשהוא בתכלית הביטול בבחי' כתית, כי מכיון שיש אופני עבודה חלוקים מן הקצה אל הקצה כמו חסד וגבורה, לכן גם אם עבודתו בקו החסד היא כדבעי אפשר שיקשה עליו שעבודתו בקו הגבורה תהי' ג\"כ באותה השלימות [ע\"ד שאפילו בנוגע אאע\"ה, כיון שעבודתו היתה בבחי' החסד<sup data-n=\"415\">35</sup>, אברהם אוהבי<sup data-n=\"416\">36</sup>, נאמר עליו<sup data-n=\"417\">37</sup> <i>עתה</i>ידעתי כי ירא אלקים אתה, לאחר שעמד גם בנסיון העשירי<sup data-n=\"418\">38</sup>], וע\"י הביטול דכתית הנה שלימות עבודתו היא בלי שינויים בכל חילוקי אופני העבודה<sup data-n=\"419\">39</sup>.\nד) <b>והנה</b><b>,</b> עוד זאת מפעולות ביטול הנ\"ל, דזה שמכיר שהוא בתכלית הירידה וכו' פועל עליו שגם אם עבודתו היא כדבעי מ\"מ יחנך א\"ע דוגמת החינוך דתשב\"ר כפשוטו, כי הוא מרגיש עצמו בבחי' תינוק בעבודתו (וכנ\"ל דבמה נחשב הוא לגבי אמיתיות ערכו). וענין החינוך צ\"ל במס\"נ (כנ\"ל), וכמו שמבאר בהמאמר הנ\"ל<sup data-n=\"420\">40</sup> המס\"נ שהי' בזה בזמן מרדכי, והרי התורה היא נצחית<sup data-n=\"421\">41</sup>, שבזה ישנה הוראה [תורה מלשון הוראה, כדאיתא בזהר<sup data-n=\"422\">42</sup>] נצחית לכאו\"א בכל זמן ובכל מקום, שצריך למסור נפשו על ענין החינוך, הן על חינוך עצמו, כמאמר המשנה<sup data-n=\"423\">43</sup> איזהו חכם הלומד מכל אדם, דחינוך זה צ\"ל בכל יום ויום במשך כל ימי חייו, שהרי בכל יום צריך לעלות בעבודתו כמאמר<sup data-n=\"424\">44</sup> מעלין בקודש, שגם כשהוא בבחי' קודש, דקודש מלה בגרמי'<sup data-n=\"425\">45</sup> הוא בחי' החכמה<sup data-n=\"426\">46</sup> [שהוא בדרגת חכם כי אתמול כבר למד מכל אדם], הנה גם אז צ\"ל עלי', שבהגיע יום חדש יהי' עביד <i>עבידתי'</i><sup data-n=\"425\">45</sup> ויוסיף ללמוד מכל אדם ויתעלה בדרגת החכמה שלו, היינו שבכל יום ויום צ\"ל חינוך עצמו. וכן מובן גם מתורת הבעש\"ט הידועה<sup data-n=\"427\">47</sup> שבכל ענין שיהודי רואה או שומע צריך לראות ולשמוע (דערזעהן און דערהערן) ההוראה שבזה בעבודתו לקונו, היינו שבכל ענין שרואה או שומע צריך לחנך את עצמו. ועאכו\"כ שצריך למסור נפשו על ענין החינוך דתשב\"ר כפשוטו. ובמיוחד יש בזה חוב על הצעירים והצעירות כמו שמוסיף כ\"ק מו\"ח אדמו\"ר במכתבו בקשר למאמרו הנ\"ל<sup data-n=\"428\">48</sup> דהעת אומרת, אשר כל אחד ואחד מהצעירים והצעירות יחיו, הנה לא זו בלבד שהם בעצמם בחייהם הפרטים, צריכים להיות איתן וחזק בשמירת קיום המצוות מעשיות בכל הידורן כו' [ועי\"ז להיות דוגמא חי'] אלא עוד זאת [וגם זה עיקר] לעשות סביבה של לומדי תורה ושומרי מצוה, ועד שיראו אצלם בגלוי שהם נצר מטעי מעשה ידי להתפאר. ובכללות, חובה זו היא על כאו\"א, דהרי כאו\"א הוא בכלל דצעירים וצעירות כשנזכר שבכל יום ויום נעשה כברי' חדשה<sup data-n=\"429\">49</sup>.<b>והנה</b> ע\"י החינוך דתשב\"ר נעשה מפי עוללים ויונקים יסדת עוז גו' להשבית אויב ומתנקם<sup data-n=\"430\">50</sup>, וכמו שמבאר בהמאמר הנ\"ל<sup data-n=\"431\">51</sup> דהאויב הוא שונא הגלוי, והנוקם הוא שונא נסתר ועולל עלילות כו' [ובעבודה הו\"ע מה שאמר יעקב<sup data-n=\"432\">52</sup> אשר לקחתי מיד האמורי בחרבי ובקשתי, דההפרש בין חרב לקשת הוא שהחרב הורג את השונא שעומד אצלו בקרוב, והקשת יכול להרוג גם את השונא שעומד מרחוק<sup data-n=\"433\">53</sup>, דהשונא הקרוב קאי על (גסות) הרע שהאדם יודע ומבין שהוא רע, והשונא שעומד מרחוק הוא דקות הרע שאינו יודע ממנו כו'. והעברת האויב ומתנקם הוא ע\"י העבודה דחרבי וקשתי, כמבואר בהמאמרים<sup data-n=\"434\">54</sup> בענין החמשה כלי זיין המנויים במשנה דשבת<sup data-n=\"435\">55</sup>].\nה) <b>והנה</b> הכח לעבודה הנ\"ל הוא ע\"י משה רבינו. כמבואר בהמאמר הנ\"ל<sup data-n=\"436\">56</sup> דזהו מ\"ש ואתה תצוה את בני ישראל גו', דתצוה הוא לשון צוותא וחיבור, ואתה קאי (בפשש\"מ) על משה, ואתפשטותא דמשה בכל דרא ודרא, שבכל א' מישראל ישנו מבחי' משה כדאיתא בתיקוני זהר<sup data-n=\"437\">57</sup> והובא באגרת הקודש לכ\"ק אדמו\"ר הזקן<sup data-n=\"438\">58</sup>, ובכל א' הנה בחי' משה שבו היא בגלוי עד שמשו\"ז יראה מילתא זוטרתי היא<sup data-n=\"439\">59</sup> לגבי' כדאיתא בתניא חלק ראשון<sup data-n=\"440\">60</sup>, ובחינת משה שבכל אחד מישראל מחברת באופן דצוותא וחיבור (תצוה) את<sup data-n=\"441\">61</sup> שרש הנשמה<sup data-n=\"442\">62</sup> להנשמה המלובשת בגוף ועם נה\"ב וגופו וחלקו בעולם, ונותנת כח שיהי' כתית למאור, שמזה שנדכא ונשבר מצד ירידת הנשמה לעוה\"ז התחתון שאין תחתון למטה ממנו<sup data-n=\"443\">63</sup>, שזהו ירידה עצומה, כי אפילו כשעוה\"ז הוא בתכלית השלימות נקרא בירא עמיקתא<sup data-n=\"444\">64</sup>, דמזה מובן שעצם הדבר שהנשמה ירדה לעוה\"ז הוא ירידה גדולה. ומצד הירידה, אף שהוא במצב של תכלית ההרחבה בגשמיות וגם ברוחניות מ\"מ במה נחשב הוא לגבי מעמדו ומצבו האמיתי (שלפני הירידה) שהוא בבחי' בנו<sup data-n=\"445\">65</sup> יחידו של ממה\"מ הקב\"ה (כידוע המשלבזה בהמשך תרס\"ו<sup data-n=\"446\">66</sup>), הנה מהכתית (שנשבר ונדכא) נעשה למאור שמגיע להמאור עצמו כנ\"ל.\nו) <b>וע\"פ</b> הנ\"ל יובן מ\"ש וקבל היהודים את אשר החלו לעשות, דהגם שבשעת מ\"ת היו ישראל בתכלית המעלה (ואז כבר ניתן הכל, כנ\"ל), מ\"מ הי' אז רק החלו לעשות, התחלה בלבד, כי זה הי' רק מלמעלה למטה. ואח\"כ בהעבודה שבזמן הגלות, בזמן מרדכי ואסתר, כאשר הוא תוקף הגלות בחושך כפול ומכופל (וכמו שהי' בפשטות) הנה אז העבודה היא מצד התחתונים, וקבל היהודים, שזה לא הי' בשעת מ\"ת. ועוד זאת, שבהעבודה שבזמן הגלות ישנו עילוי לגבי שעת מ\"ת, שדוקא אז נעשה הקיום בהתורה שקבלו במ\"ת שהיא בבחי' החלו לעשות בלבד, כי דוקא בזמן הגלות [כפשוטו, וכן בדקות הענינים, כשמתבונן (ע\"ד הנ\"ל) שגם לאחר כל הענינים שפעל בעבודתו, אפילו כשהם בתכלית השלימות, מ\"מ עדיין הוא בבחי' גלות (ברוחניות), כי מכיון שהקב\"ה עוזרו<sup data-n=\"447\">67</sup> ביכולתו הוא להגיע לדרגא נעלית יותר ועד לאין ערוך, ע\"ד לשון חז\"ל<sup data-n=\"448\">68</sup> (יגעת) ומצאת שהמציאה היא שלא בערך יגיעתו והשתדלותו<sup data-n=\"449\">69</sup>] דאז הנה כאו\"א נשבר ונדכא, הנה אז מגיעים למאור עצמו.\nז) <b>ויש</b> לקשר מה שנת\"ל בגודל העילוי שבעבודת התחתונים, שע\"י דוקא נעשה הקיום דמה שהחלו לעשות, עם פרשת השבוע [ובזה גופא עם השיעור דהיום דיום השלישי [שענינו הוא שהוכפל בו כי טוב<sup data-n=\"450\">70</sup>, טוב לשמים וטוב לבריות<sup data-n=\"451\">71</sup>] – ע\"פ תקנת כ\"ק מו\"ח אדמו\"ר ללמוד בכל יום מימות השבוע פרשה אחת בפרשת השבוע] ע\"פ המבואר בהמאמרים<sup data-n=\"452\">72</sup> ובפרט במאמר כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע שלפני ששים שנה<sup data-n=\"453\">73</sup> בפרשתנו עה\"פ<sup data-n=\"454\">74</sup> ועתה אם נא מצאתי חן בעיניך גו' למען אמצא חן בעיניך גו' כי מצאתי חן בעיניך גו' כי מצאת חן בעיני [דעי\"ז יהי' ונפלינו אני ועמך מכל העם אשר על פני האדמה (דונפלינו הוא כענין נפלא שנת\"ל)] דצריך להבין מהי המעלה בענין החן שמשה רבינו ביקש והפציר כ\"כ ע\"ז ועד שזה הי' תכלית השלימות דבקשתו, וע\"י החן יהי' אח\"כ ונפלינו אני ועמך, דהלא כתיב<sup data-n=\"455\">75</sup> שקר החן גו', והוא מפני שהחן הוא בחי' אתעדל\"ע מצ\"ע, ויש יתרון גדול במה שבא באתעדל\"ת. ומבאר שם בזה דישנה בחי' אתעדל\"ע הנמשך לאחר האתעדל\"ת שזהו המשכה מבחי' עצמות א\"ס שאין אתעדל\"ת מגעת לשם כלל והוא רק בבחי' מתנה (והוא הנק' מתנת חנם שהוא לשון חן כו') רק שזה נמשך לאחרי שלימותהאתעדל\"ת, וכמו גבי מתנה דאמרז\"ל<sup data-n=\"456\">76</sup> אי לאו דעביד לי' נייחא לנפשי' כו' הגם שהיא בבחי' מתנה.\n<b>והנה</b> העבודה שבזה היא [כמובן ע\"פ המבואר בהמאמר שם<sup data-n=\"457\">77</sup>], דישנו<sup data-n=\"458\">78</sup> ענין האמונה שבבחי' ממכ\"ע אך בבחי' זו שייך שיהי' מעין זה גם בחסידי אוה\"ע ועד שבישראל אפשר שבחי' ממכ\"ע תהי' בבחי' ידיעה. ועיקר האמונה דנש\"י הוא במדריגת סוכ\"ע, דאמונה זו שייכת רק בישראל<sup data-n=\"459\">79</sup>, דזהו מ\"ש<sup data-n=\"460\">80</sup> שמע ישראל ה' אלקינו ה' אחד שזהו\"ע הקבלה והאמונה בבחי' סוכ\"ע ובזה נאמר שמע ישראל דוקא שאמונה זו היא רק בנש\"י [משא\"כ מ\"ש ברוך שם כבוד מלכותו לעולם ועד קאי על ההתבוננות דבחי' ממכ\"ע]<sup data-n=\"461\">81</sup>. וזהו ג\"כ מה דאיתא בזהר<sup data-n=\"462\">82</sup> דהע' דשמע והד' דאחד הן אותיות רבתי וע\"י צירופם נעשה תיבת עד, ומבואר בכ\"מ<sup data-n=\"463\">83</sup> דעל דבר הנגלה אין צריך ואין שייך עדות, ואפילו על מילתא דעביד לאגלויי כו' לא הצריכה התורה עדות<sup data-n=\"464\">84</sup>, כ\"א דוקא על דבר הנעלם לגמרי, בחי' סוכ\"ע. וזהו מ\"ש שמע ישראל וגו' אחד, דקאי על כאו\"א מישראל שהם דוקא העדים המעידים<sup data-n=\"465\">85</sup> דהוי' אחד [עד שבכל מעמד ומצב שיהי' בעבודתו הנה כאו\"א מישראל אומר שמע ישראל, כמבואר בשיחות כ\"ק מו\"ח אדמו\"ר<sup data-n=\"466\">86</sup>], דהח' וד' דאחד מרמזים על ז' רקיעים וארץ וד' רוחות העולם והאל\"ף מרמזת לאלופו של עולם<sup data-n=\"467\">87</sup>, וישראל בעבודתם פועלים להיות אחד, היינו שממשיכים בעולם (בח' וד') את אלופו של עולם (הא'), עד שיתאחדו בדוגמא לתיבת אחד שהא' היא תיבה א' עם הח' וד' (ותוכן התיבה עצמה הו\"ע האחדות), ובאופן כזה שהא' דאלופו של עולם יהי' ראש<sup data-n=\"468\">88</sup> והתחלת התיבה. והנה ע\"י אתעדל\"ת זו דעבודת ישראל בבחי' סוכ\"ע (הוי' אחד), הנה ממשיכים בחי' אתעדל\"ע שלפיערך האתעדל\"ת ואח\"כ נמשך בחי' אתעדל\"ע שלמעלה מבחי' אתעדל\"ע שע\"י אתעדל\"ת. דבחי' אתעדל\"ע הנמשכת על ידי האתעדל\"ת היא בחי' שבערך לסדר ההשתלשלות, וי\"ל דגם על זה קאי מ\"ש<sup data-n=\"469\">89</sup> הנה מלאכי ילך לפניך, אך בקשת משה הי' שיהי' המשכת בחי' אתעדל\"ע שלמעלה מזה שמצ\"ע, ועתה אם נא מצאתי חן בעיניך, ענין החן, עד שיהי' ונפלינו אני ועמך, דקאי (בספירות) על ספירת הכתר, פנימיות הכתר ועד לעצומ\"ה ית'. דהגם דבחי' אתעדל\"ע זו נמשכת מצ\"ע היינו שאין אתעדל\"ת מגיע לשם, מ\"מ הרי קוב\"ה לא שריא אלא באתר שלים<sup data-n=\"470\">90</sup>, דצ\"ל תחלה עבודת התחתונים באתעדל\"ת והמשכת האתעדל\"ע שלפי ערך האתעדל\"ת ואז בהאתר שלים נמשך להיות קוב\"ה שריא כמבואר בלקו\"ת שה\"ש<sup data-n=\"471\">91</sup>.\nח) <b>וזהו</b> מ\"ש וקבל היהודים את אשר החלו לעשות, שע\"י המס\"נ שבזמן הגלות, בימי מרדכי ואסתר, פעלו הקיום בהתורה דמ\"ת, וכן גם בכל שנה ושנה הנה כשהימים האלו נזכרים ונעשים<sup data-n=\"472\">92</sup>, נמשכים כל הענינים כמו שהיו בפעם הראשונה<sup data-n=\"473\">93</sup>. וידועה תורת הבעש\"ט<sup data-n=\"474\">94</sup> דהקורא את המגילה למפרע לא יצא<sup data-n=\"475\">95</sup>, דכשקריאת המגילה היא באופן של למפרע, היינו ענין שהי' בעבר, הנה לא יצא, כי המגילה היא הוראה בעבודת האדם בכל זמן ובכל מקום ולכל אחד ואחת, כולל ההוראה מהנ\"ל, שעומדים במס\"נ, ובמשך כל השנה כולה [באיזה שינויים שיהי'] אינו שייך אצל יהודי שיעלה על דעתו אפילו מחשבת חוץ ח\"ו, ועאכו\"כ דיבור או מעשה. ומס\"נ זו מביאה שיהי' ליהודים היתה אורה ושמחה וששון ויקר<sup data-n=\"476\">96</sup> כפשוטו, מיוסד ובהקדמת אורה זו תורה עד לויקר אלו תפילין<sup data-n=\"477\">97</sup>, דקאי על כללות ענין המצוות, דהרי הוקשה כל התורה כולה לתפילין<sup data-n=\"478\">98</sup>, ומחנכים בזה גם את התשב\"ר, וכדאיתא במדרש&lt;16&gt; דמרדכי שאל אצל ג' תינוקות פסוק לי פסוקיך, וענו אל תירא מפחד פתאום ומשואת רשעים כי תבוא<sup data-n=\"479\">99</sup>, עוצו עצה ותופר דברו דבר ולא יקום כי עמנו א-ל<sup data-n=\"480\">100</sup>, ועד זקנה אני הוא ועד שיבה אני אסבול אני עשיתי ואני אשא ואני אסבול ואמלט<sup data-n=\"481\">101</sup>, כיון ששמע מרדכי כך שחק והי' שמח בשמחה גדולה כו'. וכן תהי' לנו, שכאו\"א יעבוד עבודתו באורה ושמחה וששון ויקר ככל הענינים המפורשים בזה בדרז\"ל, שכוללים כל התורה כולה, ובודאי שהקב\"ה יקיים הבטחתודונתתי גשמיכם בעתם<sup data-n=\"482\">102</sup> וכל הברכות המנויות בפרשה עד שיהי' אורה ושמחה וששון ויקר כפשוטו. ומיסמך גאולה לגאולה<sup data-n=\"483\">103</sup>, מגאולת פורים לגאולה האמיתית והשלימה ע\"י משיח צדקנו. דאף דלפי שעה קלה הנה אכתי עבדי אחשורוש אנן<sup data-n=\"484\">104</sup>, הנה בקרוב ממש ובעגלא דידן יבא משיח צדקנו ויגאלנו ויוליכנו קוממיות לארצנו, במהרה בימינו ממש.\n**********",[["380","*","יצא לאור ב<b>קונטרס פורים-קטן – ה'תשל\"ח</b>, \"<i>עשק\"מ אדר שני ה'תשל\"ח</i>\"."],["381","1","אסתר ט, כג."],["382","2","ד\"ה וקבל היהודים – נדפס בסה\"מ ה'תשי\"א ע' 180 ואילך. ולאח\"ז בסה\"מ תרפ\"ז ע' קי. ועוד. ובקונטרס בפ\"ע."],["383","3","ראה גם ביאור ענין היובל – בשיחת י\"ב תמוז תשל\"ז ס\"כ ואילך."],["384","4","ראה ג\"כ בהשיחה דהתוועדות זו (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211335\" data-slug=\"likkutei-sichot\" data-id=\"1300211335\">לקו\"ש חכ\"א ע' 326</a>). שיחה הנ\"ל. ועוד."],["385","5","שבת פח, א."],["386","6","שם, כז."],["387","7","ד\"ה ועתה אם נא מצאתי גו' תרע\"ח (סה\"מ תרע\"ח ע' רכג). סה\"מ תש\"ג ע' 29. ועוד."],["388","8","נצבים ל, יא."],["389","9","ראה אוה\"ת בראשית לג, א. נצבים ע' א'רלה. תער\"ב ח\"א ע' תנו. ועוד."],["390","10","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071282\" data-slug=\"likkutei-sichot\" data-id=\"1300071282\">לקו\"ש ח\"ג ע' 878</a>. ח\"ז ע' 270."],["391","11","פרש\"י עה\"פ בשלח טו, ב. מכילתא עה\"פ."],["392","12","המשך תרס\"ו ע' כג. תקמו. המשך תער\"ב ח\"א ע' שסו. ד\"ה ויאמר משה תש\"ט פ\"ו. ובכ\"מ."],["393","13","פרק לו (מו, א)."],["394","14","אסתר ג, יג."],["395","15","מגילה יא, סע\"א. אסת\"ר פ\"א, ד."],["396","16","שם פ\"ז, יג (קרוב לסופו). יל\"ש אסתר רמז תתרנז."],["397","17","ראה אסתר ט, כד-כה."],["398","18","דברי הימים-א טז, כב."],["399","19","קיט, ב."],["400","20","וראה ד\"ה זאת תורת הבית תרפ\"ט (סה\"מ קונטרסים ח\"א ע' לט ואילך. סה\"מ תרפ\"ט ע' 162 ואילך)."],["401","21","ר\"פ תצוה."],["402","22","ספ\"ג (ע' 182)."],["403","23","בפט\"ו (ע' 193)."],["404","24","ראה כתובות סז, א."],["405","25","ישעי' ס, כא."],["406","26","חגיגה ה, ב."],["407","27","קהלת יב, ז. וראה לקו\"ת ר\"פ האזינו. ד\"ה מים רבים שנה זו (לעיל ח\"א ע' רמז ואילך)."],["408","28","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381010\" data-slug=\"likkutei-torah\" data-id=\"4001381010\">לקו\"ת שם עא, ד</a>."],["409","29","מג\"א צז, א."],["410","30","עבוה\"ק ח\"ד פי\"ט. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830002\" data-slug=\"or-hatorah-hb\" data-id=\"8158830002\">אוה\"ת</a> מקץ שלח, סע\"ב."],["411","31","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041322\" data-slug=\"likkutei-sichot\" data-id=\"1300041322\">לקו\"ש ח\"ד ע' 1323</a>."],["412","32","סידור רסד, סע\"ד ואילך. המשך וככה תרל\"ז פפ\"ז."],["413","33","סוכה לה, א."],["414","34","הנ\"ל פצ\"ד."],["415","35","ראה אגה\"ק סי\"ג."],["416","36","ישעי' מא, ח."],["417","37","וירא כב, יב."],["418","38","ראה לקו\"ש ח\"ב ע' 378."],["419","39","להעיר מתורת הבעש\"ט (צוואת הריב\"ש בתחילתו. כתר שם טוב סרכ\"ב) עה\"פ שויתי הוי' לנגדי תמיד, שויתי לשון השתוות כל דבר שיארע לו יהי' שוה אצלו. ובד\"ה באתי לגני תשט\"ו (סה\"מ באתי לגני ח\"א ע' 50. תורת מנחם – התוועדויות חי\"ג ס\"ע 210 ואילך): שי\"ל פירוש הפנימי בזה שגם כל המדריגות (בעבודה) צריכין להיות בהשוואה. עיי\"ש."],["420","40","פ\"ג (ע' 182). פט\"ו (ע' 193)."],["421","41","<a class=\"ft-cite\" href=\"#/read/tanya/3401310022\" data-slug=\"tanya\" data-id=\"3401310022\">תניא רפי\"ז</a>."],["422","42","ח\"ג נג, ב."],["423","43","אבות רפ\"ד. וראה ג\"כ ד\"ה איזהו חכם תש\"ב (סה\"מ תש\"ב ע' 123)."],["424","44","ברכות כח, א. וש\"נ."],["425","45","זח\"ג צד, ב."],["426","46","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370184\" data-slug=\"torah-or\" data-id=\"3901370184\">תו\"א מקץ מ, ד</a>. ועוד."],["427","47","כתר שם טוב (הוצאת תשנ\"ט) בהוספות אות רכג ואילך. וש\"נ."],["428","48","נדפס בסה\"מ תשי\"א ע' 215 (ובהוצאת קה\"ת תשכ\"ז, תשל\"ח, נדפס בהוספה להמאמר הנ\"ל [ולאח\"ז באגרות-קודש שלו ח\"ד ע' טז ואילך])."],["429","49","שו\"ע אדה\"ז או\"ח רס\"ד."],["430","50","תהלים ח, ג."],["431","51","פ\"ב (ע' 181)."],["432","52","ויחי מח, כב."],["433","53","ראה ד\"ה לא יצא האיש לכ\"ק אדמו\"ר מהר\"ש (נדפס בקונטרס בפ\"ע [קה\"ת תשט\"ז]) ע' 7 [ולאח\"ז בסה\"מ תרל\"ב ח\"א ע' נז]. סה\"מ תרנ\"ט ע' קנז. תש\"ד ע' 98 ואילך."],["434","54","ד\"ה הנ\"ל שם. סה\"מ תרנ\"ט שם. תש\"ד ע' 100."],["435","55","סג, א."],["436","56","פ\"ג (ע' 183). וראה ג\"כ ד\"ה זאת תורת הבית הנ\"ל פ\"ט ואילך."],["437","57","תקו\"ז תס\"ט (קיב, א. קיד, א)."],["438","58","ביאור לסי' ז\"ך בסופו."],["439","59","ברכות לג, ב."],["440","60","פמ\"ב."],["441","61","וראה ג\"כ <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161351\" data-slug=\"likkutei-sichot\" data-id=\"1300161351\">לקו\"ש חט\"ז ע' 351</a> ד\"אתה תצוה\" היינו הצוותא וחיבור דישראל (המצווים) עם העצמיות דמשה, שהוא המקשר את ישראל בעצמות א\"ס."],["442","62","להעיר מהמבואר בתרע\"ח (ע' רכד) שענין החן (שיתבאר לקמן) באדם הו\"ע עצם הנשמה שלמעלה מהתלבשות (בחי' יפת מראה)."],["443","63","<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו</a>."],["444","64","ראה חגיגה ה, ב."],["445","65","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא פ\"ב</a>. וראה ד\"ה ועתה אם נא גו' תרע\"ח (ע' ריג ואילך – מע\"ח שער דרושי אבי\"ע פ\"ג) ביאור העילוי דבנים אתם לה' אלקיכם."],["446","66","ס\"ע שפ ואילך."],["447","67","ראה סוכה נב, ב. <a class=\"ft-cite\" href=\"#/read/tanya/3401310018\" data-slug=\"tanya\" data-id=\"3401310018\">תניא רפי\"ג</a>."],["448","68","מגילה ו, ב."],["449","69","ראה לקו\"ש ח\"ג ע' 810."],["450","70","פרש\"י בראשית א, ז."],["451","71","קידושין מ, א. וראה אוה\"ת בראשית לג, ב. משפטים ע' א'קנז. ועוד."],["452","72","סה\"מ תש\"ה ע' 51 ואילך."],["453","73","ד\"ה ועתה אם נא מצאתי גו' תרע\"ח (סה\"מ תרע\"ח ע' ריא ואילך)."],["454","74","תשא לג, יג, טז, יז."],["455","75","משלי לא, ל."],["456","76","ראה מגילה כו, ב. גיטין נ, ב. ב\"מ טז, א. ב\"ב קנו, א."],["457","77","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091072\" data-slug=\"likkutei-sichot\" data-id=\"1300091072\">דתרע\"ח (ע' רכ</a> ואילך) דבחי' החן היא בחי' ד\"ע – שזהו, בכללות, בחי' הסובב, כמבואר בד\"ה וקבל הנ\"ל פ\"י.\nוידוע (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091010\" data-slug=\"likkutei-sichot\" data-id=\"1300091010\">לקו\"ש ח\"ט ע' 72</a> ואילך ובהערה 11 שם) שגם בההמשכות שלמעלה מהשתלשלות צ\"ל עבודת האדם עכ\"פ מעין ודוגמא להגילויים שמלמעלה – ומזה מובן בנוגע לבחי' החן שהמשכתה היא ע\"י <i>האמונה</i> (שלמעלה מהשתלשלות הכחות) בבחי' <i>סוכ\"ע</i>."],["458","78","ראה ד\"ה וקבל הנ\"ל פ\"ה ואילך."],["459","79","ולכן נמשך עי\"ז להיות ונפלינו וגו'."],["460","80","ואתחנן ו, ד."],["461","81","ד\"ה הנ\"ל פ\"י. פי\"ב."],["462","82","ח\"ג רלו, ב."],["463","83","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380056\" data-slug=\"likkutei-torah\" data-id=\"4001380056\">לקו\"ת פקודי ד, סע\"א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191001\" data-slug=\"likkutei-sichot\" data-id=\"1300191001\">לקו\"ש חי\"ט ע' 1-190</a>. וש\"נ.\nבלקו\"ת שם מבואר כבפנים – דענין העדות היא בבחי' סוכ\"ע. ומש\"כ בלקו\"ש שם בפרטיות יותר – ג' בחי': דבר הנגלה – ממכ\"ע, מילתא דעבידא לאגלויי – סוכ\"ע, ועדות – עצומ\"ה ית',\nהיינו כי בסוכ\"ע ב' דרגות: סוכ\"ע – סובב <i>ובערך</i> כ\"ע, סובב ומובדל <i>לגמרי</i> מכל עלמין (המשך תער\"ב ח\"ב ע' א'קמח. סה\"מ תשי\"א ע' 56 ואילך. ובכ\"מ) שביחס דרגא הא' ה\"ז נק' עצומ\"ה ית'."],["464","84","ר\"ה כב, ב. וש\"נ."],["465","85","ראה במקומות שנסמנו לעיל הערה 83."],["466","86","סה\"ש קיץ ה'ש\"ת ע' 12."],["467","87","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380174\" data-slug=\"likkutei-torah\" data-id=\"4001380174\">לקו\"ת תזריע כג, ג</a>."],["468","88","ראה שער היחוד והאמונה פי\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380883\" data-slug=\"likkutei-torah\" data-id=\"4001380883\">לקו\"ת תבוא מא, ג</a>. עט\"ר בתחלתו."],["469","89","תשא לב, לד."],["470","90","זח\"ג צ, ב."],["471","91","כג, ד ואילך."],["472","92","אסתר שם, כח."],["473","93","ראה לב דוד (להחיד\"א) פכ\"ט."],["474","94","כתר שם טוב (הוצאת תשנ\"ט) בהוספות אות ק."],["475","95","מגילה רפ\"ב."],["476","96","אסתר ח, טז."],["477","97","מגילה טז, ב."],["478","98","קידושין לה, א."],["479","99","משלי ג, כה."],["480","100","ישעי' ח, י."],["481","101","שם מו, ד."],["482","102","בחוקותי כו, ד."],["483","103","מגילה ו, סע\"ב."],["484","104","שם יד, א."]]],[1500380010,"<h3>[בס\"ד. פורים, ה'תשי\"א<sup data-n=\"485\">*</sup>]</h3>\n<b>וקבל</b> היהודים את אשר כו' ומקשה הרבי דנפלא הדבר כו' ובזמן הגלות כו' ובפרט זמן המן שהייתה הגזרה כו' ואז דוקא קיימו מה שקבלו כבר. ומתרץ שאז היו במסנ\"פ כל השנה. והנה למה נצרך דוקא לעבודה במסנ\"פ כדי לקיים את אשר החלו כבר, יש להקדים ביאור ענין את אשר החלו שקאי על זמן מ\"ת, שהחידוש במ\"ת הי' כידוע נתינת התומ\"צ בגשמיות דוקא, היינו לבטל הגזירה דבני רומי לא ירדו כו', ולכן ניתנו לנשמות בגופים דוקא בחבורם יחד. וגם בתומ\"צ צ\"ל חבור ענין הגשמי שבזה והרוחניות, היינו שעושהו מצוה, וג\"ז רק אחרי הזיכוך בגלות. ולכן גם בקיום התומ\"צ יש כמה אופנים, והראשיים שעושה התומ\"צ במצות אנשים מלומדה בלא חיות או שלא לשמה ע\"מ שיעשוני רב וכיו\"ב שאי\"ז חיות, או פחד אלק' שאי\"ז חיות אלא אדרבה צמצום וכיוץ. ב' שעושה הנ\"ל מפני אהבת הוי' בחיות גדול שזהו מצד נשמתו שמתפשטת ומתגברת, שבכלל זהו עבודה מפני הטבע או הרגל שנעשה טבע או עבודה שע\"פ טו\"ד, ויש גם למע' מן הטו\"ד שאינו מציאות בפ\"ע אלא שרוצה לקיים רצון הבורא. והנה ע\"ד חילוקים אלו ישנם גם בתורה עצמה. תורה כדי לדעת את המעשה, שזהו דוקא התכלית, ובמילא יש בזה הגבלות, הל' חג בחג וכיו\"ב, ודוקא בארבעא מתנינן. לימוד התורה לעצמו אשר אז באהבתה ישגה תמיד מפני <i>מעלתה</i> מצ\"ע עכ\"פ ע\"פ טו\"ד. ולמעלה מכהנ\"ל לשמה באמת לשם התורה, היינו למעלה מטו\"ד, שאז מחבר ג\"כ התורה דמחכ' נפקת לשרשה בקב'. וע\"י מה יוכל להיות זה ג\"כ ע\"י שמראה בעצמו כך שמסנ\"פ. וצ\"ל תמיד התחברות התורה במקורה, דהנה לכאורה אפ\"ל\n**********",[["485","*","המאמר שלפנינו – נעתק מגוכתי\"ק אדמו\"ר שליט\"א, שהתחיל לרשמו בעצמו, ולא סיים רשימתו. המאמר בשלימותו כפי שהוגה ע\"י כ\"ק אדמו\"ר שליט\"א נדפס לקמן ע' נד ואילך."]]],[1500380011,"<h3>בס\"ד. פורים ה'תשי\"א<sup data-n=\"486\">*</sup></h3>\n<b>וקבל</b> היהודים את אשר החלו לעשות<sup data-n=\"487\">1</sup>, ומבאר כ\"ק מו\"ח אדמו\"ר במאמרו ד\"ה זה<sup data-n=\"488\">2</sup> (שיצא לאור עכשיו<sup data-n=\"489\">3</sup>) שקבלו מה שהחלו בהזמן דמתן תורה. דזה שאמרו נעשה ונשמע היתה רק התחלה (החלו לעשות), ובימי אחשורוש (בזמן גזירת המן) היתה הקבלה, וקבל היהודים<sup data-n=\"490\">4</sup>. ומדייק בזה, שלכאורה הוא דבר פלא<sup data-n=\"491\">5</sup>, שהרי במתן תורה היו ישראל בתכלית העילוי, הן בגשמיות שהיו אז במעמד ומצב משובח ביותר בענין החירות<sup data-n=\"492\">6</sup>, והן ברוחניות שהי' אז אצלם גילוי אלקות בדרגא הכי נעלית<sup data-n=\"493\">7</sup>, ובימי אחשורוש היו ישראל בתכלית הירידה, דנוסף לההעלם והסתר שבכל גלות אשר החושך יכסה ארץ<sup data-n=\"494\">8</sup> בריבוי צמצומים והעלמות והסתרים, הנה אז (בזמן גזירת המן) הי' ההעלם וההסתר עוד יותר<sup data-n=\"495\">9</sup>, וגם בגשמיות היו אז בשפל המצב בתכלית, שהיתה הגזירה להשמיד להרוג ולאבד ח\"ו את כל היהודים מנער ועד זקן טף ונשים ביום אחד<sup data-n=\"496\">10</sup>, ואעפ\"כ, בזמן מתן תורה, כשהיו ישראל בתכלית העילוי, היתה רק ההתחלה (החלו לעשות), ובזמן גזירת המן, כשהיו בתכלית השפלות, אז דוקא קבלו מה שהחלו במתן תורה. ומבאר בזה<sup data-n=\"497\">11</sup>, שבזמן הגזירה, הי' קיום התומ\"צ שלהם במס\"נ.[ולהעיר, דבתו\"א<sup data-n=\"498\">12</sup> מבואר, דהמס\"נ שלהם שהיתה אז היא שבאם היו ממירים דתם ח\"ו לא היו עושים להם כלום, כי הגזירה היתה רק על היהודים, ואעפ\"כ לא עלתה על דעתם מחשבת חוץ ח\"ו. ומבאר, שהמס\"נ שלהם היתה (לא רק שלא לכפור ח\"ו, אלא שמסרו נפשם גם) על קיום התומ\"צ<sup data-n=\"499\">13</sup>, ועד שהקהילו קהלות ברבים ללמוד תורה במס\"נ]. והתעוררות המס\"נ שלהם היתה ע\"י מרדכי היהודי, משה שבדורו<sup data-n=\"500\">14</sup>, שהקהיל קהלות ברבים לחזק את אמונתם. ועיקר<sup data-n=\"501\">15</sup> עבודתו של מרדכי היתה בלימוד התורה עם תינוקות של בית רבן, שהם היסוד של כל ישראל [כמבואר בארוכה בהמאמר<sup data-n=\"502\">16</sup> בגודל מעלת הבל תינוקות של בית רבן], כדאיתא במדרש<sup data-n=\"503\">17</sup> שקיבץ מרדכי היהודי כ\"ב אלף תלמידים<sup data-n=\"504\">18</sup> ולימדם תורה במס\"נ, עד שכשבא המן הרשע ומרדכי אמר להם ברחו לכם שלא תכוו בגחלתי אמרו אתך אנחנו בין לחיים ובין למות, שקבלו עליהם כל עונש שיהי' אך ורק שלא להפרד מהתורה. וזהו וקבל היהודים את אשר החלו לעשות, שבמתן תורה היתה רק ההתחלה ובזמן גזירת המן היתה הקבלה, כי ע\"י שהי' להם אז מס\"נ בפועל על תומ\"צ נתעלו (בענין אחד) למדריגה נעלית יותר מכמו שהיו בזמן מתן תורה, ולכן<sup data-n=\"505\">19</sup> אז דוקא היתה הקבלה, וקבל היהודים.\nב) <b>וצריך</b> להבין, הרי נקודת הביאור בהמאמר היא דזה שדוקא בזמן הגזירה היתה הקבלה הוא מצד המס\"נ שלהם, ומה נוגע כאן שהתעוררות המס\"נ שלהם היתה ע\"י מרדכי ושעיקר עבודתו של מרדכי היתה לימוד התורה עם תינוקות של בית רבן. וגם צריך ביאור במ\"ש בהדיוק (בהתחלת המאמר) דזה שבזמן מתן תורה היו ישראל בתכלית העילוי ובזמן הגזירה היו בתכלית השפלות, הוא הן ברוחניות והן בגשמיות. דלכאורה, להדיוק שבהמאמר, דהאיך יתכן שבזמן שהיו בתכלית העילוי היתה רק ההתחלה ובעת שהיו בתכלית השפלות אז דוקא היתה הקבלה, נוגע העילוי והשפלות במצב הרוחני שלהם, ולמה מביא בהמאמר שהעילוי שבזמן מתן תורה והשפלות שבזמן הגזירה היו גם בגשמיות.\nג) <b>והנה</b> נוסף להדיוקים דלעיל, צריך להבין גם בתוכן הביאור (שבהמאמר) דזה שוקבל היהודים הי' בזמן הגזירה הוא מפני שאז הי' להם מס\"נ עלתומ\"צ, דלכאורה, הרי ברובם ככולם של המצוות כתיב<sup data-n=\"506\">20</sup> אשר יעשה אותם האדם וחי בהם, וגם בג' המצוות שנאמר בהם יהרג ואל יעבור<sup data-n=\"507\">21</sup> אינם ענין המס\"נ אלא שאופן קיומם הוא אפילו אם יהרג עי\"ז<sup data-n=\"508\">22</sup>, והמצוה דמס\"נ על קידוש השם היא רק מצוה אחת, ומהו ההכרח במס\"נ בשביל הקבלה (וקבל היהודים) דכללות התורה. ומ\"ש בתניא<sup data-n=\"509\">23</sup>, דהטעם על זה שצוה משה רבינו לדור שנכנסו לארץ לקרות ק\"ש פעמיים בכל יום לקבל עליו מלכות שמים במס\"נ (אף שהבטיח להם פחדכם ומוראכם יתן ה' וגו'<sup data-n=\"510\">24</sup>) הוא מפני שקיום התורה ומצוותי' תלוי בזה שיזכור תמיד ענין מסירת נפשו לה', הרי ענין המס\"נ שבו תלוי קיום התומ\"צ הוא מס\"נ בכח (שבאם יצטרך למס\"נ על קיום התומ\"צ הוא מוכן לזה) ולא מס\"נ בפועל, והרי גם במתן תורה, כשאמרו נעשה ונשמע (ומכ\"ש לאחרי שנצטוו לקרות ק\"ש פעמיים בכל יום) קיבלו עליהם לקיים כל מה שיצטוו גם באם יהי' צריך למס\"נ על זה, ואעפ\"כ, לא היתה קבלה גמורה (וקבל היהודים) עד לזמן גזירת המן, כשהי' להם מס\"נ בפועל<sup data-n=\"511\">25</sup>.\n<b>והנה</b> ידוע שבשני זמנים היתה מס\"נ בפועל [של כלל ישראל] על תומ\"צ, בחנוכה (בזמן גזירת יון) ובפורים (בזמן גזירת המן). וכיון שכל הענינים שבתורה הם בתכלית הדיוק, צריך לומר, דזה שהענין דוקבל היהודים הי' דוקא ע\"י המס\"נ דפורים, הוא (לא רק מפני שהמס\"נ דפורים היתה לפני המס\"נ דחנוכה, אלא גם) מפני שהמס\"נ דפורים שייכת יותר ל(גמר) קבלת התורה. וצריך להבין החילוק בין המס\"נ דחנוכה להמס\"נ דפורים<sup data-n=\"512\">26</sup>, שמפני חילוק זה, הגמר דקבלת התורה הוא דוקא ע\"י המס\"נ דפורים.\nד) <b>ויובן</b> זה בהקדים<sup data-n=\"513\">27</sup> הידוע<sup data-n=\"514\">28</sup> שהחידוש דמתן תורה לגבי התומ\"צ שהיו קודם מתן תורה, הוא שהמצוות של האבות (ובכלל – קודם מתן תורה) היו רק ברוחניות. דנוסף לזה שכו\"כ מצוות קיימו רק ברוחניות (כמו תפילין שנזכר בהםיציאת מצרים ואז עדיין לא הי' גלות מצרים), הנה גם בהמצוות שקיימו בגשמיות, היתה המשכת הקדושה רק ברוחניות ולא בדבר הגשמי שבו קיימו המצוה<sup data-n=\"515\">29</sup>. כי קודם מתן תורה היתה הגזירה דעליונים לא ירדו למטה ותחתונים לא יעלו למעלה<sup data-n=\"516\">30</sup>, ולכן לא הי' החיבור דקדושת המצוה (עליונים) עם הדבר הגשמי שבו נעשית המצוה (תחתונים), משא\"כ בקיום המצוות<sup data-n=\"517\">31</sup> שלאחרי מתן תורה, כשבטלה הגזירה והמחיצה שבין עליונים לתחתונים<sup data-n=\"516\">30</sup>, נעשה החיבור של דבר הגשמי (שבו מקיימים המצוה) עם קדושת המצוה, ועד שבכמה מצוות, נעשה הדבר הגשמי חפצא של מצוה<sup data-n=\"518\">32</sup>. וע\"פ הידוע<sup data-n=\"519\">33</sup> שהחיבור דשני דברים הפכים הוא על ידי ענין שלמעלה משניהם, מובן, שהחיבור דעליונים ותחתונים שנעשה במתן תורה הוא ע\"י שבמתן תורה היתה המשכת אוא\"ס שלמעלה מהגדר דמעלה ומטה (עליונים ותחתונים). ומכ\"ז מובן, שבהמצוות שלאחרי מתן תורה, ג' ענינים. התחתון [שהרי גם לאחרי מתן תורה, שהדבר הגשמי שבו מקיימים המצוה נעשה חפצא של מצוה, לא נהפך לרוחני ונשאר דבר גשמי], העליון [שהרי גם לאחרי מתן תורה, כשקדושת המצוה נמשכת ונקבעת בהדבר הגשמי, היא ענין רוחני], והביטול של גדרי העליון והתחתון, דזה שהעליון והתחתון מתחברים זה עם זה (עם היותם הפכים) הוא ע\"י ביטול הגדר שלהם, שנעשה ע\"י המשכת אוא\"ס שלמעלה משניהם. ויש לומר, שג' ענינים אלו יש דוגמתם גם בקיום המצוות. כשהאדם מקיים את המצוות בדרך מצות אנשים מלומדה<sup data-n=\"520\">34</sup>, היינו מחמת ההרגל שהורגל כן<sup data-n=\"521\">35</sup>, כיון שהרגל נעשה טבע<sup data-n=\"522\">36</sup>, קיום המצוות שלו הוא מצד טבע הגוף ונפש הטבעית, תחתון שבאדם<sup data-n=\"523\">37</sup>, וכשמקיים את המצוות מפני שאוהב את הוי' וחפץ לדבקה בו ואי אפשר לדבקה בו באמת כי אם בקיום רמ\"ח פיקודין שהם<sup data-n=\"524\">38</sup> רמ\"ח אברין דמלכא<sup data-n=\"525\">39</sup>, קיום המצוות שלו הוא מצד הנשמה (נפש האלקית), עליון שבאדם<sup data-n=\"523\">37</sup>. וכשמקיים את המצוות לשמן, לא מצד התועלת שתהי' לו עי\"ז (גם לא תועלת רוחנית) אלא מצד זה שמצוות הם רצונו ית', קיום המצוות שלו הוא לא מצד המציאות שלו (גם לא המציאות דהנשמה) אלא בביטול, שכל ענינו (בשעה שמקיים את המצוה) הוא רק לקיים רצון העליון.ה) <b>ויש</b> להוסיף, שהשרש דג' אופנים אלו בקיום המצוות, הוא, כי גם במצוות עצמם יש ג' ענינים (בדוגמת ג' האופנים שבקיום המצוות). והענין הוא, דנתינת המצוות (למטה) היא כמרז\"ל<sup data-n=\"526\">40</sup> לא ניתנו המצוות אלא לצרף בהן את הבריות. היינו, שהכוונה בנתינת המצוות היא (לא בשביל המצוות עצמם, אלא) בשביל הבירור והזיכוך של כחות ואברי האדם שמקיים את המצוה ובשביל הבירור והזיכוך של הדברים שבעולם שבהם מקיימים את המצוה<sup data-n=\"527\">41</sup>. ויש ענין נעלה יותר במצוות, שהם מצוותיו של הקב\"ה, כדרשת רז\"ל<sup data-n=\"528\">42</sup> עה\"פ<sup data-n=\"529\">43</sup> מגיד דבריו ליעקב חוקיו ומשפטיו לישראל, מה שהוא עושה הוא אומר לישראל לעשות, דזה שהקב\"ה מקיים את המצוות (<i>קודם</i><sup data-n=\"530\">44</sup> שאומר לישראל לעשות) הוא מצד עצמו (מצד למעלה). [וכמובן גם מזה שרמ\"ח פיקודין הם רמ\"ח אברין דמלכא<sup data-n=\"531\">45</sup>, דזה שהמצוות הם האברים שלו כביכול הוא מצד למעלה]. וע\"י שישראל עושים את המצוות שהוא עושה, הם הולכים בדרכיו של הקב\"ה<sup data-n=\"532\">46</sup> ודבוקים בו<sup data-n=\"533\">47</sup>, ועי\"ז נמשך חיות להאדם שמקיים המצוות, כמ\"ש<sup data-n=\"534\">48</sup> אשר יעשה אותם האדם וחי בהם, כי ע\"י עשיית המצוות הוא מתדבק בהקב\"ה (כנ\"ל), וע\"י ואתם הדבקים בהוי' אלקיכם (עי\"ז) חיים כולכם היום<sup data-n=\"535\">49</sup>. וכיון שענין זה שבמצוות (שהם דרכיו של הקב\"ה, עי\"ז שהקב\"ה עושה את המצוות) הוא למעלה משייכות לעולמות, לכן, גם החיות שנמשך להאדם שמקיים את המצוות הוא החיות דבחי' סובב, שמצד עצמו הוא קדוש ומובדל מעולמות ואעפ\"כ ע\"י קיום המצוות הוא חי בהם בחיות פנימי<sup data-n=\"536\">50</sup>. אמנם גם ענין זה שבמצוות, הוא בדרגא שיש בה ציור. ולכן המצוות שבדרגא זו הם בהתחלקות, דרכי הוי' (לשון רבים)<sup data-n=\"537\">51</sup>, רמ\"ח אברים דמלכא, דההמשכה שע\"י כל מצוה היא המשכה פרטית (דוגמת כח הראי' בעין וכח השמיעה באוזן). ולכן שייך שהאדם יעשה את המצוות שהקב\"ה עושה, כי רמ\"ח האברים שבאדם התחתון הם כביכול בדוגמת רמ\"ח אבריםדמלכא, נעשה אדם בצלמנו כדמותנו<sup data-n=\"538\">52</sup>. ויש ענין נעלה יותר במצוות, זה שהמצוות הם רצון העליון (רצון שלמעלה מהטעם), דהרצון שבמצוות הוא בכל תרי\"ג המצוות בשוה (למעלה מרמ\"ח אברים). וכיון שהרצון שבמצוות הוא למעלה באין ערוך מהאדם התחתון שמקיים את המצוה (במכ\"ש מזה שהוא למעלה מהציור דאדם העליון), לכן, לגבי<sup data-n=\"539\">53</sup> דרגא זו (כמו שהיא מצד עצמה) אין האדם תופס מקום, דהביטול דהעדר תפיסת מקום הוא ביטול במציאות<sup data-n=\"540\">54</sup>. וגם לאחרי שישנו הציווי להאדם שעי\"ז הוא נעשה מציאות, כל מציאותו היא רק למלאות את הציווי, וע\"י שהוא ממלא את הציווי הוא מתחבר (מצוה מלשון צוותא וחיבור<sup data-n=\"541\">55</sup>) עם המצווה (שהוא למעלה ממנו באין ערוך).\nו) <b>ועד\"ז</b> הוא בלימוד התורה, שיש בזה ג' אופנים אלו. דנוסף לג' האופנים שישנם במצות תלמוד תורה (כבכל המצוות), הנה גם בהענין דלימוד התורה עצמו ישנם (דוגמת) ג' אופנים אלו. דכשלומד תורה מצד החכמה והשכל שבה, שהתורה היא חכמתכם ובינתכם (אפילו) לעיני העמים<sup data-n=\"542\">56</sup>, לימוד התורה שלו הוא מצד טבע גופו ונפשו הטבעית, שבטבעו הוא אוהב מושכלות. וכשלימוד התורה שלו הוא מצד זה שהתורה היא ממוצע המקשר ישראל וקוב\"ה, כמאמר הזהר<sup data-n=\"543\">57</sup> תלת קשרין מתקשראן דא בדא ישראל אורייתא וקוב\"ה, דע\"י שישראל מתקשראן באורייתא הם מתקשרים בהקב\"ה, לימוד התורה שלו הוא מצד הנשמה שבו. היינו, שגם אופן זה בלימוד התורה הוא מצד מציאותו (שיהי' קשור בהקב\"ה) אלא שהוא המציאות דהנשמה. ויש אופן נעלה יותר בלימוד התורה, דזה שלומד תורה הוא (לא מפני העילוי שיהי' לו עי\"ז, אלא) מצד התורה עצמה. דמכיון שאורייתא וקוב\"ה כולא חד<sup data-n=\"544\">58</sup>, ויתירה מזו שהיא חד עם העצמות, כמארז\"ל<sup data-n=\"545\">59</sup> שאנכי הוא ר\"ת אנא נפשי כתבית יהבית, דאנא (נפשי) הוא עצמותו ית', ופירוש אנא נפשי כתבית יהבית הוא<sup data-n=\"546\">60</sup> אַז ער האָט אַריינגעשריבן און אַריינגעגעבן זיך אַליין, אנא נפשי, שע\"י התורה אותי אתם לוקחים<sup data-n=\"547\">61</sup>, לכן כמו שהקב\"ה אינו ח\"ו אמצעי לאיזה ענין אחר וה\"תכלית\" הוא בובעצמו, עד\"ז<sup data-n=\"548\">62</sup> הוא גם בלימוד התורה דהאדם, שנרגש אצלו שהתכלית דלימוד התורה שלו היא התורה עצמה. דזה שיודע שאורייתא וקוב\"ה כולא חד, פועל עליו שמוסר ונותן את עצמו ללימוד התורה בלי כל חשבונות (גם לא החשבון שעי\"ז יתקשר בהקב\"ה), ולימוד התורה שלו הוא בתכלית הביטול. וג' אופנים אלו שבלימוד התורה נמשכים מג' הענינים שבתורה עצמה, שהתורה היא חכמה ושכל (היינו שהיא חכמתו של הקב\"ה ואח\"כ ירדה ונתלבשה בשכל האדם<sup data-n=\"549\">63</sup>), שהתורה היא ממוצע המקשר ישראל בקוב\"ה, ושאורייתא וקוב\"ה כולא חד.\nז) <b>והנה</b> ג' ענינים הנ\"ל יש דוגמתם גם בדיני והלכות תלמוד תורה. דהחיוב ללמוד ההלכות הצריכות למעשה<sup data-n=\"550\">64</sup> בכדי לידע את המעשה אשר יעשה, הוא <i>ע\"ד</i> לימוד התורה שמצד (טבע) הגוף ונפש הטבעית, מכיון שעשיית המצוות (כולל המצוות התלויות בדיבור<sup data-n=\"551\">65</sup>) הוא ע\"י הגוף ונפש החיונית<sup data-n=\"552\">66</sup>. והחיוב דמצות ידיעת התורה, לידע כל התורה כולה (גם הענינים שאינם צריכים למעשה), כיון שענינה של מצוה זו הוא <i>שהאדם</i> ידע את התורה, הוא ע\"ד לימוד התורה בשביל הנשמה. ויש לומר, שזהו הטעם על זה שיש שיעור וקצבה להמצוה דידיעת התורה [דמ\"ש<sup data-n=\"553\">67</sup> ארוכה מארץ מדה הוא שאין קץ לעומק טעמי ההלכות, אבל ההלכות עצמם וכן המדרשים וכו' יש להם קץ ומספר<sup data-n=\"554\">68</sup> והיו כמה וכמה שלמדו וידעו כל התורה כולה<sup data-n=\"555\">69</sup>], כי מכיון שהמצוה דידיעת התורה היא <i>שהאדם</i> ידע את התורה, והאדם הוא מוגבל, לכן גם התורה (ששייכת למצוה זו) היא במדידה והגבלה. והחיוב דוהגית בו יומם ולילה<sup data-n=\"556\">70</sup> [גם לאחרי שלמד כל התורה, ועד\"ז בנוגע לאלה שדעתם קצרה ולא יגיעו לידיעת כל התורה<sup data-n=\"557\">71</sup>] הוא החיוב דלימוד התורה מצד התורה עצמה. וכיון שהתורה (כמו שהיא מצד עצמה) היא למעלה ממדידה והגבלה (ארוכה מארץ מדה), לכן, גם המצוה דתלמוד תורה (כמו שהיא מצד התורה עצמה) היא שיעסוק בה תמיד יומם ולילה בכל רגע פנוי, למעלה ממדידה והגבלה<sup data-n=\"558\">72</sup>.\nח) <b>ויש</b> לומר בעומק יותר, שגם המצוה דוהגית בו יומם ולילה, כיון שהמצוות הם ציווים להאדם [ודלא כהתורה כמו שהיא חכמתו של הקב\"ה (שלמעלהמשייכות לעולם) ורק שאח\"כ ירדה למטה], הרי התורה שלומדים מצד <i>המצוה</i> דוהגית בו יומם ולילה היא (לא התורה כמו שהיא מצד עצמה, אלא) כמו ששייכת להאדם. ואמיתית הענין דלימוד התורה עצמה (כמו שהיא למעלה משייכות לאדם) הוא בלימוד התורה לשמה, שהלימוד הוא לא בכדי לקיים מצות תלמוד תורה אלא מצד התורה עצמה.\n<b>ויש</b> להוסיף שהמעלה בלימוד התורה לשמה לגבי הלימוד בכדי לקיים מצות ת\"ת הוא לא רק בכוונת הלימוד אלא גם בהלימוד בפועל. דכאשר הלימוד הוא בכדי לקיים מצות ת\"ת, הלימוד הוא בהגבלה, דגם במצות והגית בו יומם ולילה יש כו\"כ הגבלות כמבואר בהלכות ת\"ת. משא\"כ בלימוד התורה לשמה, אינו מתחשב במדידות והגבלות (אם גם באופן כזה הוא מחוייב ללמוד או לא<sup data-n=\"559\">73</sup>), והלימוד שלו הוא למעלה ממדידת והגבלת הזמן, ועד\"ז למעלה מהמדידה והגבלה דמקום כמרז\"ל<sup data-n=\"560\">74</sup> לאונסו שאני. והטעם לזה (בפנימיות הענינים) הוא, כי המצוה דוהגית היא ציווי להאדם, לכן יש בה הגבלות (לפי האדם). משא\"כ בלימוד התורה לשמה, מכיון שהתורה (כמו שהיא מצד עצמה) היא למעלה ממדידה והגבלה (ארוכה מארץ מדה), לכן, גם לימוד התורה של האדם, כשהלימוד שלו הוא לשמה (מצד התורה עצמה), הוא באופן שהוא יוצא מההגבלות דזמן ומקום.\nט) <b>ויש</b> לומר, שהחיבור דעליונים ותחתונים שנתחדש במתן תורה הוא מתגלה בעיקר בלימוד התורה לשמה. דנוסף על זה שבכדי שיוכל להיות החיבור דעליונים ותחתונים הוא ע\"י ביטול הגדר דעליון ותחתון ע\"י המשכת אוא\"ס שלמעלה משניהם (כנ\"ל סעיף ד), שדוגמתו באדם הוא כשעוסק בתורה לשמה שאז הוא בביטול המציאות הן בנוגע להגוף (תחתון) והן בנוגע להנשמה (עליון), הנה גם החיבור דעליונים ותחתונים עצמו מתגלה בלימוד זה, שהבל\"ג דתורה (עליונים) פועל על האדם (תחתונים) שלימוד התורה שלו יהי' למעלה מהגבלה. ויש להוסיף, דע\"י שהבל\"ג דתורה פועל גם בהאדם (ועד\"ז ע\"י ירידת התורה למטה בכלל), מתגלה הבל\"ג דתורה עוד יותר, דזה שהתורה היא בל\"ג הוא לא רק בהמקום והדרגא של התורה אלא שהיא נמשכת גם למטה<sup data-n=\"561\">75</sup> וגם בהמשכתה למטה נרגש בגילוי הבל\"ג שבה, שגם לימוד התורה של האדם הוא באופן דבל\"ג<sup data-n=\"562\">76</sup>.יו\"ד) <b>וע\"פ</b> כל הנ\"ל יש לומר הטעם על זה שגמר קבלת התורה (וקבל היהודים) תלוי במס\"נ, כי החיבור דעליונים ותחתונים הוא ע\"י ביטול הגדרים והמציאות דעליון ותחתון (כנ\"ל), ולכן, בכדי שתהי' השלימות דקבלת התורה, הוצרך להיות הביטול דמס\"נ. ואף שגם בשעת מתן תורה כשאמרו נעשה ונשמע קיבלו עליהם לעשות כל מה שיצטוו גם באם יהי' צריך למס\"נ על זה, הרי כל זמן שהמס\"נ היא בכח הוא מצד הנשמה ואינו בהגוף, וכיון שהביטול (שעל ידו נעשה החיבור דעליונים ותחתונים) צריך להיות הן בהעליון והן בהתחתון, לכן השלימות דקבלת התורה תלוי' במס\"נ בפועל, כי המס\"נ בפועל היא<sup data-n=\"563\">77</sup> בהגוף ונפש הטבעית.\n<b>ועפ\"ז</b> יובן גם המעלה במס\"נ דפורים על המס\"נ דחנוכה, כי גם המס\"נ בפועל היא בעיקר מצד הנשמה, אלא שהמס\"נ דהנשמה פועלת גם בהגוף ובנפש הטבעית, ומכיון שהגוף ונפש הטבעית (מצד ענינם) הם מציאות, לכן הגילוי דמתן תורה (החיבור דעליונים ותחתונים) שנמשך בהם ע\"י הביטול דמס\"נ שמצד הנשמה הוא דבר נוסף עליהם. וזוהי המעלה דהמס\"נ דפורים על המס\"נ דחנוכה, שבפורים היו בתכלית הביטול (והשפלות) גם מצד הגוף<sup data-n=\"564\">78</sup>, שהרי היו הפקר גמור להריגה לכל מי שירצה, ובדרך הטבע לא הי' דרך להנצל מזה. [ואף שהגזירה היתה רק על היהודים ובאם היו כופרים ח\"ו לא היו עושים להם כלום (כמובא לעיל סעיף א מתו\"א), מ\"מ, מכיון שהגזירה אז היתה לא על קיום התומ\"צ אלא על הגוף, להרוג ולאבד ח\"ו, נמצא, שהגופים שלהם היו אז בתכלית השפלות. דכאשר הגזירה היא על התומ\"צ (כמו בחנוכה<sup data-n=\"565\">79</sup> שהגזירה היתה להשכיחם תורתיך ולהעבירם מחוקי רצוניך<sup data-n=\"566\">80</sup>) שבאם יקיים תומ\"צ יהרגו אותו, אזי, הגוף (מצד <i>ענינו</i>) אינו כהפקר. משא\"כ כשהגזירה היא להרוג ולאבד ח\"ו אלא שיש לו אפשרות להנצל מהגזירה ע\"י שיכפור ח\"ו, מכיון שהגזירה להרוג אותו היא (לא מפני שאינו רוצה לכפור, אלא) על הגוף, נמצא שהגוף (מצד <i>ענינו</i>) הוא כהפקר<sup data-n=\"567\">81</sup>].\n<b>וזהו</b> מה שע\"י המס\"נ דפורים דוקא הי' הגמר והשלימות דקבלת התורה, כי ע\"י שהביטול שלהם אז הי' גם מצד הגוף, לכן היו כלים להגילוי דמתן תורה הן מצד הנשמה והן מצד הגוף. ויש לומר דזהו גם מ\"ש בהמאמר שבזמן הגזירה היוישראל בתכלית השפלות גם בגשמיות, כי בזה מרמז הטעם על זה שהיו אז כלים להגילוי דמתן תורה גם מצד הגוף.\nיא) <b>והנה</b> ע\"פ המבואר לעיל (סעיף ד) שבחיבור עליון ותחתון יש ג' ענינים – העליון, התחתון והביטול שלהם – מובן, שבכדי לזכות להגמר והשלימות דקבלת התורה אין מספיק הביטול דהנשמה ודהגוף, אלא צריך שתהי' גם המציאות שלהם, וכמו שהם בתכלית השלימות, ושהמציאות שלהם תהי' קשורה ומחוברת עם התורה. וע\"ד שנת\"ל (ס\"ו וס\"ח) שהמעלה דלימוד התורה לשמה היא לא רק בענין הביטול (שהלימוד שלו הוא לא בשביל השלימות שלו, גם לא בשביל השלימות דהנשמה) אלא גם זה שמציאותו של האדם הלומד (הנשמה והגוף) מתחברת עם התורה שעי\"ז הוא יוצא מהגבלותיו ומתעלה להבל\"ג דתורה. ויש לומר, דזהו שמביא בהמאמר שהתעוררות המס\"נ דישראל היתה ע\"י מרדכי, משה שבדורו, דלימוד התורה של מרדכי הי' בתכלית העילוי, וע\"י שעורר את ישראל ללמוד תורה במס\"נ [ובפרט שמרדכי הי' ראש הדור (ע\"ד משה) שממנו נמשך לכל האברים], המשיך בהם (לא רק ענין הביטול, אלא) גם העילוי דלימוד התורה כמו שהיא מצד השלימות דהאדם, השלימות דהנשמה ודהגוף.\n<b>ועפ\"ז</b> יש לבאר גם מה שמביא בהמאמר שמרדכי קיבץ כ\"ב אלף תינוקות של בית רבן, כי מעלה זו בלימוד התורה (שהיא מצד השלימות דהנשמה ודהגוף) היא בעיקר בתינוקות של בית רבן. ויובן זה ע\"פ מה שארז\"ל<sup data-n=\"568\">82</sup> אין העולם מתקיים אלא בשביל הבל תינוקות של בית רבן, אמר לי' רב פפא לאביי דידי ודידך מאי, א\"ל אינו דומה הבל שיש בו חטא להבל שאין בו חטא. דהגם שלימוד התורה של ר\"פ ואביי הי' (בודאי) לשמה בדרגות הכי נעלות ולימוד התורה דתינוקות של בית רבן הוא מצד יראת הרצועה<sup data-n=\"569\">83</sup>, אעפ\"כ, יש יתרון בהבל תינוקות של בית רבן, שעל הבל זה דוקא העולם מתקיים. וידוע הביאור בזה<sup data-n=\"570\">84</sup>, דהמעלה בהבל תשב\"ר הוא הן מצד נשמתם, שהיא קרובה יותר לאלקות מפני שזה מקרוב באה מעולם הרוחני, והן מצד הגוף שלהם שלא נתגשם כ\"כ באכו\"ש ובתאוות, כמבואר במק\"א בארוכה. ועפ\"ז יש לומר, דזה שמביא בהמאמר שבזמן הגזירה קיבץ מרדכי כ\"ב אלף תינוקות של בית רבן, הוא, בכדי לבאר שבלימוד התורה שהי' אז, הי' (לא רק הביטול דהנשמה ודהגוף, אלא) גם השלימות דהנשמה ודהגוף. [אלא שמעלת הנשמה דתינוקות של בית רבן אינה שייכת (כ\"כ) ללימוד התורה שלהם, מכיון שהלימוד שלהם הוא מפני יראת הרצועה (טבע הגוף) ולא מצד הנשמה, וגם אין בזה הביטול דמס\"נ, ולכן מביא בהמאמר שהלימוד דתינוקות של בית רבן הי' ע\"י מרדכי, שעי\"ז הי' גם לימוד התורה שלהם במס\"נ כמבואר בהמאמר]. ויש להוסיף, דע\"י שמרדכיקיבץ כ\"ב אלף תינוקות של בית רבן נתוסף אצלו העילוי דהבל תינוקות של בית רבן<sup data-n=\"571\">85</sup>, ועי\"ז<sup data-n=\"572\">86</sup> המשיך ענין זה גם בכל היהודים שבדורו.\nיב) <b>ועפ\"ז</b> יש לבאר גם מה שחייב אינש לבסומי בפוריא עד דלא ידע<sup data-n=\"573\">87</sup>, כי בימי הפורים בכל שנה ושנה חוזר וניעור הענין דוקבל היהודים כמו שהי' בפעם הראשונה, ואדרבא – באופן דמעלין בקודש<sup data-n=\"574\">88</sup>. [ויש להוסיף, שהחידוש בימי הפורים לגבי מתן תורה הוא בשני ענינים. שבימי הפורים הי' הגמר והשלימות דקבלת התורה (וקבל היהודים), כנ\"ל בארוכה, וגם קיום התורה, כדאיתא בגמרא<sup data-n=\"575\">89</sup> עה\"פ<sup data-n=\"576\">90</sup> קיימו וקבלו היהודים קיימו מה שקבלו כבר, דזה שקבלו במתן תורה לא הי' באופן דקיום נצחי, דלאחרי שחטאו בעגל התנצלו את עדים<sup data-n=\"577\">91</sup>, ובימי הפורים כתיב<sup data-n=\"578\">92</sup> וימי הפורים האלה לא יעברו גו' וזכרם לא יסוף מזרעם, דזה שקבלו בפורים קיים בקיום נצחי<sup data-n=\"579\">93</sup>. ועד\"ז הוא בימי הפורים בכל שנה ושנה, שיש בזה שני ענינים אלה. שבכל שנה ניתוסף בהשלימות דקבלת התורה (כנ\"ל), ושגם הוספה זו יש לה קיום נצחי]. ולכן בפורים צ\"ל העבודה דלא ידע, אַרויסגיין פון זיך, כי השלימות דקבלת התורה באה ע\"י הביטול. וזהו גם שהיציאה ממציאותו (עד דלא ידע) צריכה להיות ע\"י לבסומי ביין<sup data-n=\"580\">94</sup> (גשמי), כי הביטול (דפורים) צריך להיות גם מצד הגוף, כנ\"ל בארוכה. ומזה נמשך הנתינת כח על כל השנה, שעניני הגוף לא יתפסו מקום אצלו ובמילא לא תהי' מניעה מצד הגוף ללימוד התורה.\n<b>וע\"פ</b> מה שנת\"ל דמעלת לימוד התורה לשמה היא לא רק בענין הביטול אלא גם שהלימוד של האדם הוא באופן דבל\"ג, יש לומר, שעד\"ז הוא גם בעד דלא ידע, שזה פועל (אח\"כ) עלי' גם בהידיעה [דלימוד התורה צ\"ל בהבנה והשגה דוקא], שמבין בשכלו ענינים בתורה שקודם לא הי' שייך לזה. וכמו שביאר כ\"ק מו\"ח אדמו\"ר באחת השיחות דפורים<sup data-n=\"581\">95</sup>, שע\"י שמגיעים לדרגת לא ידע, הידע שאח\"כ הוא באופן אחר לגמרי. ובכללות הוא שהשכל המוגבל של האדם מתאחד עם התורה שלומד הבלתי מוגבלת, ועי\"ז נעשה חד גם עם קוב\"ה, ישראל אורייתא וקוב\"ה כולא חד.\n**********",[["486","*","יצא לאור ב<b>קונטרס פורים – תשמ\"ט</b>, \"לקראת ימי הפורים . . <i>ז' אד\"ש תשמ\"ט</i>\"."],["487","1","אסתר ט, כג."],["488","2","שנאמר \"ה' תשא פורים קטן, רפ\"ז\" (כותרת המאמר בסה\"מ תרפ\"ז (ועד\"ז ב\"התמים\") שבהערה הבאה)."],["489","3","בקונטרס פורים שנה זו (ה'תשי\"א). נדפס אח\"כ גם בסה\"מ ה'תשי\"א ע' 180 ואילך. תרפ\"ז ע' קי ואילך. ולפני זה – ב\"התמים\" חוברת ז לה, ג [שלו, ג] ואילך."],["490","4","וכ\"ה גם ברד\"ה זה ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370397\" data-slug=\"torah-or\" data-id=\"3901370397\">תו\"א (מג\"א צו, ג</a>) ובשערי אורה (שער הפורים פח, ב). וכ\"ה גם ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370438\" data-slug=\"torah-or\" data-id=\"3901370438\">תו\"א שם צ, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370241\" data-slug=\"torah-or\" data-id=\"3901370241\">צח, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370438\" data-slug=\"torah-or\" data-id=\"3901370438\">שערי אורה נד, א</a>. רד\"ה זה תרע\"ח (סה\"מ תרע\"ח ע' קצו). ובכ\"מ.\nולהעיר, שבתו\"א שם (צח, א) ובהמאמר דתרפ\"ז (בתחלתו) שהוא ע\"ד שארז\"ל (שבת פח, א) עה\"כ (אסתר ט, כז) קיימו וקבלו היהודים קיימו מה שקבלו כבר [אף שלכאורה הם שני ענינים, ד\"וקבל היהודים את אשר החלו\" הוא שרק בפורים היתה הקבלה, משא\"כ \"קיימו מה שקבלו\" הוא שגם במ\"ת היתה הקבלה* אלא שלא הי' לה קיום. וראה לקמן סי\"ב]. ובשערי אורה שם (בשני המקומות), ועד\"ז ברד\"ה זה תרע\"ח, הובא פירוש זה עצמו (עה\"פ וקבל היהודים) בשם \"ארז\"ל\"."],["491","5","הביאור בדיוק לשון זה – ראה ד\"ה וקבל היהודים דפורים קטן ה'תשל\"ח ס\"א (לעיל ע' מד)."],["492","6","ראה שמו\"ר פמ\"א, ז. ויק\"ר פי\"ח, ג. זח\"ב קיג, סע\"ב ואילך. וראה גם עירובין נד, א."],["493","7","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו</a> שהגילוי דמתן תורה הי' מעין הגילוי דלע\"ל."],["494","8","לשון הכתוב – ישעי' ס, ב."],["495","9","ולהעיר ממחז\"ל (חולין קלט, ב) \"אסתר מן התורה מנין [דכתיב (וילך לא, יח)] ואנכי <i>הסתר אסתיר</i>\". ולהעיר, שאפילו לאחרי הנס דפורים (מכיון שהנס הי' מלובש בטבע) נק' כנס\"י בשם אסתר מלשון הסתר אסתיר (ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370409\" data-slug=\"torah-or\" data-id=\"3901370409\">תו\"א שם צ, ד</a> ואילך). ומכ\"ש בזמן הגזירה."],["496","10","אסתר ג, יג."],["497","11","בפ\"ג ואילך.\n*) <i>ואולי יש לומר</i>,<i> שלכן מדייק בהדרושים (<a class=\"ft-cite\" href=\"#/read/torah-or/3901370432\" data-slug=\"torah-or\" data-id=\"3901370432\">תו\"א שם צ</i>,<i> א</a> (<a class=\"ft-cite\" href=\"#/read/torah-or/3901370442\" data-slug=\"torah-or\" data-id=\"3901370442\">ועד\"ז שם צו</i>,<i> ג</a></i>.<i> <a class=\"ft-cite\" href=\"#/read/torah-or/3901370241\" data-slug=\"torah-or\" data-id=\"3901370241\">צט</i>,<i> סע\"א</a>)</i>.<i> שערי אורה שם נד</i>,<i> א (ועד\"ז שם פח</i>,<i> ב</i>.<i> צ</i>,<i> ב)</i>.<i> סה\"מ תרע\"ח שם) דפירוש </i>\"<i>וקבל היהודים את אשר החלו</i>\"<i> הוא שבימי מרדכי הי' </i><b>גמר</b><i> הקבלה</i>."],["498","12","שם צא, ב. צז, א. צט, ב. וכ\"ה בשערי אורה שם ס\"ח (צ, ב). סד\"ה וקבל תרע\"ח (סה\"מ תרע\"ח ע' רד). ד\"ה חייב אינש עטר\"ת ס\"ד (סה\"מ עטר\"ת ע' שו). תרפ\"א (ה'תש\"ח) ס\"ה (סה\"מ תרפ\"א ע' קצא. ה'תש\"ח ע' 118). ד\"ה בלילה ההוא ה'ש\"ת פ\"ה (סה\"מ ה'ש\"ת ע' 9). ועוד. וכ\"ה במגילת סתרים עה\"פ אסתר שם."],["499","13","שזהו חידוש גדול יותר, כי בנוגע לאמונה, גם קל שבקלים מוסר נפשו (תניא פי\"ח. ובכ\"מ)."],["500","14","דנוסף לזה שאתפשטותא דמשה בכל דרא (תקו\"ז תס\"ט – קיב, א. קיד, א), ומרדכי הי' האתפשטותא דמשה שבדורו (ראה בהמאמר פט\"ו) – איתא במדרש (אסת\"ר פ\"ו, ב. הובא בהמאמר פ\"ג) שהי' מרדכי שקול בדורו כמשה בדורו."],["501","15","ראה בהמאמר פ\"ג ופט\"ו."],["502","16","פ\"ב. וראה גם שם פ\"א ופט\"ו."],["503","17","ראה אסת\"ר פ\"י, ד. יל\"ש אסתר רמז תתרנח. ויק\"ר (פכ\"ח, ו) ויל\"ש אמור (רמז תתרמג) עה\"פ (אמור כג, יא) והניף את העומר. פס\"ר פי\"ח (פ' העומר)."],["504","18","ראה אסת\"ר פ\"ט, ד. יל\"ש אסתר רמז תתרנז."],["505","19","וכ\"ה גם ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370434\" data-slug=\"torah-or\" data-id=\"3901370434\">תו\"א ד\"ה זה (צז, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370407\" data-slug=\"torah-or\" data-id=\"3901370407\">שם</a>, סע\"ד) ובשערי אורה ד\"ה זה ס\"ח (צ, ב). ד\"ה יביאו לבוש מלכות פט\"ו (נט, ב)."],["506","20","אחרי יח, ה. וראה רמב\"ם הל' יסוה\"ת פ\"ה ה\"א (מיומא פה, ב. סנהדרין עד, א. תוספתא שבת ספט\"ז) \"וחי בהם ולא שימות בהם\"."],["507","21","רמב\"ם שם ה\"ב (מיומא פב, א. סנהדרין ותוספתא שם)."],["508","22","ראה בארוכה סה\"מ ה'תש\"ט ע' 123 בהערה."],["509","23","פכ\"ה (לב, סע\"א ואילך)."],["510","24","עקב יא, כה."],["511","25","בשערי אורה שם (סא, א. צ, ב) דזה שהקבלה שבמתן תורה נגמרה ע\"י המס\"נ בפועל שהי' בימי הפורים (אף שגם כשאמרו נעשה ונשמע \"בודאי נכון הי' לבבם למסור נפשם בפו\"מ\") הוא מצד המעלה דמס\"נ בפועל ש\"מגיע למעלה מעלה מאד נעלה גם מתו\"מ\". אבל צריך ביאור, מדוע צריך בשביל קבלת התורה להגיע לדרגא <i>שלמעלה</i> מתומ\"צ."],["512","26","בשערי אורה בהקדמה שהמס\"נ דפורים הי' מצד \"כח המשפיע\" והמס\"נ דחנוכה \"מצד המקבל\". אבל לכאורה חילוק זה אינו ביאור על זה ש\"וקבל\" הי' ע\"י המס\"נ דפורים דוקא. וע\"פ המבואר ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370443\" data-slug=\"torah-or\" data-id=\"3901370443\">תו\"א שם (צט, ב</a> ואילך) ובשערי אורה שם (צז, א ואילך) דזה שבמ\"ת הי' רק \"החלו לעשות\" הוא מפני שהמס\"נ אז הי' מפני הגילוי דלמעלה משא\"כ המס\"נ דפורים – מכיון שהמס\"נ דחנוכה הי' \"מצד המקבל\", הי' ראוי לכאורה שעל ידה יהי' \"וקבל\"."],["513","27","ראה גם רד\"ה וקבל ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370397\" data-slug=\"torah-or\" data-id=\"3901370397\">תו\"א (צו, ג</a>) ובשערי אורה (פח, ב), שענין זה (שבימי אחשורוש קבלו מה שהחלו במתן תורה) יובן בהקדים תחלה ענין מתן תורה."],["514","28","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051100\" data-slug=\"likkutei-sichot\" data-id=\"1300051100\">לקו\"ש ח\"ה ע' 88</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051091\" data-slug=\"likkutei-sichot\" data-id=\"1300051091\">שם ע' 79</a>. וש\"נ."],["515","29","ראה סה\"מ ה'תש\"י ע' 223 ובהערות שם."],["516","30","שמו\"ר פי\"ב, ג. תנחומא וארא טו."],["517","31","<i>ועד\"ז</i> הוא בתורה, שדוקא במתן תורה ניתן הכח שלימוד התורה יפעול שינוי בהאדם הלומדה – ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161214\" data-slug=\"likkutei-sichot\" data-id=\"1300161214\">לקו\"ש חט\"ז ע' 214</a>. אלא שעיקר ענין זה הוא במצוות – ראה הדרן על הש\"ס (בתורת מנחם – הדרנים על הרמב\"ם וש\"ס ע' תיח) הערה 31."],["518","32","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161213\" data-slug=\"likkutei-sichot\" data-id=\"1300161213\">לקו\"ש שם ע' 213</a> הערה 16."],["519","33","אגה\"ק סי\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380174\" data-slug=\"likkutei-torah\" data-id=\"4001380174\">לקו\"ת תזריע כג, ג</a>. ובכ\"מ."],["520","34","ישעי' כט, יג."],["521","35","<a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא פל\"ט (נג, ב</a>)."],["522","36","<a class=\"ft-cite\" href=\"#/read/tanya/3401310049\" data-slug=\"tanya\" data-id=\"3401310049\">תניא פמ\"ד (סג, ב</a>). וראה גם שם ספי\"ד. פט\"ו (כא, א). שבילי אמונה נתיב ד שער ב. שו\"ת הרמ\"ע מפאנו סל\"ו."],["523","37","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370013\" data-slug=\"torah-or\" data-id=\"3901370013\">ראה ב</a>\"ר פ\"ח, יא. פי\"ב, ח. וראה תו\"א בראשית ג, ד ואילך. קונטרס ומעין מאמר טו. המשך תרס\"ו ע' תצה. ובכ\"מ."],["524","38","ראה תקו\"ז ת\"ל (עד, סע\"א). הובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310028\" data-slug=\"tanya\" data-id=\"3401310028\">תניא</a> שבהערה הבאה. שם רפכ\"ג. ועוד."],["525","39","<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא פ\"ד</a>."],["526","40","תנחומא שמיני ח (וראה שם ז). ב\"ר רפמ\"ד. וש\"נ. וראה מו\"נ ח\"ג פכ\"ו."],["527","41","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז</a>."],["528","42","שמו\"ר פ\"ל, ט. וראה גם ירושלמי ר\"ה פ\"א ה\"ג."],["529","43","תהלים קמז, יט."],["530","44","ומכיון שלמעלה הוא למעלה מהזמן – הפירוש ד\"קודם\" הוא קדימה <i>במעלה</i>."],["531","45","ולהעיר שבכ\"מ מובא ענין זה (שרמ\"ח פיקודין הן רמ\"ח אברין דמלכא) בהמשך לזה שהקב\"ה מקיים את המצוות (<a class=\"ft-cite\" href=\"#/read/torah-or/3901370160\" data-slug=\"torah-or\" data-id=\"3901370160\">תו\"א מקץ לד, ד</a>. שערי אורה שם פכ\"ט (צד, ב). ועוד)."],["532","46","כידוע שמצוות נק' דרכי הוי' (הושע בסופו. נזיר כג, א. הוריות יו\"ד, ב. וראה גם זהר ח\"א קעה, ב \"ואינון ארחין ושבילין דאורייתא\". ובכ\"מ). וכבר דובר כמ\"פ (ראה לעיל ח\"א ע' רנה. לקו\"ש חל\"ד ע' 153 ואילך) דפירוש \"ללכת בכל דרכיו\" (עקב יו\"ד, יב) הוא עשיית המצוות. וזה שארז\"ל שפירוש \"ללכת בכל דרכיו\" קאי על <i>מדותיו</i> של הקב\"ה (מה הוא רחום כו') הוא עה\"פ שבס\"פ עקב (יא, כב)."],["533","47","להעיר מפרש\"י עה\"פ ובו תדבקון (ראה יג, ה) \"הדבק בדרכיו . . כמו שעשה הקב\"ה\", היינו שע\"י הדביקות בדרכיו \"כמו שעשה הקב\"ה\" – עי\"ז \"<i>ובו</i> תדבקון\"."],["534","48","אחרי יח, ה. וב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381137\" data-slug=\"likkutei-torah\" data-id=\"4001381137\">לקו\"ת שה\"ש ב, א</a> [ועד\"ז בדרך חיים פע\"ה (פב, א ואילך)] \"וחי בהם – שמקבל מהם חיות\"."],["535","49","ואתחנן ד, ד. וראה אדר\"נ ספל\"ד."],["536","50","להעיר מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310051\" data-slug=\"tanya\" data-id=\"3401310051\">תניא פמ\"ו (סו, א</a>) בפירוש אשר קדשנו במצותיו, \"שהיא קדושתו של הקב\"ה בכבודו ובעצמו . . מה שהקב\"ה הוא מובדל מהעולמות . . בחי' סובב . . (ואעפ\"כ) היא (נפש האדם שמקיים המצוה) במעלת ומדריגת קדושת א\"ס ב\"ה ממש מאחר שמתייחדת ומתכללת בו ית' והיו לאחדים ממש\"."],["537","51","ולהעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380803\" data-slug=\"likkutei-torah\" data-id=\"4001380803\">לקו\"ת ראה כא, ד</a> בענין תרי\"ג ארחין."],["538","52","בראשית א, כו."],["539","53","בהבא לקמן (עד סוף הסעיף) ראה אגרות-קודש אדמו\"ר מוהריי\"צ ח\"י ע' שסט ואילך. סה\"מ תרח\"ץ, ה'ש\"ת וה'תש\"י שבהערה 55."],["540","54","ראה גם בהמאמר (ד\"ה וקבל תרפ\"ז) ספי\"ב ואילך."],["541","55","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380272\" data-slug=\"likkutei-torah\" data-id=\"4001380272\">לקו\"ת בחוקותי מה, ג</a>. דרך חיים שער התפלה (נב, סע\"ב). סה\"מ תרח\"ץ ע' נב. ה'ש\"ת ע' 73 ואילך. ה'תש\"י ע' 71 ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071030\" data-slug=\"likkutei-sichot\" data-id=\"1300071030\">לקו\"ש ח\"ז ע' 30</a> ואילך. לקו\"ת חוקת (נז, ד) בפי' \"אשר צוה\". וראה בהמאמר פ\"ד בפי' \"ואתה תצוה\" \"דציווי הוא צוותא וחיבור שהוא ענין ההתקשרות\". וראה פע\"ח שער כט (שער הלולב וד' מיניו) פ\"ג: יצוה, כשאמרז\"ל (ברכות ו, סע\"ב) כל העולם כולו לא נברא אלא לצוות לזה שהוא לשון חיבור."],["542","56","ואתחנן ד, ו."],["543","57","ראה זח\"ג עג, א. וראה סה\"מ תרנ\"ז ס\"ע כח."],["544","58","<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא פ\"ד</a> ורפכ\"ג בשם הזהר. וראה הנסמן במאמרי אדהאמ\"צ ויקרא ח\"א ע' רפה. וראה זהר ח\"א כד, א. ח\"ב ס, א. תקו\"ז ת\"ו (כא, ב). תכ\"ב (סד, א). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380903\" data-slug=\"likkutei-torah\" data-id=\"4001380903\">לקו\"ת נצבים מו, א</a>. ועוד."],["545","59","שבת קה, א (כגירסת העין יעקב)."],["546","60","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380507\" data-slug=\"likkutei-torah\" data-id=\"4001380507\">לקו\"ת שלח מח, סע\"ד</a> ואילך."],["547","61","ראה שמו\"ר פל\"ג, א. שם, ו. תנחומא תרומה ג. תניא פמ\"ז. לקו\"ת שם."],["548","62","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191195\" data-slug=\"likkutei-sichot\" data-id=\"1300191195\">לקו\"ש חי\"ט ע' 182</a>."],["549","63","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא פ\"ד</a>."],["550","64","שיש להם דין קדימה על שאר כל ההלכות שאין צריך למעשה כ\"כ – הל' ת\"ת לאדה\"ז פ\"ב ה\"ט."],["551","65","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז (מז, א</a>). אבל ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ה (מה, א</a>) באופן אחר. ואכ\"מ."],["552","66","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/tanya/3401310040\" data-slug=\"tanya\" data-id=\"3401310040\">תניא פל\"ה</a> שם."],["553","67","איוב יא, ט."],["554","68","הלכות ת\"ת שם פ\"א ה\"ה."],["555","69","ראה מנחות צט, ב. קו\"א להל' ת\"ת שם פ\"ג ה\"א אות א (ע' 1686 [תתמג, ב])."],["556","70","יהושע א, ח. וראה בארוכה קו\"א שם דמצות ידיעת התורה ומצות והגית בו הם <i>שני</i> ענינים.\nבקו\"א שם שמצוות ידיעת התורה <i>עדיפא</i> ממצות והגית, אבל אין מזה סתירה למ\"ש בפנים, כי זה שמצות ידיעת התורה עדיפא הוא בנוגע לזה שאינה נדחית מפני מצוה אחרת."],["557","71","ראה הל' ת\"ת שם פ\"ג ה\"ג וד'."],["558","72","ואף שמבואר בהל' ת\"ת שם (פ\"ג) שיש כמה אופנים בקיום מצות והגית, ועד שבשעת הדחק קיים מצות והגית ע\"י ק\"ש שחרית וערבית (הל' ת\"ת שם פ\"ג ה\"ד) – הרי החילוקים הם רק כשהוא טרוד בפרנסה, אבל בנוגע לזמן הפנוי – המצוה דוהגית היא בכל רגע."],["559","73","ראה בארוכה לקו\"ש ח\"ב ע' 304 ואילך. ולהעיר מקו\"א שם (ע' 1688 [תתמד, ב]) בפירוש מרז\"ל (אבות פ\"ו, ד) \"כך היא דרכה של תורה כו' חיי צער תחי'\" שאין זה חיוב \"אלא שזו דרכה של תורה דוקא\", דלכאורה י\"ל הכוונה, דענין זה אינו מצד <i>מצות</i> תלמוד תורה אלא \"דרכה של <i>תורה</i>\". אבל ראה שם פ\"ג ה\"ג בתחלתה \"מי שנשאו לבו לקיים <i>מצוה</i> זו כראוי . . חיי צער תחי'\"."],["560","74","קידושין לג, א. הל' ת\"ת שם ספ\"ג."],["561","75","וע\"ד החילוק שבין הא\"ס שבאצילות להא\"ס שלמעלה מאצילות, דזה שהאור דאצילות א\"ס להתפשטותו \"הוא באצילות גופא ואינו יורד ומתגלה חוץ לאצילות\" ואוא\"ס שלמעלה מאצילות הוא \"בבחי' א\"ס להתפשטותו ממש שנמשך בכל ההשתלשלות\" (המשך תרס\"ו ע' תק ואילך)."],["562","76","וזה שהאדם נשאר במציאותו (גבול) ואעפ\"כ לימוד התורה שלו הוא למעלה מהגבלה – עי\"ז מתגלה עוד יותר הבל\"ג דתורה. וע\"ד המבואר בהמשך תרס\"ו שם (ס\"ע תקא) ש\"אמיתית ענין א\"ס להתפשטותו (הוא) שבכל מקום הוא מאיר בגילוי ממש ומ\"מ העולמות הן במדריגתן שנתהוו\"."],["563","77","ראה שערי אורה שער החנוכה ד\"ה בכ\"ה בכסליו פי\"ט (ח, סע\"א) ואילך. וראה בארוכה ד\"ה והי' עקב ה'תשכ\"ז ס\"ה (לקמן ח\"ד ע' קצא ואילך). <i>וש\"נ</i>."],["564","78","ראה בארוכה שערי אורה ד\"ה וקבל פי\"א (אלא שהביאור שם הוא באופן אחר)."],["565","79","ראה לבוש או\"ח הל' חנוכה סתר\"ע ס\"ב, הובא בט\"ז שם סק\"ג."],["566","80","נוסח הודאת \"ועל הנסים\" דחנוכה."],["567","81","להעיר שהחילוק בין שני אופנים אלו הוא גם בהלכה: גם מי שנאמר בו יהרג ואל יעבור, כשעבר באונס אין עונשין אותו (רמב\"ם הל' יסוה\"ת פ\"ה ה\"ד), ואעפ\"כ כשעבר ונתרפא – במקום סכנה – בע\"ז ג\"ע וש\"ד עונשים אותו (שם ה\"ו), ומהטעמים לזה, כי בחולה, האונס אינו על העבירה, ועושה ברצון (ראה בארוכה \"תשובות וביאורים\" ע' 14 [אגרות-קודש ח\"א ע' רלו] בהערות. וראה שם עוד דוגמאות לזה).\nועפ\"ז יש להוסיף עוד ביאור במעלת המס\"נ דפורים על המס\"נ דחנוכה – שאז בא בגילוי שענין התומ\"צ נוגע לעצם מציאותם, ועד שבאם היו עוברים ח\"ו היו נענשים על זה – ראה שיחת פורים שנה זו ס\"ד (תורת מנחם – התוועדויות ח\"ב ס\"ע 299 ואילך)."],["568","82","שבת קיט, ב."],["569","83","ראה תניא קו\"א סד\"ה להבין מ\"ש בשער היחודים (קנה, א)."],["570","84","דרך חיים פע\"ו (פב, ד)."],["571","85","וע\"ד המבואר בהמאמר ספ\"ה \"דעל ידי רגלי העם . . נתוסף אור במשה\"."],["572","86","להעיר ממ\"ש בהמאמר בסופו \"עמד מרדכי . . והקהיל קהלות ברבים לחזק אמונתם בהוי' (אמונתם של ישראל בכלל) <i>ע\"י לימוד תינוקות של בית רבן</i>\"."],["573","87","מגילה ז, ב. וראה סה\"מ תרפ\"א ע' קעט הערה 1."],["574","88","ברכות כח, א. וש\"נ."],["575","89","שבת פח, א."],["576","90","אסתר ט, כז."],["577","91","תשא לג, ו. שבת שם."],["578","92","אסתר שם, כח."],["579","93","ראה בארוכה שערי אורה ד\"ה וקבל פ\"כ (צד, א)."],["580","94","פרש\"י מגילה שם."],["581","95","ראה שיחת פורים תש\"ו ס\"ב (סה\"ש תש\"ו ס\"ע 23 ואילך)."]]]]});
